window.HS_LOAD(1,{"intro":[[["صحابہ کرامؓ کس طرح غیب پر ایمان لایا کرتے تھے اور نبی کریم ",""],["ﷺ","a"],[" کی بتائی ہوئی خبروں کے مقابلہ میں فانی لذتوں، انسانی مشاہدوں، وقتی محسوسات اور مادی تجربوں کو چھوڑ دیتے تھے اور ایسا معلوم ہوتا تھا کہ گویا انہوں نے غیبی امور کو اپنی آنکھوں سے دیکھ لیا تھا اور اپنے مشاہدات کو وہ جھٹلا دیا کرتے تھے۔",""]]],"topics":{"1":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ ایک دن ہم لوگ حضور ",""],["ﷺ","a"],[" کے اردگرد بیٹھے ہوئے تھے اور چند ساتھیوں سمیت حضرت ابوبکرؓ اور حضرت عمرؓ بھی ہمارے ساتھ تھے۔ حضورؐ ہمارے درمیان میں سے اٹھ کر چلے گئے، آپؐ کو واپس آنے میں کافی دیر ہو گئی۔ ",""],["ہمیں اس بات کا ڈر ہوا کہ ہم حضورؐ کے ساتھ نہیں ہیں، آپؐ اکیلے گئے ہیں، کہیں اس اکیلے پن میں آپؐ کو کسی دشمن کی طرف سے کوئی تکلیف نہ پہنچ جائے،","h"],[" اس وجہ سے ہم سب گھبرا کر کھڑے ہو گئے۔ سب سے پہلے میں گھبرا کر اٹھا اور حضورؐ کو تلاش کرنے نکلا۔ چلتے چلتے انصار کے قبیلہ بنو نجار کے ایک باغ کے پاس پہنچا اور میں نے اس باغ کا چکر لگایا تاکہ مجھے باغ کا کوئی دروازہ مل جائے لیکن مجھے کوئی دروازہ نہ ملا۔ پھر مجھے ایک نالی نظر آئی جو باہر کے ایک کنویں سے باغ کے اندر جاری تھی، میں سمٹ کر (اس نالی سے) اندر چلا گیا تو دیکھا کہ حضورؐ وہاں موجود تھے۔ حضورؐ نے فرمایا تم ابوہریرہ ہو؟ میں نے عرض کیا جی ہاں یا رسول ",""],["ٱللَّٰه","a"],["! حضورؐ نے فرمایا تمہیں کیا ہوا؟ میں نے عرض کیا آپؐ ہمارے درمیان تشریف فرما تھے پھر اٹھ کر چلے گئے پھر کافی دیر گزر گئی لیکن آپؐ واپس نہ آئے۔ ہمیں اس بات کا ڈر ہوا کہ آپؐ اکیلے ہیں، ہم میں سے کوئی آپؐ کے ساتھ نہیں تو اس اکیلے پن میں آپؐ کو کوئی تکلیف نہ پہنچ جائے، اس خیال سے ہم سب گھبرا گئے۔ سب سے پہلے میں گھبرا کر وہاں سے اٹھا اور آپؐ کو ڈھونڈنے لگ گیا، ڈھونڈتے ڈھونڈتے میں اس باغ تک پہنچ گیا (باغ کا دروازہ مجھے ملا نہیں اس لیے) میں لومڑی کی طرح سکڑ سمٹ کر (نالی سے) اندر آ گیا ہوں اور وہ تمام لوگ میرے پیچھے پیچھے آ رہے ہیں۔",""]]],["c",[["حضورؐ نے مجھے اپنے دو جوتے (نشانی کے طور پر) دے کر فرمایا: میرے یہ دونوں جوتے لے جاؤ اور اس باغ کے باہر تمہیں جو بھی گواہی دیتا ہوا ملے کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور وہ دل سے اس پر یقین کر رہا ہو اسے جنت کی بشارت دے دینا۔",""]]],["p",[["مجھے سب سے پہلے ",""],["حضرت عمرؓ","b"],[" ملے۔ انہوں نے پوچھا اے ابوہریرہ! یہ جوتے کیا ہیں؟ میں نے کہا یہ دونوں جوتے حضورؐ کے ہیں جنہیں دے کر حضورؐ نے مجھے بھیجا ہے کہ مجھے جو بھی یہ گواہی دیتا ہوا ملے کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور دل سے اس پر یقین کر رہا ہو میں اسے جنت کی بشارت دے دوں۔ ",""],["حضرت عمرؓ نے میرے سینے پر (اس زور سے) مارا کہ میں سرین کے بل زمین پر گر پڑا","h"],[" اور حضرت عمرؓ نے کہا اے ابوہریرہ! واپس جاؤ۔ میں حضورؐ کی خدمت میں واپس گیا اور رو کر فریاد کرنے لگا۔ حضرت عمرؓ میرے پیچھے پیچھے آئے۔ حضورؐ نے فرمایا اے ابوہریرہ! تمہیں کیا ہوا؟ میں نے عرض کیا مجھے حضرت عمرؓ باہر ملے تھے، جو بشارت دے کر آپؐ نے مجھے بھیجا تھا میں نے انہیں سنائی تو انہوں نے میرے سینے پر اس زور سے دو ہتھڑ مارا کہ میں سرین کے بل گر گیا اور انہوں نے مجھ سے کہا واپس چلے جاؤ۔ (اتنے میں حضرت عمرؓ بھی وہاں پہنچ گئے) حضورؐ نے حضرت عمرؓ سے فرمایا اے عمر! تم نے ایسا کیوں کیا؟ حضرت عمرؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے ماں باپ آپ پر قربان ہوں، کیا آپؐ نے اپنے دو جوتے دے کر حضرت ابوہریرہؓ کو واپس بھیجا ہے کہ انہیں جو آدمی اس بات کی گواہی دیتا ہوا ملے کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور دل سے اس کا یقین کر رہا ہو تو یہ اسے جنت کی بشارت دے دیں؟ حضورؐ نے فرمایا ہاں۔ حضرت عمرؓ نے عرض کیا آپؐ ایسا نہ کریں کیونکہ مجھے اس بات کا ڈر ہے کہ لوگ اس بشارت پر بھروسہ کر لیں گے اور (مزید نیک عمل کرنے چھوڑ دیں گے) آپؐ لوگوں کو عمل کرنے دیں۔ اس پر حضورؐ نے فرمایا اچھا انہیں عمل کرنے دو۔",""],[" (1)","s"]]]],"f":[["(1)","Muslim, as quoted in Jam'ul Fawaa'id (Vol.1 Pg.7)."]]},{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں کہ ایک رات میں باہر نکلا تو دیکھا کہ حضورؐ اکیلے جا رہے ہیں، آپؐ کے ساتھ کوئی نہیں ہے۔ میں نے اپنے دل میں کہا شاید آپؐ کو ساتھ چلنا گوارا نہ ہو، اس لیے میں ذرا فاصلے سے ایسی جگہ چلنے لگا جہاں چاند کی روشنی نہیں پڑ رہی تھی۔ اتنے میں حضورؐ نے مڑ کر مجھے دیکھا اور فرمایا کون ہے؟ میں نے عرض کیا ",""],["ٱللَّٰه","a"],[" مجھے آپ پر قربان کرے میں ابوذر ہوں۔ آپؐ نے فرمایا اے ابوذر! ادھر آؤ۔ میں کچھ دیر آپؐ کے ساتھ چلا پھر آپؐ نے فرمایا:",""]]],["c",[["زیادہ مال والے قیامت کے دن کم ثواب والے ہوں گے، البتہ جس کو ",""],["ٱللَّٰه","a"],[" نے خوب مال دیا اور اس نے دائیں بائیں آگے پیچھے مال خوب لٹایا اور نیکی کے کاموں میں خوب خرچ کیا تو وہ مالدار بھی قیامت کے دن زیادہ اجر و ثواب والا ہوگا۔",""]]],["p",[["پھر حضورؐ کے ساتھ تھوڑی دیر اور چلا۔ اس کے بعد آپؐ نے مجھ سے فرمایا تم یہاں بیٹھ جاؤ اور حضورؐ نے مجھے ایک وسیع ہموار میدان میں بٹھا دیا جس کے اردگرد پتھر ہی پتھر تھے۔ آپؐ نے مجھ سے فرمایا میرے واپس آنے تک یہیں بیٹھے رہنا۔ یہ فرما کر حضورؐ نے ایک پتھریلے میدان میں چلنا شروع کر دیا اور چلتے چلتے اتنی دور چلے گئے کہ مجھے نظر نہیں آ رہے تھے، پھر کافی دیر کے بعد آپؐ واپس آئے تو میں نے دور سے سنا کہ آپؐ فرما رہے تھے: اگرچہ وہ زنا کرے اور چوری کرے۔ جب آپؐ میرے پاس پہنچ گئے تو مجھ سے رہا نہ گیا اور میں نے آپؐ سے پوچھا اے ",""],["ٱللَّٰه","a"],[" کے نبی! ",""],["ٱللَّٰه","a"],[" مجھے آپ پر قربان کرے آپ اس پتھریلے میدان میں کس سے باتیں کر رہے تھے؟ مجھے تو آپ کی باتوں کا جواب دیتا ہوا کوئی سنائی نہ دیا۔ حضورؐ نے فرمایا:",""]]],["c",[["یہ جبرائیل علیہ السلام تھے جو اس پتھریلے میدان کے کنارے میں میرے سامنے آئے تھے اور انہوں نے کہا تھا آپ اپنی امت کو یہ خوشخبری سنا دیں کہ جو اس حال میں مرے کہ وہ ",""],["ٱللَّٰه","a"],[" کے ساتھ کسی کو شریک نہ کرتا ہو وہ جنت میں داخل ہوگا۔",""]]],["p",[["میں نے کہا اے جبرائیل! اگرچہ وہ زنا کرے اور چوری کرے؟ حضرت جبرائیل نے عرض کیا جی ہاں۔ (حضرت ابوذرؓ فرماتے ہیں کہ) میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! اگرچہ وہ چوری کرے اور زنا کرے؟ حضورؐ نے فرمایا جی ہاں! اگرچہ وہ شراب پیئے۔",""],["(2)","s"],[" بخاری، مسلم اور ترمذی کی اس جیسی ایک روایت میں یہ ہے کہ حضورؐ نے چوتھی مرتبہ میں فرمایا چاہے ابوذر کی ناک خاک میں مل جائے۔ (یعنی ایسا ہی ہوگا اگرچہ ابوذر کی رائے یہ ہے کہ ایسا نہ ہو)",""],["(3)","s"]]]],"f":[["(2)","Bukhaari and Muslim, as quoted in Jam'ul Fawaa'id (Vol.1 Pg.7)."],["(3)","Tirmidhi."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ ایک بوڑھے دیہاتی تھے جنہیں علقمہ بن علاثہ کہا جاتا تھا، انہوں نے ایک مرتبہ حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں بہت بوڑھا ہوں، اب اس عمر میں قرآن نہیں سیکھ سکتا، لیکن میں اس بات کی گواہی دیتا ہوں کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور محمد ",""],["ﷺ","a"],[" ",""],["ٱللَّٰه","a"],[" کے بندے اور اس کے رسول ہیں اور مجھے اس کا پکا یقین ہے۔ جب وہ بڑے میاں چلے گئے تو حضورؐ نے فرمایا آدمی بڑا سمجھدار ہے یا فرمایا تمہارا یہ ساتھی بڑا سمجھدار ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.70). Kharaa'iti in his Makaarimul Akhlaaq and Daar Qutni in his Afraad have reported a similar narration, as quoted in Isaabah (Vol.2 Pg.503)."]]},{"b":[["n",[["حضرت عثمان بن عفانؓ","b"],[" فرماتے ہیں کہ میں نے حضورؐ کو فرماتے ہوئے سنا کہ ",""],["میں ایسا کلمہ جانتا ہوں کہ جو آدمی بھی اسے سچے دل سے کہے گا وہ آگ پر ضرور حرام ہو جائے گا۔","h"],[" اس پر حضرت عمر بن خطابؓ نے کہا کیا میں آپ کو بتاؤں وہ کلمہ کون سا ہے؟ یہ وہ کلمہ اخلاص ہے جس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے محمد ",""],["ﷺ","a"],[" اور آپؐ کے صحابہؓ کو جمائے رکھا، اور یہ وہ تقویٰ والا کلمہ ہے جس کی حضورؐ نے اپنے چچا ابوطالب کو مرتے وقت بہت ترغیب دی تھی، یعنی اس بات کی گواہی دینا کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad, as quoted in Majma'uz Zawaa'id (Vol.1 Pg.15). Abu Ya'la, Ibn Khuzaymah, Ibn Hibbaan, Bayhaqi and others have also reported the narration, as quoted in Kanzul Ummaal (Vol.1 Pg.74)."]]},{"b":[["n",[["حضرت یعلیٰ بن شدادؒ","b"],[" کہتے ہیں کہ میرے والد حضرت شدادؓ نے مجھے یہ واقعہ سنایا اس وقت حضرت عبادہ بن صامتؓ بھی اس مجلس میں موجود تھے اور وہ میرے والد کی تصدیق کر رہے تھے۔ میرے والد نے فرمایا کہ ایک دن ہم لوگ نبی کریم ",""],["ﷺ","a"],[" کے پاس تھے، آپؐ نے فرمایا کیا تم میں کوئی اجنبی یعنی اہل کتاب (یہود) میں سے ہے؟ ہم نے عرض کیا نہیں یا رسول ",""],["ٱللَّٰه","a"],["! پھر حضورؐ نے فرمایا دروازہ بند کر دو (ہم نے دروازہ بند کر دیا)۔ پھر حضورؐ نے فرمایا:",""]]],["c",[["اپنے ہاتھ اٹھاؤ اور ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہو۔",""]]],["p",[["چنانچہ ہم نے کچھ دیر اپنے ہاتھ اٹھائے رکھے (حضورؐ نے بھی ہاتھ اٹھائے ہوئے تھے)۔ پھر حضورؐ نے اپنے ہاتھ نیچے کیے (اور ہم نے بھی نیچے کیے)۔ پھر آپؐ نے فرمایا:",""]]],["c",[["الحمد للہ! اے ",""],["ٱللَّٰه","a"],["! تو نے مجھے یہ کلمہ دے کر بھیجا اور اس (پر ایمان لانے) کا حکم دیا اور اس پر جنت کا تو نے وعدہ فرمایا اور تو وعدہ خلافی نہیں کرتا۔",""]]],["p",[["پھر فرمایا غور سے سنو! ",""],["تمہیں بشارت ہو کیونکہ ","h"],["ٱللَّٰه","ah"],[" تعالیٰ نے تمہاری مغفرت کر دی ہے۔","h"],[" (6)","s"]]]],"f":[["(6)","Ahmad, Tabraani and Bazzaar, all reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.19)."]]},{"b":[["n",[["حضرت رفاعہ جہنیؓ","b"],[" فرماتے ہیں کہ ہم لوگ حضورؐ کے ساتھ واپس آ رہے تھے۔ جب ہم کدید یا قدید مقام پر پہنچے تو کچھ لوگ آپؐ سے اپنے گھر والوں کے پاس جانے کی اجازت مانگنے لگے۔ حضورؐ ان کو اجازت دینے لگے۔ پھر کھڑے ہو کر حضورؐ نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثنا بیان کی پھر فرمایا ان لوگوں کو کیا ہو گیا ہے کہ ان کو درخت کا وہ حصہ جو رسول ",""],["ٱللَّٰه","a"],["ؐ کے قریب ہے دوسرے حصے سے زیادہ ناپسند ہے۔ بس اس بات کے سنتے ہی سب رونے لگے۔ کوئی ایسا نظر نہیں آ رہا تھا جو رو نہ رہا ہو۔ ایک آدمی نے کہا اس کے بعد جو اجازت مانگے گا وہ یقیناً بڑا نادان ہوگا۔ حضورؐ نے پھر ",""],["ٱللَّٰه","a"],[" کی حمد و ثنا بیان کی اور خیر کی بات کی اور فرمایا:",""]]],["c",[["میں ",""],["ٱللَّٰه","a"],[" کے ہاں اس بات کی گواہی دیتا ہوں کہ جو بندہ اس حال میں مرے گا کہ وہ اس بات کی سچے دل سے گواہی دے رہا ہو کہ ",""],["ٱللَّٰه","a"],[" کے سوا کوئی معبود نہیں اور میں ",""],["ٱللَّٰه","a"],[" کا رسول ہوں اور پھر وہ ٹھیک ٹھیک چلتا رہے تو وہ ضرور جنت میں داخل ہوگا۔ اور میرے رب عزوجل نے مجھ سے وعدہ کیا ہے کہ وہ میری امت میں سے ستر ہزار آدمی جنت میں حساب کتاب اور عذاب کے بغیر داخل کرے گا اور مجھے امید ہے کہ آپ لوگ اور آپ لوگوں کے نیک ماں باپ اور نیک بیوی بچے جنت میں پہلے اپنے ٹھکانوں میں پہنچ جائیں گے پھر وہ ستر ہزار جنت میں داخل ہوں گے۔",""],[" (7)","s"]]],["p",[["ایک روایت میں یہ ہے کہ حضرت ابوبکرؓ نے کہا کہ اس کے بعد آپؐ سے جو اجازت مانگے گا وہ یقیناً بڑا نادان ہوگا۔",""],[" (8)","s"]]]],"f":[["(7)","Ahmad and Ibn Maajah, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.20)."],["(8)","Daarimi, Ibn Khuzaymah, Ibn Hibbaan and Tabraani, as quoted in Kanzul Ummaal (Vol.5 Pg.287)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا اے فلاں! تم نے ایسے اور ایسے کیا ہے؟ اس نے کہا نہیں۔ اس ذات کی قسم جس کے علاوہ کوئی معبود نہیں! میں نے ایسے نہیں کیا۔ چونکہ حضورؐ کو معلوم تھا کہ اس نے یہ کام کیا ہے، اس لیے آپؐ نے یہ کئی مرتبہ پوچھا (لیکن ہر مرتبہ وہ یہی جواب دیتا رہا)۔ حضورؐ نے فرمایا چونکہ تم ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کی تصدیق کر رہے ہو اس وجہ سے تمہارے اس گناہ کو مٹا دیا گیا۔",""],["(9)","s"],[" ایک روایت میں یہ ہے کہ حضورؐ نے فرمایا تمہارے ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کی تصدیق کرنے کی وجہ سے تمہارے جھوٹ کا کفارہ ہو گیا۔",""],[" (10)","s"]]]],"f":[["(9)","Bazzaar."],["(10)","Abu Ya'la. Both Bazzaar and Abu Ya'la report from reliable sources as confirmed by Haythami (Vol.10 Pg.83). Ibn Hajar has however commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابن زبیرؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا کہ ایک آدمی نے جھوٹی قسم کھائی اور یوں کہا کہ اس ",""],["ٱللَّٰه","a"],[" کی قسم جس کے علاوہ کوئی معبود نہیں تو (جھوٹی قسم کھانے کا) گناہ معاف کر دیا گیا (کیونکہ اس نے قسم کے ساتھ ",""],["لَا إِلٰهَ إِلَّا هُوَلَا إِلٰهَ إِلَّا هُوَ","a"],[" کے الفاظ بھی کہہ دیے تو ان الفاظ کی برکت سے وہ گناہ معاف ہو گیا)۔",""],[" (11)","s"]]]],"f":[["(11)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.83)."]]},{"b":[["n",[["حضرت ابوموسیٰ اشعریؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا کہ جہنمی لوگ جب جہنم میں اکٹھے ہو جائیں گے اور ان کے ساتھ کچھ قبلہ کو ماننے والے یعنی کچھ مسلمان بھی ہوں گے تو وہ کافر مسلمانوں سے کہیں گے کہ کیا تم لوگ مسلمان نہیں تھے؟ وہ مسلمان جواب دیں گے کیوں نہیں، ہم تو مسلمان تھے۔ کفار کہیں گے تمہارے اسلام نے تمہیں کیا فائدہ دیا؟ تم بھی ہمارے ساتھ جہنم میں آ گئے۔ مسلمان جواب میں کہیں گے ہمارے کچھ گناہ تھے جن کی وجہ سے ہم پکڑے گئے اور جہنم میں ڈال دیے گئے۔ مسلمانوں کے اس جواب کو ",""],["ٱللَّٰه","a"],[" تعالیٰ سنیں گے اور (فرشتوں کو) حکم دیں گے، چنانچہ جہنم میں جتنے قبلہ کو ماننے والے مسلمان ہوں گے وہ سب اس میں سے نکال دیے جائیں گے۔ جب جہنم میں باقی رہ جانے والے کفار یہ منظر دیکھیں گے تو وہ کہیں گے اے کاش! ہم بھی مسلمان ہوتے تو جیسے یہ نکل گئے ہم بھی جہنم سے نکل جاتے۔ پھر حضورؐ نے اعوذ ب",""],["ٱللَّٰه","a"],[" من الشیطان الرجیم پڑھ کر یہ آیات پڑھیں:",""]]],["q",[["الٓر ۚ تِلْكَ آيَاتُ الْكِتَابِ وَقُرْآنٍ مُّبِينٍ ۝ رُبَمَا يَوَدُّ الَّذِينَ كَفَرُوا لَوْ كَانُوا مُسْلِمِينَ  (سورۃ الحجر: ۱-۲)","a"]]],["p",[["ترجمہ: الر۔ یہ آیتیں ہیں کامل کتاب اور قرآنِ واضح کی۔ کافر لوگ بار بار تمنا کریں گے کہ کیا خوب ہوتا اگر وہ مسلمان ہوتے۔",""],[" (12)","s"]]]],"f":[["(12)","Tabraani. Ibn Abi Haatim has reported a similar narration."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا کہ ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" والوں میں سے کچھ لوگ اپنے گناہوں کی وجہ سے جہنم میں چلے جائیں گے۔ لات اور عزیٰ (بتوں) کو ماننے والے ان سے کہیں گے کہ جب تم بھی ہمارے ساتھ جہنم کی آگ میں ہو تو ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہنے کا تمہیں کیا فائدہ ہوا؟ اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ کو مسلمانوں کے حق میں غصہ آ جائے گا تو ",""],["ٱللَّٰه","a"],[" تعالیٰ انہیں وہاں سے نکال کر نہر حیات میں ڈال دیں گے جس سے ان کے جسم جہنم کی جلن سے ایسے صاف ہو جائیں گے جیسے کہ چاند گرہن سے نکل کر صاف ہو جاتا ہے اور جنت میں داخل ہو جائیں گے اور یہ لوگ جہنمی کے نام سے پکارے جائیں گے۔",""],["(13)","s"],[" ایک روایت میں یہ ہے کہ چونکہ ان کے چہروں میں کچھ سیاہی ہوگی، اس لیے یہ لوگ جنت میں جہنمی کے نام سے پکارے جائیں گے۔ وہ عرض کریں گے اے ہمارے رب! ہم سے یہ نام ختم کر دے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ انہیں جنت کی نہر میں نہانے کا حکم دیں گے تو (وہ سیاہی چلی جائے گی اور) ان کا یہ نام ختم ہو جائے گا۔",""]]]],"f":[["(13)","Tabraani, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.546)."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا اسلام بھی ایسے پرانا ہو جائے گا جیسے کپڑے کے نقش و نگار پرانے ہو جاتے ہیں۔ کسی کو معلوم نہ ہوگا کہ روزہ، صدقہ اور قربانی کیا چیز ہے؟ ",""],["ٱللَّٰه","a"],[" کی کتاب یعنی قرآن پر ایک رات ایسی آئے گی کہ اس کی ایک آیت بھی زمین پر باقی نہ رہے گی۔ (فرشتہ ساری زمین سے سارا قرآن اٹھا کر لے جائے گا) اور لوگوں کی مختلف جماعتیں باقی رہ جائیں گی جن کے بوڑھے مرد اور بوڑھی عورتیں کہیں گی کہ ہم نے اپنے آباء و اجداد کو اس کلمہ ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" پر پایا تھا، ہم بھی یہی کلمہ پڑھتے ہیں۔ حضرت صلہؒ (راوی) نے پوچھا کہ جب وہ لوگ یہ بھی نہیں جانتے ہوں گے کہ روزہ، صدقہ اور قربانی کیا چیز ہے تو ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" پڑھنے سے انہیں کیا فائدہ ہوگا؟ حضرت حذیفہؓ نے ان سے اعراض فرمایا۔ حضرت صلہؒ نے دوبارہ پوچھا تو حضرت حذیفہؓ نے پھر اعراض فرمایا۔ جب تیسری مرتبہ پوچھا تو حضرت حذیفہؓ نے ان کی طرف متوجہ ہو کر فرمایا اے صلہ! یہ کلمہ انہیں آگ سے نجات دے گا، یہ کلمہ انہیں آگ سے نجات دے گا، یہ کلمہ انہیں آگ سے نجات دے گا۔",""],[" (14)","s"]]]],"f":[["(14)","Haakim (Vol.4 Pg.545), reporting from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ لوگوں میں سے ",""],["ٱللَّٰه","a"],[" تعالیٰ کے ساتھ سب سے زیادہ معاملہ صاف رکھنے والا اور ",""],["ٱللَّٰه","a"],[" کو سب سے زیادہ جاننے والا وہ آدمی ہے جو ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" والوں سے سب سے زیادہ محبت کرنے والا اور ان کی سب سے زیادہ تعظیم کرنے والا ہو۔",""],[" (15)","s"]]]],"f":[["(15)","Abu Nu'aym in his Hilya, as quoted in Kanzul Ummaal (Vol.1 Pg.76)."]]},{"b":[["n",[["حضرت سالم بن ابی الجعدؒ","b"],[" کہتے ہیں کہ حضرت ابوالدرداءؓ کو کسی نے بتایا کہ حضرت ابوسعد بن منبہؓ نے سو غلام آزاد کیے ہیں۔ حضرت ابوالدرداءؓ نے فرمایا ایک آدمی کے مال میں سو غلام بہت زیادہ ہیں لیکن اگر تم کہو تو میں تمہیں اس سے بھی زیادہ فضیلت والے (اعمال) بتا دوں۔ ایک تو وہ ایمان جو دن رات ہر وقت دل سے چمٹا ہوا ہو اور دوسرے یہ کہ ہر وقت تمہاری زبان ",""],["ٱللَّٰه","a"],[" کے ذکر سے تر رہے۔",""],[" (16)","s"]]]],"f":[["(16)","Abu Nu'aym in his Hilya (Vol.1 Pg.219). Ibn Abi Dunya has reported a similar narration, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.55)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں کہ جیسے ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہاری روزی کو تمہارے درمیان تقسیم کیا ہے، اسی طرح اخلاق کو بھی تمہارے درمیان تقسیم کیا ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ مال تو اسے بھی دے دیتے ہیں جس سے محبت ہو اور اسے بھی دے دیتے ہیں جس سے محبت نہ ہو لیکن ایمان صرف اسے ہی دیتے ہیں جس سے محبت ہو۔ چنانچہ ",""],["ٱللَّٰه","a"],[" تعالیٰ جب کسی بندے سے محبت کرتے ہیں تو اسے ایمان دے دیتے ہیں، لہٰذا جو بخل کی وجہ سے مال خرچ نہ کر سکتا ہو اور بزدلی کی وجہ سے دشمن سے جہاد نہ کر سکتا ہو اور راتوں کو محنت نہ کر سکتا ہو اسے چاہیے کہ وہ ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],["، ",""],["ٱللَّٰه","a"],[" اکبر، الحمد للہ اور سبحان ",""],["ٱللَّٰه","a"],[" کثرت سے کہا کرے۔",""],[" (17)","s"]]]],"f":[["(17)","Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.10 Pg.90) and Mundhiri in his Targheeb wat Tarheeb (Vol.3 Pg.95)."]]}]},"2":{"lead":[],"stories":[{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ جب حضورؐ کے کسی صحابیؓ سے ملتے تو اس سے کہتے آؤ تھوڑی دیر اپنے رب پر ایمان کو تازہ کریں۔ ایک دن انہوں نے یہ بات ایک آدمی سے کہی اسے غصہ آ گیا اور اس نے جا کر حضورؐ کی خدمت میں عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کیا آپ نے حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ کو نہیں دیکھا کہ وہ آپ کے ایمان کو چھوڑ کر ایک گھڑی کا ایمان اختیار کر رہے ہیں۔ حضورؐ نے فرمایا:",""]]],["c",[["ٱللَّٰه","a"],[" ابن رواحہ پر رحم فرمائے، یہ ان مجلسوں کو پسند کرتے ہیں جن پر فرشتے فخر کرتے ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad, as quoted in Targheeb wat Tarheeb (Vol.3 Pg.63). Haafidh has commented on the chain of narrators in Al Bidaayah wan Nihaayah (Vol.4 Pg.258)."]]},{"b":[["n",[["حضرت عطاء بن یسارؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ نے اپنے ایک ساتھی سے کہا آؤ ہم ایک گھڑی اپنا ایمان تازہ کر لیں۔ اس نے کہا کیا ہم پہلے سے مومن نہیں ہیں؟ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے کہا ہیں، لیکن ہم ",""],["ٱللَّٰه","a"],[" کا ذکر کریں گے تو اس سے ہمارا ایمان بڑھ جائے گا۔",""],[" (2)","s"]]]],"f":[["(2)","Bayhaqi."]]},{"b":[["n",[["حضرت شریح بن عبد","b"],["ٱللَّٰه","a"],["ؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ اپنے کسی ساتھی کا ہاتھ پکڑ کر کہتے، آؤ ہمارے ساتھ کچھ دیر رہو تاکہ ہم ایمان تازہ کر لیں اور ذکر کی مجلس میں (",""],["ٱللَّٰه","a"],[" کی ذات و صفات کا آپس میں ذکر کرنے کے لیے) بیٹھ جائیں۔",""],[" (3)","s"]]]],"f":[["(3)","Haafidh Abul Qaasim Laalkaa'ee."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ میرا ہاتھ پکڑ کر کہا کرتے، آؤ ہم کچھ دیر اپنا ایمان تازہ کر لیں کیونکہ دل اس ہانڈی سے بھی جلدی پلٹ جاتا ہے جو خوب زور شور سے ابل رہی ہو۔",""],[" (4)","s"]]]],"f":[["(4)","Tayaalisi."]]},{"b":[["n",[["حضرت ابوالدرداءؓ","b"],[" فرماتے ہیں کہ جب حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ مجھ سے ملتے تو مجھے کہتے، اے عویمر! ذرا بیٹھ جاؤ کچھ دیر (ایمان کا) مذاکرہ کر لیں۔ چنانچہ ہم بیٹھ کر مذاکرہ کر لیتے پھر مجھ سے فرماتے یہ ایمان کی مجلس ہے۔ ایمان تمہارے کرتے کی طرح ہے جسے تم نے پہنا ہوا ہوتا ہے پھر تم اسے اتار لیتے ہو، اتارا ہوا ہوتا ہے پھر تم اسے پہن لیتے ہو اور دل اس ہانڈی سے بھی جلدی پلٹ جاتا ہے جو خوب زور شور سے ابل رہی ہو۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.1 Pg.101)."]]},{"b":[["n",[["حضرت ابوذرؓ","b"],[" فرماتے ہیں کہ حضرت عمرؓ اپنے ساتھیوں میں سے ایک دو کا ہاتھ پکڑ لیتے اور فرماتے ہمارے ساتھ کچھ دیر رہو تاکہ ہم اپنا ایمان بڑھا لیں اور پھر ہم ",""],["ٱللَّٰه","a"],[" تعالیٰ (کی ذات و صفات) کا ذکر کرتے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abi Shaybah and Laalkaa'ee in his Sunnah, as quoted in Kanzul Ummaal (Vol.1 Pg.207)."]]},{"b":[["n",[["حضرت اسود بن ہلالؒ","b"],[" کہتے ہیں کہ ہم لوگ حضرت معاذؓ کے ساتھ چل رہے تھے کہ اتنے میں انہوں نے فرمایا آؤ کچھ دیر بیٹھ کر ایمان تازہ کر لیں۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Hilya (Vol.1 Pg.235)."]]}]},"3":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا اپنا ایمان تازہ کرتے رہو۔ صحابہؓ نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! ہم اپنا ایمان کیسے تازہ کریں؟ آپؐ نے فرمایا ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کثرت سے کہا کرو۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad and Tabraani, reporting from reliable sources as confirmed by Haythami (Vol.1 Pg.82) and Mundhiri in Targheeb wat Tarheeb (Vol.3 Pg.75)."]]}]},"4":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوسعید خدریؓ","b"],[" فرماتے ہیں کہ ایک آدمی نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا کہ میرے بھائی کو دست آ رہے ہیں۔ حضورؐ نے فرمایا اسے شہد پلاؤ (کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے کہ شہد میں لوگوں کے لیے شفا ہے)۔ وہ آدمی گیا اور اس نے جا کر اپنے بھائی کو شہد پلایا اور پھر آ کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے اسے شہد پلایا، اس سے تو دست اور زیادہ آنے لگے ہیں۔ حضورؐ نے فرمایا جاؤ اسے شہد پلاؤ۔ اس نے جا کر شہد پلایا اور پھر آ کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! اس کو تو دست اور زیادہ آنے لگے ہیں۔ ",""],["حضورؐ نے فرمایا ","h"],["ٱللَّٰه","ah"],[" سچ فرماتے ہیں اور تمہارے بھائی کا پیٹ غلط کہتا ہے۔","h"],[" جاؤ اسے شہد پلاؤ۔ اب جا کر اس نے بھائی کو شہد پلایا تو وہ ٹھیک ہو گیا۔",""],[" (1)","s"]]]],"f":[["(1)","Bukhaari and Muslim, as quoted in Tafseer of Ibn Katheer (Vol.2 Pg.575)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ کی بیوی حضرت زینبؓ","b"],[" فرماتی ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ جب ضرورت پوری کر کے گھر واپس آتے اور دروازے پر پہنچتے تو کھنکارتے اور تھوکتے تاکہ ایسا نہ ہو کہ وہ اچانک اندر آئیں اور ہمیں کسی نامناسب حالت میں دیکھ لیں۔ چنانچہ وہ ایک دن آئے اور انہوں نے کھنکارا۔ اس وقت میرے پاس ایک بوڑھی عورت تھی جو حمرہ",""],["(2)","s"],[" کا منتر پڑھ کر مجھ پر دم کر رہی تھی، میں نے اسے پلنگ کے نیچے چھپا دیا۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ اندر آ کر میرے پاس بیٹھ گئے۔ ان کو میری گردن میں ایک دھاگہ نظر آیا۔ انہوں نے کہا یہ دھاگہ کیسا ہے؟ میں نے کہا اس پر منتر پڑھ کر کسی نے مجھے دیا ہے۔ انہوں نے دھاگہ پکڑ کر کاٹ دیا اور فرمایا عبد",""],["ٱللَّٰه","a"],[" کے گھر والوں کو شرک کی کوئی ضرورت نہیں۔ ",""],["میں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ منتر، تعویذ اور گنڈا یہ سب شرک ہے۔","h"],[" (بشرطیکہ ان چیزوں کو ہی خود اثر کرنے والا سمجھے)۔ میں نے ان سے کہا آپ یہ کیسے کہہ رہے ہیں؟ میری آنکھ دکھنے آتی تھی، میں فلاں یہودی کے پاس جایا کرتی تھی وہ دم کیا کرتا تھا۔ جب بھی وہ دم کرتا میری آنکھ ٹھیک ہو جاتی۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے فرمایا یہ سب کچھ شیطان کی طرف سے تھا۔ شیطان تمہاری آنکھ پر ہاتھ سے کچوکا مارتا تھا (جس سے آنکھ دکھنے لگ جاتی تھی)، جب وہ یہودی دم کرتا تو وہ اپنا ہاتھ پیچھے ہٹا لیتا (جس سے آنکھ ٹھیک ہو جاتی)۔ تمہیں یہ کافی تھا کہ تم اس موقع پر یہ دعا پڑھ لیتیں جو حضورؐ پڑھا کرتے تھے:",""]]],["q",[["اَذْهِبِ الْبَاسَ رَبَّ النَّاسِ، وَاشْفِ أَنْتَ الشَّافِي، لَا شِفَاءَ إِلَّا شِفَاؤُكَ، شِفَاءً لَا يُغَادِرُ سَقَمًا","a"],[" (3)","s"]]],["p",[["ترجمہ: اے لوگوں کے رب! تکلیف کو دور فرما دے اور شفا عطا فرما، تو ہی شفا دینے والا ہے، تیری شفا کے سوا کوئی شفا نہیں، ایسی شفا عطا فرما جو کسی بیماری کو نہ چھوڑے۔",""]]]],"f":[["(2)","Erysipelas: a severe bacterial skin rash accompanied by fever and vomiting."],["(3)","Ahmad, as quoted in Tafseer of Ibn Katheer (Vol.2 Pg.494)."]]},{"b":[["n",[["حضرت عکرمہؒ","b"],[" کہتے ہیں کہ حضرت ابن رواحہؓ اپنی بیوی کے پہلو میں لیٹے ہوئے تھے ان کی باندی گھر کے کونے میں (سو رہی) تھی۔ یہ اٹھ کر اس کے پاس چلے گئے اور اس میں مشغول ہو گئے۔ ان کی بیوی گھبرا کر اٹھی اور ان کو بستر پر نہ پایا تو وہ بھی اٹھ کر باہر چلی گئی اور انہیں باندی میں مشغول دیکھا۔ وہ اندر واپس آئی اور چھری لے کر باہر نکلی، اتنے میں یہ فارغ ہو کر کھڑے ہو چکے تھے اور اپنی بیوی کو راستے میں ملے۔ بیوی نے چھری اٹھائی ہوئی تھی۔ انہوں نے پوچھا کیا بات ہے؟ بیوی نے کہا ہاں کیا بات ہے؟ اگر میں تمہیں وہاں پا لیتی جہاں میں نے تمہیں دیکھا تھا تو میں تمہارے کندھوں کے درمیان یہ چھری گھونپ دیتی۔ حضرت ابن رواحہؓ نے کہا تم نے مجھے کہاں دیکھا تھا؟ انہوں نے کہا میں نے تمہیں باندی کے پاس دیکھا تھا۔ حضرت ابن رواحہؓ نے کہا تم نے مجھے وہاں نہیں دیکھا تھا۔ میں نے اس کے ساتھ کچھ نہیں کیا، اگر میں نے اس کے ساتھ کچھ کیا ہوتا تو میں جنبی ہوتا اور حضورؐ نے حالت جنابت میں قرآن پڑھنے سے ہمیں منع فرمایا ہے (اور میں ابھی قرآن پڑھ کر تمہیں سناتا ہوں)۔ ان کی بیوی نے کہا اچھا قرآن پڑھو۔ انہوں نے یہ اشعار (اس طرح سے) پڑھے (کہ ان کی بیوی قرآن سمجھتی رہی۔ محبت بڑھانے کے لیے میاں بیوی کا آپس میں جھوٹ بولنا جائز ہے):",""]]],["q",[["أَتَانَا رَسُولُ اللّٰهِ يَتْلُو كِتَابَهُ  ·  كَمَا لَاحَ مَشْهُورٌ مِنَ الْفَجْرِ سَاطِعُ","a"]]],["p",[["ہمارے پاس ",""],["ٱللَّٰه","a"],[" کے رسول آئے جو ",""],["ٱللَّٰه","a"],[" کی ایسی کتاب پڑھتے ہیں جو کہ روشن اور چمکدار صبح کی طرح چمکتی ہے۔",""]]],["q",[["أَتَى بِالْهُدَى بَعْدَ الْعَمَى فَقُلُوبُنَا  ·  بِهِ مُوقِنَاتٌ أَنَّ مَا قَالَ وَاقِعُ","a"]]],["p",[["آپؐ لوگوں کے اندھے پن کے بعد ہدایت لے کر آئے اور ہمارے دلوں کو یقین ہے کہ آپؐ نے جو کچھ کہا ہے وہ ہو کر رہے گا۔",""]]],["q",[["يَبِيتُ يُجَافِي جَنْبَهُ عَنْ فِرَاشِهِ  ·  إِذَا اسْتَثْقَلَتْ بِالْمُشْرِكِينَ الْمَضَاجِعُ","a"]]],["p",[["جب مشرکین بستروں پر گہری نیند سو رہے ہوتے ہیں اس وقت آپؐ عبادت میں ساری رات گزار دیتے ہیں، اور آپؐ کا پہلو بستر سے دور رہتا ہے۔",""]]],["p",[["یہ اشعار سن کر ان کی بیوی نے کہا میں ",""],["ٱللَّٰه","a"],[" پر ایمان لاتی ہوں اور میں اپنی نگاہ کو غلط قرار دیتی ہوں۔ پھر صبح کو حضرت ابن رواحہؓ نے حضورؐ کی خدمت میں جا کر یہ واقعہ سنایا تو حضورؐ اتنا ہنسے کہ آپؐ کے دندان مبارک نظر آنے لگے۔",""],[" (4)","s"]]]],"f":[["(4)","Daar Qutni (Pg.44,45). The author of Ta'leequl Mughni (Pg.45) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت حبیب بن ابی ثابتؒ","b"],[" کہتے ہیں کہ میں حضرت ابووائلؒ سے کچھ پوچھنے گیا۔ انہوں نے کہا ہم جنگ صفین میں تھے تو ایک آدمی نے کہا کیا آپ نے ان لوگوں کو نہیں دیکھا جو ",""],["ٱللَّٰه","a"],[" کی کتاب کی طرف بلائے جا رہے ہیں؟ اس پر حضرت علیؓ نے فرمایا ہاں (میں نے انہیں دیکھا ہے)۔ حضرت سہل بن حنیفؓ نے (اس آدمی کو) کہا، اپنے آپ کو قصوروار ٹھہراؤ کیونکہ ہم نے صلح حدیبیہ کے دن، جس دن حضورؐ اور مشرکوں کے درمیان صلح ہوئی تھی، یہ دیکھا تھا کہ اگر ہم لڑنا مفید سمجھتے تو ہم مشرکوں سے لڑ سکتے تھے (لیکن ہم نے مفید نہ سمجھا صلح کے بعد)۔ حضرت عمرؓ نے (حضورؐ کی خدمت میں) عرض کیا کیا ہم حق پر اور یہ مشرک باطل پر نہیں ہیں؟ کیا ہمارے شہید جنت میں اور ان کے مقتول جہنم میں نہیں جائیں گے؟ اور ابھی ",""],["ٱللَّٰه","a"],[" نے ہمارے درمیان فیصلہ نہیں فرمایا تو ہم واپس کیوں جا رہے ہیں؟ حضورؐ نے فرمایا:",""]]],["c",[["اے ابن خطاب! میں ",""],["ٱللَّٰه","a"],[" کا رسول ہوں، مجھے ",""],["ٱللَّٰه","a"],[" تعالیٰ ہرگز ضائع نہیں ہونے دیں گے۔",""]]],["p",[["(اس سے حضرت عمرؓ کا غصہ ٹھنڈا نہ ہوا بلکہ) وہ غصے میں بھرے ہوئے حضرت ابوبکر صدیقؓ کے پاس گئے اور ان سے کہا، اے ابوبکر! کیا ہم حق پر اور یہ مشرک باطل پر نہیں؟ حضرت ابوبکرؓ نے فرمایا اے ابن خطاب! یہ ",""],["ٱللَّٰه","a"],[" کے رسول ہیں اور ",""],["ٱللَّٰه","a"],[" تعالیٰ انہیں ہرگز ضائع نہیں ہونے دیں گے۔ پھر سورت فتح نازل ہوئی۔",""],["(5)","s"],[" ایک روایت میں یہ ہے کہ حضرت سہل بن حنیفؓ نے کہا اے لوگو! اپنی رائے کو ناقص سمجھو، میں نے حضرت ابوجندلؓ (کے مشرکوں کی طرف واپس کیے جانے) کے دن دیکھا (کہ جب حضورؐ نے انہیں مشرکوں کی طرف واپس کرنے کو مان لیا تو مجھے اس سے اتنی زیادہ گرانی ہوئی) کہ حضورؐ کی بات کے انکار کی اگر مجھ میں طاقت ہوتی تو اس دن میں ضرور انکار کر دیتا۔ ایک روایت میں ہے کہ پھر سورت فتح نازل ہوئی تو حضورؐ نے حضرت عمر بن خطابؓ کو بلایا اور انہیں سورت فتح پڑھ کر سنائی۔",""],["(6)","s"],[" اور دعوت الی ",""],["ٱللَّٰه","a"],[" کے باب میں صلح حدیبیہ کے قصہ میں بخاری کی لمبی حدیث گزر چکی ہے جسے حضرت مسور بن مخرمہؓ اور حضرت مروانؓ روایت کرتے ہیں، اس میں یہ بھی ہے کہ حضرت ابوجندلؓ نے کہا اے مسلمانو! میں تو مسلمان ہو کر آیا تھا اور اب مجھے مشرکوں کی طرف واپس کیا جا رہا ہے، کیا تم دیکھ نہیں رہے ہو کہ میں کتنی مصیبتیں اٹھا رہا ہوں؟ اور واقعی انہیں ",""],["ٱللَّٰه","a"],[" کی خاطر سخت مصیبتیں پہنچائی گئی تھیں۔",""]]]],"f":[["(5)","Bukhaari and Muslim."],["(6)","Nasa'ee, as quoted in Tafseer of Ibn Katheer (Vol.4 Pg.200)."]]},{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں کہ میں نے حضورؐ کی خدمت میں آ کر عرض کیا کہ کیا آپؐ ",""],["ٱللَّٰه","a"],[" کے برحق نبی نہیں ہیں؟ حضورؐ نے فرمایا ہوں۔ پھر میں نے کہا کہ کیا ہم حق پر اور ہمارا دشمن باطل پر نہیں ہے؟ آپؐ نے فرمایا ہاں، تم ٹھیک کہتے ہو۔ میں نے عرض کیا پھر ہم کیوں اتنا دب کر صلح کریں؟ آپؐ نے فرمایا میں ",""],["ٱللَّٰه","a"],[" کا رسول ہوں، اس کی نافرمانی نہیں کر سکتا اور وہی میرا مددگار ہے۔ میں نے کہا کیا آپؐ نے ہم سے یہ نہیں فرمایا تھا کہ ہم بیت ",""],["ٱللَّٰه","a"],[" جا کر اس کا طواف کریں گے؟ آپؐ نے فرمایا ہاں، میں نے کہا تھا لیکن کیا میں نے تم کو یہ بھی کہا تھا کہ ہم اسی سال بیت ",""],["ٱللَّٰه","a"],[" جائیں گے؟ میں نے عرض کیا نہیں۔ آپؐ نے فرمایا تم بیت ",""],["ٱللَّٰه","a"],[" ضرور جاؤ گے اور اس کا طواف کرو گے۔ حضرت عمرؓ فرماتے ہیں کہ میں حضرت ابوبکرؓ کے پاس گیا اور ان سے کہا اے ابوبکر! کیا یہ ",""],["ٱللَّٰه","a"],[" کے برحق نبی نہیں ہیں؟ انہوں نے کہا، ہیں۔ میں نے کہا کیا ہم حق پر اور ہمارا دشمن باطل پر نہیں ہے؟ انہوں نے کہا، تم ٹھیک کہتے ہو۔ میں نے کہا پھر ہم کیوں اتنا دب کر صلح کریں؟ حضرت ابوبکرؓ نے کہا اے آدمی! وہ ",""],["ٱللَّٰه","a"],[" کے رسول ہیں اور وہ ",""],["ٱللَّٰه","a"],[" کی نافرمانی نہیں کر سکتے اور ",""],["ٱللَّٰه","a"],[" ان کا مددگار ہے، تم ان کا دامن مضبوطی سے تھامے رکھو۔ ",""],["ٱللَّٰه","a"],[" کی قسم! وہ حق پر ہیں۔ میں نے کہا کیا انہوں نے ہم سے یہ نہیں فرمایا تھا کہ ہم بیت ",""],["ٱللَّٰه","a"],[" جا کر اس کا طواف کریں گے؟ انہوں نے کہا، ہاں۔ کیا انہوں نے تم سے یہ بھی کہا تھا کہ تم اسی سال بیت ",""],["ٱللَّٰه","a"],[" جاؤ گے؟ میں نے کہا، نہیں۔ انہوں نے کہا تم بیت ",""],["ٱللَّٰه","a"],[" ضرور جاؤ گے اور اس کا طواف کرو گے۔ حضرت عمرؓ فرماتے ہیں کہ میں نے اپنی اس گستاخی کی معافی کے لیے بہت سے اعمال خیر کیے۔",""]]]],"f":[]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ حدیبیہ سے واپسی پر نبی کریم ",""],["ﷺ","a"],[" پر یہ آیت نازل ہوئی:",""]]],["q",[["لِيَغْفِرَ لَكَ اللّٰهُ مَا تَقَدَّمَ مِنْ ذَنۢبِكَ وَمَا تَأَخَّرَ  (سورۃ الفتح: ۲)","a"]]],["p",[["ترجمہ: تاکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ آپ کی سب اگلی پچھلی خطائیں معاف فرما دے۔ حضورؐ نے فرمایا:",""]]],["c",[["آج مجھ پر ایک آیت نازل ہوئی ہے جو مجھے روئے زمین کی تمام چیزوں سے زیادہ محبوب ہے۔",""]]],["p",[["پھر حضورؐ نے صحابہؓ کو یہ آیت سنائی۔ صحابہؓ نے کہا اے ",""],["ٱللَّٰه","a"],[" کے نبی! آپ کو یہ خوشخبری مبارک ہو۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے بتا دیا ہے کہ وہ آپ کے ساتھ کیا معاملہ فرمائیں گے لیکن یہ نہ پتہ چلا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمارے ساتھ کیا معاملہ فرمائیں گے؟ اس پر حضورؐ پر یہ آیت نازل ہوئی:",""]]],["q",[["لِيُدْخِلَ الْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ جَنَّاتٍ تَجْرِي مِنْ تَحْتِهَا الْأَنْهَارُ ... فَوْزًا عَظِيمًا  (سورۃ الفتح: ۵)","a"]]],["p",[["ترجمہ: تاکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ مسلمان مردوں اور مسلمان عورتوں کو ایسی بہشت میں داخل کرے جن کے نیچے نہریں جاری ہوں گی جن میں ہمیشہ کو رہیں گے اور تاکہ ان کے گناہ دور کر دے اور یہ ",""],["ٱللَّٰه","a"],[" کے نزدیک بڑی کامیابی ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Ahmad. Bukhaari and Muslim have reported a similar narration, as quoted in Tafseer of Ibn Katheer (Vol.4 Pg.183)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ حدیبیہ سے واپسی میں یہ آیت حضورؐ پر نازل ہوئی:",""]]],["q",[["إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا  (سورۃ الفتح: ۱)","a"]]],["p",[["ترجمہ: بے شک ہم نے آپ کو ایک کھلم کھلا فتح دی۔",""],["(8)","s"],[" حضورؐ کے صحابہؓ کو (بیت ",""],["ٱللَّٰه","a"],[" کے قریب پہنچ کر) عمرہ کرنے سے روک دیا گیا تھا اور حضورؐ اور صحابہؓ نے حدیبیہ میں قربانی کے جانور ذبح کر دیے تھے اور سب پر بہت زیادہ رنج و غم طاری تھا۔ حضورؐ نے فرمایا مجھ پر ایک ایسی آیت نازل ہوئی ہے جو مجھے ساری دنیا سے زیادہ محبوب ہے اور پھر",""]]],["q",[["إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا ۝ لِّيَغْفِرَ لَكَ ٱللَّٰهُ مَا تَقَدَّمَ مِن ذَنۢبِكَ وَمَا تَأَخَّرَ ... عَزِيزًا","a"]]],["p",[["یہاں تک پڑھا۔ حضورؐ کے صحابہؓ نے عرض کیا اے ",""],["ٱللَّٰه","a"],[" کے نبی! آپ کو مبارک ہو۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا ہے۔",""],["(9)","s"]]]],"f":[["(8)","Allaah granted the victory through the Treaty of Hudaybiyyah because after this treaty large numbers of people accepted Islaam and it led to the conquest of Makkah."],["(9)","Ibn Jareer (Vol.26 Pg.44)."]]},{"b":[["n",[["حضرت مجمع بن جاریہ انصاریؓ","b"],[" جو قرآن پڑھے ہوئے قاریوں میں سے تھے وہ فرماتے ہیں کہ ہم صلح حدیبیہ کے وقت موجود تھے، جب ہم وہاں سے واپس ہوئے تو لوگ اونٹوں کو دوڑا رہے تھے۔ کچھ لوگوں نے دوسروں سے پوچھا کہ ان لوگوں کو کیا ہوا؟ (یہ اونٹ اتنے تیز کیوں دوڑا رہے ہیں؟) ان لوگوں نے بتایا کہ حضورؐ پر وحی نازل ہوئی ہے تو ہم بھی ان لوگوں کے ساتھ سواریاں تیز دوڑانے لگے۔ جب حضورؐ کے پاس پہنچے تو حضورؐ کراع الغمیم مقام کے نزدیک اپنی سواری پر تشریف فرما تھے۔ آہستہ آہستہ لوگ آپؐ کے پاس جمع ہو گئے۔ پھر آپؐ نے یہ آیت پڑھ کر سنائی:",""]]],["q",[["إِنَّا فَتَحْنَا لَكَ فَتْحًا مُّبِينًا","a"]]],["p",[["حضورؐ کے پاس صحابہؓ میں سے ایک صحابی نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کیا یہ فتح تھی؟ حضورؐ نے فرمایا:",""]]],["c",[["ہاں، اس ذات کی قسم جس کے قبضے میں محمدؐ کی جان ہے یہ یقیناً زبردست فتح تھی۔",""]]],["p",[["آگے اور بھی حدیث ہے۔",""],["(10)","s"]]]],"f":[["(10)","Ahmad. Abu Dawood has reported a similar narration, as quoted in Tafseer of Ibn Katheer (Vol.4 Pg.173)."]]},{"b":[["n",[["حضرت براءؓ","b"],[" فرماتے ہیں کہ تم لوگ فتح مکہ کو بڑی فتح سمجھتے ہو، فتح مکہ بھی بڑی فتح ہے لیکن ہم صلح حدیبیہ کے دن بیعت الرضوان کو اس سے بھی بڑی فتح سمجھتے ہیں۔ آگے اور بھی حدیث ہے۔",""],["(11)","s"]]]],"f":[["(11)","Bukhaari, as quoted in Tafseer of Ibn Katheer (Vol.4 Pg.182)."]]},{"b":[["n",[["حضرت جابرؓ","b"],[" فرماتے ہیں کہ ہم بڑی فتح صرف صلح حدیبیہ کو ہی شمار کرتے تھے۔",""],["(12)","s"]]]],"f":[["(12)","Ibn Jareer (Vol.26 Pg.44)."]]},{"b":[["n",[["حضرت قیس بن حجاجؒ","b"],[" اپنے ایک استاد سے نقل کرتے ہیں کہ جب مسلمانوں نے مصر فتح کر لیا اور مصری مہینوں میں سے بونہ نامی مہینہ",""],["(13)","s"],[" شروع ہو گیا تو مسلمانوں کے امیر حضرت عمرو بن عاصؓ کے پاس مصر والے آئے اور انہوں نے کہا اے امیر صاحب! ہمارے اس دریائے نیل کے جاری رہنے کے لیے ایک پرانی رسم ہے، وہ رسم ہم ادا نہ کریں تو دریائے نیل کا پانی خشک ہو جاتا ہے۔ حضرت عمروؓ نے فرمایا وہ رسم کیا ہے؟ مصر والوں نے کہا وہ رسم یہ ہے کہ جب اس (بونہ) مہینے کی بارہ تاریخ ہو جاتی ہے تو ہم ایک کنواری لڑکی کو تلاش کرتے ہیں جو اپنے ماں باپ کے پاس رہتی ہو۔ اس کے ماں باپ کو (بہت سامان دے کر) راضی کرتے ہیں۔ پھر اس لڑکی کو سب سے عمدہ زیور اور کپڑے پہناتے ہیں اور پھر اسے دریائے نیل میں ڈال دیتے ہیں۔ حضرت عمروؓ نے ان سے فرمایا یہ کام اسلام میں نہیں ہو سکتا۔ ",""],["اسلام اپنے سے پہلے کے تمام غلط کاموں کو ختم کر دیتا ہے۔","h"],[" وہ مصری لوگ بونہ مہینے میں وہاں ہی رہے (اور دریائے نیل میں پانی بالکل نہیں تھا)۔ بالآخر مصریوں نے مصر چھوڑ کر جانے کا ارادہ کر لیا۔ حضرت عمروؓ نے حضرت عمر بن خطابؓ کو خط میں یہ ساری تفصیل لکھ کر بھیجی۔ حضرت عمرؓ نے جواب میں یہ لکھا کہ تم نے جو کیا وہ بالکل ٹھیک ہے اور میں اس خط کے ساتھ ایک پرچہ بھیج رہا ہوں اسے دریائے نیل میں ڈال دو۔ پھر آگے اور حدیث بھی ہے جیسے کہ تائیدات غیبیہ کے باب میں دریاؤں کے مسخر ہونے کے ذیل میں آئے گی۔ اس کے آخر میں یہ ہے کہ حضرت عمروؓ نے وہ پرچہ دریائے نیل میں ڈال دیا (یہ جمعہ کا دن تھا)۔ ہفتے کے دن صبح کو لوگوں نے جا کر دیکھا تو وہ حیران رہ گئے کہ ایک ہی رات میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے دریائے نیل میں سولہ ہاتھ پانی چڑھا دیا تھا اور یوں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مصر والوں کو اس غلط رسم سے ختم کرا دیا۔ اور آج تک وہ رسم ختم ہے (اس کے بغیر ہی دریائے نیل میں مسلسل پانی چل رہا ہے)۔",""],[" (14)","s"]]]],"f":[["(13)","A month in the Egyptian calendar."],["(14)","Laalkaa'ee in his Sunnah, as quoted in Tafseer of Ibn Katheer (Vol.3 Pg.464)."]]},{"b":[["n",[["حضرت سہم بن منجابؒ","b"],[" کہتے ہیں کہ ہم حضرت علاء بن حضرمیؓ کے ساتھ ایک غزوے میں گئے۔ ہم چلتے چلتے دارین (جزیرے) کے پاس پہنچ گئے۔ ہمارے اور دارین والوں کے درمیان سمندر تھا۔ حضرت علاءؓ نے یہ دعا مانگی: یا علی یا حلیم یا علی یا عظیم! ہم تیرے بندے ہیں اور تیرے راستے میں ہیں، تیرے دشمن سے جنگ کرنے آئے ہیں۔ اے ",""],["ٱللَّٰه","a"],["! دشمن تک پہنچنے کا ہمارے لیے راستہ بنا دے۔ اس کے بعد حضرت علاءؓ ہمیں لے کر سمندر میں اتر گئے اور ہم بھی ان کے ساتھ گھس گئے لیکن سمندر کا پانی ہماری زین کے نمدوں تک بھی نہیں پہنچا اور ہم لوگ ان تک پہنچ گئے۔",""],["(15)","s"],[" حضرت ابوہریرہؓ سے بھی اس جیسی سمندر والی حدیث منقول ہے۔ اس میں یہ مضمون بھی ہے کہ کسریٰ کے گورنر ابن مکعبر نے جب ہمیں (یوں سمندر پر چل کر آتے ہوئے) دیکھا تو اس نے کہا نہیں ",""],["ٱللَّٰه","a"],[" کی قسم! ہم ان لوگوں سے نہیں لڑ سکتے (ان کے ساتھ ",""],["ٱللَّٰه","a"],[" کی غیبی مدد ہے)۔ پھر وہ کشتی میں بیٹھ کر فارس چلا گیا۔",""],["(16)","s"],[" اور عنقریب جنگ قادسیہ کے دن حضرت سعد بن ابی وقاصؓ کے دریائے دجلہ پار کرنے کے بارے میں احادیث آئیں گی اور ان میں حضرت حجر بن عدیؓ کا یہ قول بھی آئے گا کہ آپ لوگوں کو پار کر کے دشمن تک پہنچنے سے صرف پانی کی یہ بوند یعنی دریائے دجلہ روک رہا ہے، پھر یہ آیت پڑھی:",""]]],["q",[["وَمَا كَانَ لِنَفْسٍ أَنْ تَمُوتَ إِلَّا بِإِذْنِ ٱللَّٰهِ كِتَابًا مُّؤَجَّلًا  (سورۃ آل عمران: ۱۴۵)","a"]]],["p",[["ترجمہ: \"اور کسی شخص کو موت آنا ممکن نہیں بدون حکم ",""],["ٱللَّٰه","a"],[" تعالیٰ کے، اس طور سے کہ اس کی معیاد معین لکھی ہوئی رہتی ہے۔\" پھر حضرت حجر بن عدیؓ نے اپنا گھوڑا دریائے دجلہ میں ڈال دیا۔ جب انہوں نے ڈالا تو تمام لوگوں نے اپنے جانور دریا میں ڈال دیے۔ جب دشمن کے لوگوں نے ان کو (یوں دریا پر چل کر) آتے ہوئے دیکھا تو وہ کہنے لگے \"دیو آ گئے، دیو آ گئے\"، اور دشمن کے لوگ (آخر کار) بھاگ گئے۔",""]]]],"f":[["(15)","Abu Nu'aym in his Hilya (Vol.1 Pg.7)."],["(16)","Abu Nu'aym in his Hilya (Vol.1 Pg.8). Tabraani, Ibn Abi Dunya and Bayhaqi have also reported the narration."]]},{"b":[["n",[["حضرت معاویہ بن حرملؒ","b"],[" کہتے ہیں کہ ایک مرتبہ (مدینہ منورہ کے پتھریلے میدان) حرہ میں آگ نکلی تو حضرت عمرؓ حضرت تمیمؓ کے پاس گئے اور ان سے فرمایا کہ اٹھو اور اس آگ کا انتظام کرو۔ حضرت تمیمؓ نے کہا اے امیر المومنین! میں کون ہوں؟ میں کیا ہوں؟ (تواضع کرنے لگے)۔ حضرت عمرؓ ان پر اصرار کرتے رہے یہاں تک کہ حضرت تمیمؓ کھڑے ہو گئے اور دونوں آگ کی طرف چل پڑے اور میں ان کے پیچھے چلنے لگا۔ وہاں پہنچ کر حضرت تمیمؓ آگ کو اپنے ہاتھ سے دھکا دیتے رہے یہاں تک کہ وہ آگ (اس) گھاٹی میں داخل ہو گئی (جس میں سے نکل کر آئی تھی) اور آگ کے پیچھے حضرت تمیمؓ بھی گھاٹی کے اندر چلے گئے۔ یہ دیکھ کر حضرت عمرؓ فرمانے لگے کہ ",""],["جس نے یہ منظر نہیں دیکھا وہ دیکھنے والے کے برابر نہیں ہو سکتا","h"],[" (کیونکہ اس نے دیکھ کر ایمان تازہ کر لیا ہے)۔",""],[" (17)","s"]]]],"f":[["(17)","Abu Nu'aym in his Dalaa'il (Pg.212)."]]},{"b":[["n",[["بحرین کے ایک صاحب حضرت ابوسکینہؒ","b"],[" نبی کریم ",""],["ﷺ","a"],[" کے ایک صحابیؓ سے روایت کرتے ہیں کہ جب نبی کریم ",""],["ﷺ","a"],[" نے خندق کھودنے کا حکم دیا تو (خندق کھودتے ہوئے) صحابہؓ کے سامنے ایک چٹان آ گئی جس نے صحابہؓ کو خندق کھودنے سے روک دیا۔ حضورؐ خندق کے ایک کنارے پر چادر رکھ کر کھڑے ہوئے اور کدال لے کر یہ آیت پڑھی:",""]]],["q",[["وَتَمَّتْ كَلِمَتُ رَبِّكَ صِدْقًا وَعَدْلًا لَّا مُبَدِّلَ لِكَلِمَاتِهِ ۚ وَهُوَ ٱلسَّمِيعُ ٱلْعَلِيمُ  (سورۃ الانعام: ۱۱۵)","a"]]],["p",[["ترجمہ: \"اور آپ کے رب کا کلام واقعیت اور اعتدال کے اعتبار سے کامل ہے۔ اس کے کلام کا کوئی بدلنے والا نہیں اور وہ خوب سن رہے ہیں اور خوب جان رہے ہیں۔\" اور آپؐ نے زور سے کدال چٹان پر ماری تو چٹان کا تہائی حصہ ٹوٹ کر گر پڑا۔ حضرت سلمان فارسیؓ کھڑے ہوئے دیکھ رہے تھے۔ حضورؐ کے کدال مارنے کے ساتھ ایک چمک ظاہر ہوئی۔ پھر آپؐ نے دوبارہ وہی آیت پڑھ کر کدال ماری تو چٹان کا دوسرا تہائی حصہ بھی ٹوٹ کر گر پڑا اور پھر دوبارہ ایک چمک ظاہر ہوئی جسے حضرت سلمانؓ نے دیکھا۔ حضورؐ نے تیسری مرتبہ وہی آیت پڑھ کر کدال ماری تو چٹان کا آخری تیسرا حصہ بھی ٹوٹ کر گر پڑا۔ پھر حضورؐ خندق سے باہر تشریف لائے اور اپنی چادر لے کر بیٹھ گئے۔ حضرت سلمانؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے دیکھا کہ آپؐ جب بھی چٹان پر چوٹ مارتے تو اس کے ساتھ ایک چمک ظاہر ہوتی۔ نبی کریم ",""],["ﷺ","a"],[" نے فرمایا اے سلمان! کیا تم نے اسے دیکھا؟ حضرت سلمانؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! اس ذات کی قسم جس نے آپؐ کو حق دے کر بھیجا ہے، ہاں میں نے اسے دیکھا ہے۔ حضورؐ نے فرمایا:",""]]],["c",[["جب میں نے پہلی دفعہ چوٹ ماری تھی تو اس وقت کسریٰ کا شہر مدائن اور اس کے آس پاس کے علاقے اور بہت سارے شہر میرے سامنے ظاہر کر دیے گئے جنہیں میں نے دیکھا۔",""]]],["p",[["وہاں جو صحابہؓ اس وقت موجود تھے انہوں نے حضورؐ کی خدمت میں عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ ",""],["ٱللَّٰه","a"],[" سے یہ دعا کریں کہ وہ یہ تمام شہر فتح کر کے ہمیں دے دے اور ان کی اولاد کو ہمارے لیے مال غنیمت بنا دے اور ان کے شہروں کو ہمارے ہاتھوں اجاڑ دے۔ چنانچہ آپؐ نے یہ دعا فرمائی۔",""]]],["c",[["پھر میں نے دوسری مرتبہ چوٹ ماری تو قیصر کے شہر اور اس پاس کے علاقے میرے سامنے ظاہر کر دیے گئے جنہیں میں نے اپنی آنکھوں سے دیکھا۔",""]]],["p",[["صحابہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ ",""],["ٱللَّٰه","a"],[" سے یہ دعا کریں کہ وہ یہ تمام علاقے فتح کر کے ہمیں دے دے اور ان کی اولاد کو ہمارے لیے مال غنیمت بنا دے اور ان کے شہروں کو ہمارے ہاتھوں اجاڑ دے۔ چنانچہ آپؐ نے یہ دعا فرمائی۔",""]]],["c",[["پھر میں نے تیسری مرتبہ چوٹ ماری تو حبشہ کے شہر اور اس پاس کے علاقے میرے سامنے ظاہر کیے گئے جنہیں میں نے اپنی آنکھوں سے دیکھا۔",""]]],["p",[["پھر حضورؐ نے فرمایا جب تک حبشہ والے تمہیں چھوڑے رکھیں تم بھی انہیں چھوڑے رکھو اور جب تک ترک تمہیں چھوڑے رکھیں تم بھی انہیں چھوڑے رکھو۔ (یہ حکم شروع میں تھا، بعد میں یہ حکم منسوخ ہو گیا اور ہر ملک میں جانے کا حکم آ گیا)۔",""],[" (18)","s"]]]],"f":[["(18)","Nasa'ee, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.102). Abu Dawood has reported the concluding portion which states: \"You should however leave the Abyssinians alone as long as they leave you alone and also leave the Turks alone as long as they leave you alone.\""]]},{"b":[["n",[["حضرت عمرو بن عوف مزنیؓ","b"],[" ایک حدیث ذکر فرماتے ہیں جس میں یہ مضمون ہے کہ حضورؐ تشریف لائے اور حضرت سلمانؓ سے کدال لے کر اس زور سے ماری کہ چٹان ٹکڑے ٹکڑے ہو گئی اور اس میں سے ایک روشنی نکلی جس سے سارا مدینہ روشن ہو گیا اور ایسا لگا کہ جیسے اندھیری رات میں چراغ جل رہا ہو۔ حضورؐ نے ایسی تکبیر کہی جیسے دشمن پر فتح کے وقت کہی جاتی ہے اور مسلمانوں نے بھی تکبیر کہی۔ اور حضورؐ نے دوبارہ کدال ماری تو پھر ایسے ہی ہوا۔ حضورؐ نے تیسری مرتبہ کدال ماری تو پھر ایسے ہی ہوا۔ پھر حضرت سلمانؓ اور مسلمانوں نے حضورؐ سے اس کا تذکرہ کیا اور اس روشنی کے بارے میں پوچھا۔ حضورؐ نے فرمایا:",""]]],["c",[["پہلی چوٹ لگنے سے میرے سامنے حیرہ مقام کے محل اور کسریٰ کے مدائن ایسے روشن ہو گئے جیسے کتے کے نوکدار دانت چمکتے ہیں اور حضرت جبرائیلؑ نے مجھے بتایا کہ میری امت ان پر غلبہ حاصل کرے گی۔ اور دوسری چوٹ لگانے سے روم کے سرخ محل ایسے روشن ہو گئے جیسے کہ کتے کے نوکدار دانت چمکتے ہیں اور حضرت جبرائیل علیہ السلام نے مجھے بتایا کہ میری امت ان پر غلبہ حاصل کرے گی۔ اور تیسری مرتبہ چوٹ لگانے سے صنعاء کے محل ایسے روشن ہو گئے جیسے کتے کے نوکدار دانت چمکتے ہیں۔ اور حضرت جبرائیلؑ نے مجھے بتایا کہ میری امت ان پر غلبہ حاصل کرے گی، اس لیے تم سب خوشخبری حاصل کرو۔",""]]],["p",[["یہ سن کر تمام مسلمان بہت خوش ہوئے اور انہوں نے کہا الحمد للہ! یہ سچا وعدہ ہے اور جب کفار کی جماعتیں خندق پر پہنچیں تو مسلمانوں نے کہا یہ تو وہی ہو رہا ہے جس کی ہمیں ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ نے خبر دی تھی اور ",""],["ٱللَّٰه","a"],[" تعالیٰ اور اس کے رسولؐ نے سچ فرمایا تھا (اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا:) اس واقعہ نے مسلمانوں کے ایمان اور اطاعت کو اور بڑھا دیا۔ اور منافقوں نے کہا رسولؐ تمہیں یہ بتا رہے ہیں کہ وہ یثرب یعنی مدینہ سے ہی حیرہ کے محل اور کسریٰ کا مدائن دیکھ رہے ہیں اور وہ فتح ہو کر تمہیں ملیں گے اور تمہارا حال یہ ہے کہ تم لوگ خندق کھود رہے ہو اور تم لوگ تو میدان میں ان کے سامنے جا بھی نہیں سکتے۔ اس پر منافقوں کے بارے میں یہ آیت نازل ہوئی:",""]]],["q",[["وَإِذْ يَقُولُ ٱلْمُنَٰفِقُونَ وَٱلَّذِينَ فِى قُلُوبِهِم مَّرَضٌ مَّا وَعَدَنَا ٱللَّهُ وَرَسُولُهُۥٓ إِلَّا غُرُورًا  (سورۃ الاحزاب: ۱۲)","a"]]],["p",[["ترجمہ: \"اور جبکہ منافقین اور وہ لوگ جن کے دلوں میں مرض ہے یوں کہہ رہے تھے کہ ہم سے ",""],["ٱللَّٰه","a"],[" نے اور اس کے رسولؐ نے محض دھوکہ ہی کا وعدہ کر رکھا ہے۔\"",""],[" (19)","s"]]],["p",[["تائیدات غیبیہ کے باب میں غزوات میں کھانے کی برکت کے عنوان میں حضرت ابن عباسؓ کی ایک لمبی حدیث آ رہی ہے جس میں یہ ہے کہ حضورؐ نے فرمایا مجھے چھوڑو، سب سے پہلے میں اس پتھر پر چوٹ ماروں گا۔ چنانچہ آپؐ نے بسم ",""],["ٱللَّٰه","a"],[" پڑھی اور اس پتھر پر ایسی چوٹ ماری جس سے اس کا ایک تہائی حصہ ٹوٹ کر گر گیا اور آپؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" اکبر! رب کعبہ کی قسم! روم کے محلات! آپؐ نے پھر اس پر ایسی چوٹ ماری جس سے ایک اور ٹکڑا ٹوٹ کر گر پڑا، آپؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" اکبر! رب کعبہ کی قسم! فارس کے محلات! اس پر منافقوں نے کہا کہ ہم تو (اپنی جان بچانے کے لیے) اپنے ارد گرد خندق کھود رہے ہیں اور یہ ہم سے فارس اور روم کے محلات کا وعدہ کر رہے ہیں۔",""]]],["p",[["اور عنقریب تائیدات غیبیہ کے باب میں زہر کے اثر نہ ہونے کے عنوان میں یہ مضمون آئے گا کہ حضرت خالدؓ نے زہر پیا اور فرمایا کوئی انسان اپنے وقت سے پہلے نہیں مر سکتا۔ اور یہ بھی آئے گا کہ حضرت عمروؓ نے کہا اے عربوں کی جماعت! جب تک تمہارے طبقہ (صحابہؓ) کا ایک فرد بھی باقی رہے گا تم جس کام یا ملک کا ارادہ کرو گے اس کے مالک بن جاؤ گے۔ اور یہ بھی آئے گا کہ حضرت عمروؓ نے حیرہ والوں سے کہا میں نے آج جیسا واضح دلیل والا دن کبھی نہیں دیکھا۔ اور نصرت خداوندی کے اسباب کے باب میں آئے گا کہ حضرت ثابت بن اقرمؓ نے کہا اے ابوہریرہ! ایسے لگ رہا ہے کہ آپ دشمن کی بہت زیادہ فوجیں دیکھ رہے ہیں (حضرت ابوہریرہؓ کہتے ہیں) میں نے کہا جی ہاں۔ حضرت ثابتؓ نے کہا آپ ہمارے ساتھ جنگ بدر میں شریک نہیں ہوئے تھے (",""],["ٱللَّٰه","a"],[" کی طرف سے) ہماری مدد تعداد کی کثرت کی وجہ سے نہیں ہوتی (وہ تو ایمان و اعمال اور داعیانہ جذبات کی وجہ سے ہوتی ہے)۔ اور یہ بھی آئے گا کہ ایک آدمی نے حضرت خالدؓ سے کہا آج رومی کتنے زیادہ اور مسلمان کتنے کم ہیں۔ حضرت خالدؓ نے کہا نہیں، رومی کتنے کم اور مسلمان کتنے زیادہ ہیں۔ لشکر نصرت خداوندی سے زیادہ ہوتے ہیں اور نصرت خداوندی سے محروم ہوں تو کم ہو جاتے ہیں۔ کثرت اور قلت کا دار و مدار انسانوں کی تعداد پر نہیں ہے۔ ",""],["ٱللَّٰه","a"],[" کی قسم! میری تمنا ہے کہ میرا اشقر نامی گھوڑا تندرست ہو جائے اور رومیوں کی تعداد دگنی ہو جائے۔ اور یہ بھی آئے گا کہ حضرت ابوبکرؓ نے حضرت عمرو بن العاصؓ کو یہ خط لکھا: امابعد! تمہارا خط میرے پاس آیا جس میں تم نے لکھا ہے کہ رومیوں کے لشکر بہت زیادہ جمع ہو گئے ہیں۔ یاد رکھو! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اپنے نبیؐ کے ساتھ ہماری مدد سامان کی کثرت اور لشکروں کی کثرت کی وجہ سے نہیں کی تھی۔ ہم حضورؐ کے ساتھ غزوے میں جایا کرتے تھے اور ہمارے ساتھ صرف دو گھوڑے ہوتے تھے اور بعض غزوات میں اونٹ اتنے کم ہوتے تھے کہ ہم باری باری ان پر سوار ہوتے تھے۔ اور جنگ احد کے دن ہم حضورؐ کے ساتھ تھے، ہمارے پاس صرف ایک گھوڑا تھا جس پر حضورؐ سوار تھے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمارے تمام مخالفوں کے خلاف ہماری پشت پناہی کرتے تھے۔",""],["(20)","s"],[" اور پہلے یہ بھی گزر چکا ہے کہ حضرت ابوبکرؓ نے بڑے سخت حالات کے باوجود حضرت اسامہؓ کا لشکر روانہ فرمایا تھا۔",""],["(21)","s"],[" ہر طرف سے عرب ان پر ٹوٹ پڑے تھے (چند قبائل کے سوا) سارے عرب والے مرتد ہو گئے تھے اور نفاق ظاہر ہو گیا تھا اور یہودیت اور نصرانیت گردن اٹھانے لگی تھی، اور چونکہ حضورؐ کے حادثہ انتقال کا صدمہ تازہ تھا اور صحابہؓ کی تعداد کم اور دشمن کی تعداد زیادہ تھی اس وجہ سے صحابہؓ کی حالت اس بکری جیسی تھی جو سخت سردی والی رات میں بارش میں بھیگ گئی ہو۔ اور صحابہؓ نے حضرت ابوبکرؓ کو یہ مشورہ دیا تھا کہ وہ حضرت اسامہؓ کے لشکر کو روک لیں لیکن حضرت ابوبکرؓ چونکہ صحابہؓ میں سب سے زیادہ سمجھدار اور دور اندیش تھے اس وجہ سے انہوں نے کہا کیا میں اس لشکر کو روک لوں جسے رسول ",""],["ٱللَّٰه","a"],["ؐ نے بھیجا؟ اگر میں ایسا کروں تو یہ میری بہت بڑی جسارت ہوگی۔ اس ذات کی قسم! جس کے قبضے میں میری جان ہے سارے عرب مجھ پر ٹوٹ پڑیں یہ مجھے اس سے زیادہ پسند ہے کہ میں اس لشکر کو جانے سے روک دوں جسے حضورؐ نے روانہ فرمایا تھا۔ اے اسامہ! تم اپنے لشکر کو لے کر وہاں جاؤ جہاں جانے کا تمہیں حکم ہوا تھا اور فلسطین کے جس علاقے میں جا کر لڑنے کا حضورؐ نے تمہیں حکم دیا تھا وہاں جا کر اہل موتہ سے لڑو، تم جنہیں یہاں چھوڑ کر جا رہے ہو ",""],["ٱللَّٰه","a"],[" ان کے لیے کافی ہے۔ اور غزوہ موتہ کے دن کے بیان میں یہ گزر چکا ہے کہ جب دشمن کی تعداد دو لاکھ ہو گئی تو حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ نے کہا اے میری قوم! ",""],["ٱللَّٰه","a"],[" کی قسم! جس شہادت کو تم پسند نہیں کر رہے ہو (حقیقت میں) تم اسی کی تلاش میں نکلے ہو۔ ہم لوگوں سے جنگ تعداد، طاقت اور کثرت کی بنیاد پر نہیں کرتے بلکہ ہم تو لوگوں سے جنگ اس دین کی بنیاد پر کرتے ہیں جس کے ذریعے ",""],["ٱللَّٰه","a"],[" نے ہمیں عزت عطا فرمائی ہے، لہٰذا چلو دو کامیابیوں میں سے ایک کامیابی تو ضرور ملے گی یا دشمن پر غلبہ یا ",""],["ٱللَّٰه","a"],[" کے راستے کی شہادت۔ اس پر لوگوں نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! ابن رواحہؓ نے بالکل ٹھیک کہا ہے۔",""],["(22)","s"],[" اس بارے میں صحابہؓ کے کتنے قصے اس کتاب میں جگہ جگہ موجود ہیں بلکہ احادیث، غزوات اور سیرت کی کتابوں میں بھی کثرت سے موجود ہیں، لہٰذا انہیں دوبارہ ذکر کر کے ہم اس کتاب کو مزید لمبا نہیں کرنا چاہتے۔",""]]]],"f":[["(19)","Ibn Jareer, as quoted in Al Bidaayah wan Nihaayah (Vol.4 Pg.100)."],["(20)","Tabraani. Haythami (Vol.6 Pg.132) has commented on the chain of narrators."],["(21)","Under the heading \"Dispatching the Army of Hadhrat Usaama bin Zaid even on his Deathbed, after which Hadhrat Abu Bakr also Gives the Same Importance to the Matter When he Becomes the Khalifah\" and the subheading \"Hadhrat Abu Bakr Rejects the Request of the Muhaajireen and Ansaar to hold back the Army of Hadhrat Usaama\"."],["(22)","Under the heading \"The Enthusiasm of the Sahabah to Die and Give their Lives in the path of Allaah\" and the subheading \"Hadhrat Abdullaah bin Rawaaha Encourages the Sahabah towards Martyrdom\"."]]}]},"5":{"lead":[],"stories":[{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ ایک دن حضورؐ مسجد میں تشریف لے گئے تو وہاں حضرت حارث بن مالکؓ سو رہے تھے۔ حضورؐ نے ان کو پاؤں سے ہلایا اور فرمایا اپنا سر اٹھاؤ۔ انہوں نے سر اٹھا کر کہا یا رسول ",""],["ٱللَّٰه","a"],["! میں آپ پر قربان ہوں۔ حضورؐ نے فرمایا اے حارث بن مالک! تم نے کس حال میں صبح کی؟ انہوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے پکا سچا مومن ہونے کی حالت میں صبح کی ہے۔ حضورؐ نے فرمایا:",""]]],["c",[["ہر حق بات کی کوئی حقیقت ہوا کرتی ہے، جو تم کہہ رہے ہو اس کی حقیقت کیا ہے؟",""]]],["p",[["حضرت حارثؓ نے عرض کیا میں نے اپنے آپ کو دنیا سے ہٹا لیا اور دن کو میں پیاسا رہتا ہوں یعنی روزہ رکھتا ہوں اور رات کو جاگتا ہوں اور مجھے ایسے معلوم ہوتا ہے کہ جیسے میں اپنے رب کے عرش کو دیکھ رہا ہوں اور جنت والوں کو جنت میں ایک دوسرے کی زیارت کرتے ہوئے دیکھ رہا ہوں اور جہنم والوں کو ایک دوسرے پر بھوکتے ہوئے دیکھ رہا ہوں۔ حضورؐ نے ان سے فرمایا:",""]]],["c",[["ٱللَّٰه","a"],[" تعالیٰ نے تمہارا دل نورانی بنا دیا ہے اور تم نے (ایمان کی حقیقت کو) پہچان لیا ہے، لہٰذا تم اس (ایمانی کیفیت) پر ٹکے رہو۔",""]]],["p",[["ایک روایت میں یہ ہے کہ حضورؐ نے فرمایا تم نے (حقیقت کو) دیکھ لیا ہے اب اس کو مضبوطی سے پکڑ لو۔ پھر حضورؐ نے فرمایا اس بندے کے دل میں ",""],["ٱللَّٰه","a"],[" نے ایمان کو روشن کیا ہے۔ انہوں نے عرض کیا اے ",""],["ٱللَّٰه","a"],[" کے نبی! آپ میرے لیے ",""],["ٱللَّٰه","a"],[" سے شہادت کی دعا فرما دیں۔ حضورؐ نے دعا فرما دی۔ چنانچہ ایک دن اعلان ہوا کہ اے ",""],["ٱللَّٰه","a"],[" کے سوارو! (گھوڑوں پر) سوار ہو جاؤ۔ اس پر یہی سب سے پہلے سوار ہوئے اور یہی سب سے پہلے شہید ہوئے۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Asaakir."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ ایک دن حضورؐ تشریف لے جا رہے تھے کہ سامنے سے ایک انصاری نوجوان آئے۔ حضورؐ نے ان سے فرمایا اے حارث! تم نے کس حال میں صبح کی؟ انہوں نے عرض کیا میں نے ",""],["ٱللَّٰه","a"],[" پر پختہ ایمان لانے کی حالت میں صبح کی ہے۔ حضورؐ نے فرمایا تم دیکھ لو کیا کہہ رہے ہو؟ کیونکہ ہر قول کی حقیقت ہوا کرتی ہے۔ انہوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے اپنا دل دنیا سے ہٹا لیا ہے۔ پھر آگے عسکری جیسی حدیث ذکر کی ہے اور مزید کچھ اور مضمون بھی ہے۔",""],["(2)","s"],[" اور ایک روایت میں یہ ہے کہ حضورؐ نے فرمایا ہر قول کی کوئی حقیقت ہوا کرتی ہے تمہارے ایمان کی کیا حقیقت ہے؟",""],["(3)","s"]]]],"f":[["(2)","Askari, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.160)."],["(3)","Ibn Najjaar, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.161)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ ایک مرتبہ حضرت معاذ بن جبلؓ حضورؐ کی خدمت میں حاضر ہوئے۔ حضورؐ نے فرمایا تم نے کس حال میں صبح کی؟ حضرت معاذؓ نے عرض کیا میں نے آپؐ پر ایمان لانے کی حالت میں صبح کی۔ حضورؐ نے فرمایا:",""]]],["c",[["ہر بات کی سچائی کی کوئی دلیل ہوتی ہے اور ہر حق بات کی ایک حقیقت ہوتی ہے، تمہاری بات کی سچائی کی کیا دلیل ہے؟",""]]],["p",[["حضرت معاذؓ نے عرض کیا اے ",""],["ٱللَّٰه","a"],[" کے نبی! جب بھی صبح ہوتی ہے میں یہ سمجھتا ہوں کہ میں شام نہیں کر سکوں گا اور جب بھی شام ہوتی ہے میں یہ سمجھتا ہوں کہ میں صبح نہیں کر سکوں گا اور جب بھی کوئی قدم اٹھاتا ہوں تو یہ گمان کرتا ہوں کہ میں دوسرا قدم نہیں اٹھا سکوں گا اور گویا کہ میں ان تمام امتوں کی طرف دیکھ رہا ہوں جو گھٹنوں کے بل بیٹھی ہوئی ہیں اور انہیں ان کے اعمال نامے کی طرف بلایا جا رہا ہے اور ان کے ساتھ ان کے نبی بھی ہیں، اور ان کے ساتھ وہ بت بھی ہیں جن کی وہ ",""],["ٱللَّٰه","a"],[" کے علاوہ عبادت کیا کرتے تھے، اور گویا کہ میں جہنم والوں کی سزا اور جنت والوں کے اجر و ثواب کو دیکھ رہا ہوں۔ حضورؐ نے فرمایا تم نے (ایمان کی حقیقت) پہچان لی، اب اسی پر جمے رہنا۔",""],[" (4)","s"]]],["p",[["ٱللَّٰه","a"],[" اور اس کے رسولؐ کی طرف دعوت دینے کے باب میں",""],["(5)","s"],[" حضرت سوید بن حارثؓ کی یہ حدیث گزر چکی ہے کہ وہ فرماتے ہیں کہ میں اپنی قوم کے سات آدمیوں کا وفد لے کر حضورؐ کی خدمت میں گیا۔ جب ہم آپؐ کی خدمت میں حاضر ہوئے اور ہم نے آپؐ سے گفتگو کی تو آپؐ کو ہمارا انداز گفتگو اور انداز نشست و برخاست اور لباس پسند آیا۔ آپؐ نے فرمایا تم کون لوگ ہو؟ ہم نے عرض کیا ہم مومن ہیں۔ اس پر آپؐ مسکرانے لگے اور فرمایا ہر بات کی ایک حقیقت اور نشانی ہوا کرتی ہے۔ تمہارے اس قول اور ایمان کی کیا حقیقت اور نشانی ہے؟ حضرت سویدؓ فرماتے ہیں ہم نے عرض کیا پندرہ خصلتیں ہیں، ان میں سے پانچ خصلتیں تو وہ ہیں جن کے بارے میں آپؐ کے قاصدوں نے ہمیں حکم دیا کہ ہم ان پر ایمان لائیں اور ان میں سے پانچ خصلتیں وہ ہیں جن کے بارے میں آپؐ کے قاصدوں نے ہمیں حکم دیا کہ ہم ان پر عمل کریں اور ان میں سے پانچ خصلتیں وہ ہیں جن کو ہم نے زمانہ جاہلیت میں اختیار کیا تھا اور ہم اب تک ان پر قائم ہیں، لیکن اگر ان میں سے کسی کو آپؐ ناگوار سمجھیں تو ہم اسے چھوڑ دیں گے۔ پھر آگے ",""],["ٱللَّٰه","a"],[" اور اس کے فرشتوں اور اس کی کتابوں اور اس کے رسولوں پر اور اچھی بری تقدیر پر ایمان لانے اور ارکان اسلام اور اخلاق طیبہ کے بارے میں حدیث ذکر کی ہے۔",""]]]],"f":[["(4)","Ibn Mubaarak in his Zuhd. Haafidh has commented on the chain of narrators, as quoted in Isaabah (Vol.1 Pg.289). Abdur Razzaaq has reported a similar narration, as have Tabraani, Ibn Mandah, Bayhaqi and Bazzaar, but Haythami (Vol.1 Pg.57) has commented on the chains of narrators of Bazzaar and Tabraani."],["(5)","Under the heading \"Rasulullaah Calls people towards Fulfilling the Faraa'idh of Islaam\" and the subheading \"The Hadith of Hadhrat Alqama Concerning the Reality of Imaan, Giving Da'wah towards Imaan and the Faraa'idh\"."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ میں نبی کریم ",""],["ﷺ","a"],[" کے پاس بیٹھا ہوا تھا کہ اتنے میں قبیلہ بنو حارثہ کے حضرت حرملہ بن زید انصاریؓ آئے اور انہوں نے حضورؐ کے سامنے بیٹھ کر ہاتھ سے زبان کی طرف اشارہ کرتے ہوئے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ایمان یہاں پر ہے اور سینے پر ہاتھ رکھ کر کہا، اور یہاں نفاق ہے اور یہ دل ",""],["ٱللَّٰه","a"],[" کا ذکر بہت کم کرتا ہے۔ حضورؐ خاموش رہے۔ حضرت حرملہؓ نے اپنی بات پھر دہرائی۔ حضورؐ نے حضرت حرملہؓ کی زبان کا کنارہ پکڑ کر فرمایا:",""]]],["c",[["اے ",""],["ٱللَّٰه","a"],["! اس کی زبان کو سچ بولنے والا اور اس کے دل کو شکر کرنے والا بنا دے اور اسے میری محبت نصیب فرما اور جو مجھ سے محبت کرے اس کی محبت بھی اسے نصیب فرما اور اس کے معاملے کو خیر کی طرف موڑ دے۔",""]]],["p",[["حضرت حرملہؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میرے بہت سے بھائی منافق ہیں، میں ان کا سردار تھا، کیا میں آپؐ کو ان کے نام نہ بتاؤں؟ حضورؐ نے فرمایا جو بھی ہمارے پاس اس طرح آئے گا جس طرح تم ہمارے پاس آئے ہم اس کے لیے ایسے ہی استغفار کریں گے جیسے ہم نے تمہارے لیے کیا اور جو نفاق پر ہی ڈٹا رہے گا تو ",""],["ٱللَّٰه","a"],[" اس سے خود ہی نبٹ لیں گے۔",""],[" (6)","s"]]]],"f":[["(6)","Abu Nu'aym in his Hilya (Vol.1 Pg.242)."]]}]},"6":{"lead":[],"stories":[{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ حضورؐ نے ایک آدمی کو ایک لشکر کا امیر بنا کر بھیجا۔ وہ جب بھی اپنے ساتھیوں کو نماز پڑھاتا تو قُلْ هُوَ ٱللَّهُ أَحَدٌ ضرور پڑھتا۔ جب وہ لوگ واپس آئے تو انہوں نے حضورؐ سے اس کا تذکرہ کیا۔ حضورؐ نے فرمایا اس سے پوچھو وہ ایسا کیوں کرتا ہے؟ ان لوگوں نے اس سے پوچھا تو اس نے بتایا کہ چونکہ اس سورت میں رحمن کی صفات کا تذکرہ ہے اس لیے اس کا پڑھنا مجھے بہت پسند ہے۔ حضورؐ نے فرمایا:",""]]],["c",[["اسے بتا دو کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے محبت کرتے ہیں۔",""],[" (1)","s"]]]],"f":[["(1)","Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.2 Pg.250). Tabraani and Ibn Mandah have also reported the narration, as quoted in Isaabah (Vol.1 Pg.320)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں کہ ایک یہودی عالم نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا، یا محمد! یا کہا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آسمانوں کو ایک انگلی پر، زمینوں کو دوسری انگلی پر رکھا، درختوں، پہاڑوں، پانی اور گیلی مٹی کو تیسری انگلی پر اور باقی ساری مخلوق کو چوتھی انگلی پر رکھا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ ان تمام چیزوں کو ہلا کر فرماتے ہیں کہ میں ہی بادشاہ ہوں۔",""],["(2)","s"],[" ",""],["حضورؐ اس یہودی عالم کی اس بات کی تصدیق کرتے ہوئے اتنا ہنسے کہ آپؐ کے دندان مبارک ظاہر ہو گئے۔","h"],[" پھر آپؐ نے یہ آیت آخر تک پڑھی:",""]]],["q",[["وَمَا قَدَرُوا ٱللَّهَ حَقَّ قَدْرِهِۦ وَٱلْأَرْضُ جَمِيعًا قَبْضَتُهُۥ يَوْمَ ٱلْقِيَٰمَةِ وَٱلسَّمَٰوَٰتُ مَطْوِيَّٰتٌۢ بِيَمِينِهِۦ ۚ سُبْحَٰنَهُۥ وَتَعَٰلَىٰ عَمَّا يُشْرِكُونَ  (سورۃ الزمر: ۶۷)","a"]]],["p",[["ترجمہ: \"ان لوگوں نے ",""],["ٱللَّٰه","a"],[" تعالیٰ کی کچھ عظمت نہ کی جیسی عظمت کرنا چاہیے تھی، حالانکہ (اس کی وہ شان ہے کہ) ساری زمین اس کی مٹھی میں ہوگی قیامت کے دن اور تمام آسمان لپٹے ہوں گے اس کے داہنے ہاتھ میں",""],["(3)","s"],["۔ وہ پاک اور برتر ہے ان کے شرک سے۔\"",""],[" (4)","s"]]]],"f":[["(2)","Bayhaqi in his Asmaa was Sifaat (Pg.208), as quoted by Bukhaari and Muslim as well."],["(3)","The meaning of this is best known to Allaah. Allaah says about such verses, \"None knows their interpretation except Allaah\" [Surah Aal Imraan, verse 7]."],["(4)","Bayhaqi in his Asmaa was Sifaat (Pg.245), as quoted by Bukhaari and Muslim as well."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ حضورؐ سے کسی نے پوچھا کہ قیامت کے دن کافر کو کیسے منہ کے بل",""],["(5)","s"],[" اٹھایا جائے گا؟ حضورؐ نے فرمایا جس ذات نے اسے دنیا میں پاؤں کے بل چلایا وہ اس بات پر بھی قادر ہے کہ اسے قیامت کے دن منہ کے بل چلائے۔",""],[" (6)","s"]]]],"f":[["(5)","As referred to in verse 97 of Surah Bani Israa'eel and verse 34 of Surah Furqaan."],["(6)","Bayhaqi in his Asmaa was Sifaat (Pg.256). Bukhaari, Muslim, Ahmad, Nasa'ee, Ibn Abi Haatim, Haakim and others have reported a similar narration, as quoted in Kanzul Ummaal (Vol.7 Pg.28)."]]},{"b":[["n",[["حضرت حذیفہ بن اسیدؓ","b"],[" کہتے ہیں کہ ایک مرتبہ حضرت ابوذرؓ نے کھڑے ہو کر (اپنی قوم سے) کہا اے بنو غفار! تم بات کیا کرو اور قسم نہ کھایا کرو کیونکہ صادق مصدوق (یعنی جو خود بھی سچ بولتے تھے اور ان سے فرشتہ بھی سچی بات آ کر کہتا تھا یعنی حضورؐ) نے مجھے یہ بتایا ہے کہ (قیامت کے دن) لوگوں کو تین جماعتوں میں اٹھایا جائے گا۔ ایک جماعت سواری پر ہوگی اور یہ لوگ کھاتے پیتے اور کپڑے پہنے ہوئے ہوں گے اور ایک جماعت پیدل بھاگ رہی ہوگی اور ایک جماعت کو فرشتے منہ کے بل گھسیٹ کر (جہنم کی) آگ کے پاس جمع کر رہے ہوں گے۔ ان میں سے ایک آدمی نے پوچھا کہ دو جماعتوں کو تو ہم نے پہچان لیا ہے لیکن جو لوگ پیدل بھاگ رہے ہوں گے ان کا یہ حال کیوں ہوگا؟ حضرت ابوذرؓ نے کہا ",""],["ٱللَّٰه","a"],[" تعالیٰ سواری پر آفت ڈال دیں گے اور ایک سواری بھی باقی نہ رہے گی۔ یہاں تک کہ ایک آدمی کے پاس ایک پسندیدہ باغ ہوگا وہ یہ باغ دے کر پالان والی بوڑھی اونٹنی لینا چاہے گا لیکن وہ بھی اسے نہ مل سکے گی۔",""],[" (7)","s"]]]],"f":[["(7)","Ahmad, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.65). Haakim (Vol.4 Pg.564) has also reported the narration from reliable sources, as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت عائشہ صدیقہؓ کے ماں جائے بھائی حضرت طفیل بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں کہ میں نے خواب میں دیکھا کہ نصاریٰ کی ایک جماعت سے میری ملاقات ہوئی۔ میں نے ان سے کہا اگر تم لوگ یہ دعویٰ نہ کرو کہ حضرت مسیح (علیہ السلام) ",""],["ٱللَّٰه","a"],[" کے بیٹے ہیں تو تم لوگ بہت اچھے ہو۔ انہوں نے کہا اگر تم لوگ یہ نہ کہو کہ جیسے ",""],["ٱللَّٰه","a"],[" نے چاہا اور جیسے محمد (",""],["ﷺ","a"],[") نے چاہا تو تم لوگ بھی بہت اچھے ہو جاؤ۔ پھر میری یہودیوں کی ایک جماعت سے ملاقات ہوئی۔ میں نے ان سے کہا اگر تم لوگ یہ دعویٰ نہ کرو کہ حضرت عزیر (علیہ السلام) ",""],["ٱللَّٰه","a"],[" کے بیٹے ہیں تو تم لوگ بہت اچھے ہو۔ انہوں نے کہا تم لوگ بھی بہت اچھے ہو، اگر تم یہ نہ کہتے ہو کہ جیسے ",""],["ٱللَّٰه","a"],[" نے چاہا اور جیسے محمد (",""],["ﷺ","a"],[") نے چاہا۔ میں نے نبی کریم ",""],["ﷺ","a"],[" کی خدمت میں حاضر ہو کر یہ خواب سنایا۔ حضورؐ نے فرمایا تم نے یہ خواب کسی کو بتایا ہے؟ میں نے کہا جی ہاں! پھر حضورؐ نے ",""],["ٱللَّٰه","a"],[" کی حمد و ثنا بیان فرما کر ارشاد فرمایا:",""]]],["c",[["تمہارے بھائی نے وہ خواب دیکھا ہے جس کا مضمون تم تک پہنچ چکا ہے، لہٰذا تم لوگ یہ نہ کہا کرو بلکہ یہ کہا کرو: جیسے ",""],["ٱللَّٰه","a"],[" وحدہ لا شریک لہ نے چاہا۔",""],[" (8)","s"]]]],"f":[["(8)","Bayhaqi in his Asmaa was Sifaat (Pg.110)."]]},{"b":[["n",[["حضرت حذیفہؓ","b"],[" فرماتے ہیں کہ مسلمانوں میں سے ایک آدمی نے خواب میں دیکھا کہ اہل کتاب میں سے ایک آدمی اسے ملا جس نے کہا اگر تم لوگ شرک نہ کرتے اور یوں نہ کہتے کہ جیسے ",""],["ٱللَّٰه","a"],[" اور محمدؐ نے چاہا تو تم لوگ بہت اچھے ہوتے۔ اس آدمی نے اس خواب کا ذکر حضورؐ سے کیا۔ حضورؐ نے فرمایا آپ لوگوں کی یہ بات مجھے بھی پسند نہیں۔ اس لیے آئندہ آپ لوگ یوں کہا کریں جیسے ",""],["ٱللَّٰه","a"],[" نے چاہا پھر جیسے فلاں نے چاہا، یعنی ",""],["ٱللَّٰه","a"],[" اور رسول دونوں کو ایک جملہ میں اکٹھا ملا کر نہ لاؤ بلکہ الگ الگ جملوں میں لے کر آؤ۔",""],[" (9)","s"]]]],"f":[["(9)","Bayhaqi in his Asmaa was Sifaat (Pg.110)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ ایک آدمی حاضر خدمت ہو کر حضورؐ سے کسی کام کے بارے میں بات کرنے لگا اور بات کرتے کرتے اس نے یوں کہہ دیا جیسے ",""],["ٱللَّٰه","a"],[" اور آپؐ چاہیں۔ حضورؐ نے فرمایا کیا تم نے مجھے ",""],["ٱللَّٰه","a"],[" کے برابر بنا دیا ہے؟ بلکہ یوں کہو جیسے اکیلا ",""],["ٱللَّٰه","a"],[" چاہے۔",""],[" (10)","s"]]]],"f":[["(10)","Bayhaqi in his Asmaa was Sifaat (Pg.110)."]]},{"b":[["n",[["حضرت اوزاعیؒ","b"],[" کہتے ہیں کہ ایک یہودی نے آ کر حضورؐ سے مشیت کے بارے میں پوچھا (کہ کس کے چاہنے سے کام ہوتا ہے)۔ حضورؐ نے فرمایا کام تو ",""],["ٱللَّٰه","a"],[" ہی کے چاہنے سے ہوتا ہے۔ اس یہودی نے کہا کہ میں کھڑا ہونا چاہتا ہوں (تو کھڑا ہو جاتا ہوں یعنی میرے چاہنے سے ہوا)۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے بھی تمہارے کھڑے ہونے کو چاہ لیا تھا (اس لیے تم کھڑے ہو سکے)۔ پھر اس یہودی نے کہا میں بیٹھنا چاہتا ہوں (تو بیٹھ جاتا ہوں)۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" نے بھی تمہارے بیٹھنے کو چاہ لیا تھا۔ اس یہودی نے کہا میں کھجور کے اس درخت کو کاٹنا چاہتا ہوں (تو کاٹ لیتا ہوں)۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" نے چاہ لیا تھا کہ تم اس درخت کو کاٹ لو۔ اس یہودی نے کہا میں اس درخت کو باقی رکھنا چاہتا ہوں (تو وہ باقی رہ جاتا ہے)۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" نے چاہ لیا تھا کہ تم اسے باقی رکھو۔ حضرت اوزاعیؒ کہتے ہیں کہ پھر حضرت جبرائیل علیہ السلام حضورؐ کے پاس آئے اور عرض کیا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے آپؐ کو یہ دلیل سمجھائی جیسے کہ حضرت ابراہیم علیہ السلام کو سمجھائی تھی۔ یہی مضمون لے کر قرآن کی یہ آیت نازل ہوئی:",""]]],["q",[["مَا قَطَعْتُم مِّن لِّينَةٍ أَوْ تَرَكْتُمُوهَا قَآئِمَةً عَلَىٰٓ أُصُولِهَا فَبِإِذْنِ ٱللَّهِ وَلِيُخْزِىَ ٱلْفَٰسِقِينَ  (سورۃ الحشر: ۵)","a"]]],["p",[["ترجمہ: \"جو کھجوروں کے درخت کے تنے تم نے کاٹ ڈالے یا ان کو ان کی جڑوں پر کھڑا رہنے دیا",""],["(11)","s"],[" سو (دونوں باتیں) ",""],["ٱللَّٰه","a"],[" ہی کے حکم (اور رضا) کے موافق ہیں اور تاکہ کافروں کو ذلیل کرے۔\"",""],[" (12)","s"]]]],"f":[["(11)","This verse refers to the date plantations of the Banu Nadheer tribe that the Muslims destroyed to break the morale of the Jews so that they surrender."],["(12)","Bayhaqi in his Asmaa was Sifaat (Pg.111)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں کہ جب حضورؐ حدیبیہ سے واپس آ رہے تھے تو آپؐ نے رات کے آخری حصے میں ایک جگہ پڑاؤ ڈالا اور فرمایا ہمارا پہرہ کون دے گا؟ میں نے عرض کیا میں۔ حضورؐ نے فرمایا تم تو سو جاؤ گے۔ پھر حضورؐ نے فرمایا اچھا تم ہی پہرہ دو۔ چنانچہ میں پہرہ دینے لگا۔ جب صبح صادق ہونے لگی تو حضورؐ کی بات پوری ہو گئی اور مجھے نیند آ گئی اور جب سورج کی گرمی ہماری پشت پر پڑی تب ہماری آنکھ کھلی۔ چنانچہ حضورؐ اٹھے اور ایسے موقع پر جو کیا کرتے تھے وہ کیا۔ پھر آپؐ نے صبح کی نماز پڑھائی۔ پھر فرمایا:",""]]],["c",[["اگر ",""],["ٱللَّٰه","a"],[" چاہتے تو تم یوں سوتے نہ رہ جاتے اور تمہاری نماز قضا نہ ہوتی لیکن ",""],["ٱللَّٰه","a"],[" تعالیٰ نے چاہا کہ تمہارے بعد آنے والوں میں سے کوئی سوتا رہ جائے یا نماز پڑھنا بھول جائے تو اس کے لیے عملی نمونہ سامنے آ جائے۔",""],[" (13)","s"]]]],"f":[["(13)","Bayhaqi in his Asmaa was Sifaat (Pg.109)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ابی قتادہؓ","b"],[" وضو والے برتن کی حدیث میں اپنے والد سے نقل کرتے ہیں کہ نبی کریم ",""],["ﷺ","a"],[" نے فرمایا (کہ نماز قضا ہو جانے کے موقع پر) جب ",""],["ٱللَّٰه","a"],[" تعالیٰ نے چاہا تمہاری روحوں کو قبض فرما لیا اور جب چاہا واپس کر دیا۔ پھر صحابہؓ نے سورج کی روشنی کے سفید ہونے تک (وضو، استنجا وغیرہ کی) اپنی ضروریات پوری کیں، پھر حضورؐ نے نماز پڑھائی۔",""],[" (14)","s"]]]],"f":[["(14)","Bayhaqi in his Asmaa was Sifaat (Pg.109). Bukhaari has reported a similar narration."]]},{"b":[["n",[["حضرت طارق بن شہابؒ","b"],[" کہتے ہیں کہ ایک یہودی نے آ کر حضرت عمر بن خطابؓ سے پوچھا کہ ذرا یہ تو بتائیں کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے:",""]]],["q",[["وَجَنَّةٍ عَرْضُهَا ٱلسَّمَٰوَٰتُ وَٱلْأَرْضُ  (سورۃ آل عمران: ۱۳۳)","a"]]],["p",[["ترجمہ: \"اور جنت جس کی وسعت ایسی ہے جیسے سب آسمان اور زمین۔\" (جب سب جگہ جنت ہو گئی) تو پھر جہنم کہاں ہے؟ حضرت عمرؓ نے حضرت محمدؐ کے صحابہؓ کے سامنے فرمایا کہ اسے جواب دو لیکن ان میں سے کسی کے پاس اس کا جواب نہیں تھا۔ حضرت عمرؓ نے فرمایا ذرا تم یہ بتاؤ کہ جب رات آ کر ساری زمین پر چھا جاتی ہے تو دن کہاں چلا جاتا ہے؟ اس یہودی نے کہا جہاں ",""],["ٱللَّٰه","a"],[" چاہتے ہیں وہاں چلا جاتا ہے۔ حضرت عمرؓ نے فرمایا ایسے ہی جہنم بھی وہاں ہے جہاں ",""],["ٱللَّٰه","a"],[" چاہتا ہے۔ اس پر اس یہودی نے کہا اے امیر المومنین! اس ذات کی قسم جس کے قبضے میں میری جان ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ کی نازل کردہ کتاب میں بھی اسی طرح ہے جیسے آپؐ نے فرمایا۔",""],[" (15)","s"]]]],"f":[["(15)","Abd bin Humayd, Ibn Jareer, Ibn Mundhir and Ibn Khusru, as quoted in Kanzul Ummaal (Vol.7 Pg.277)."]]},{"b":[["n",[["حضرت جعفر بن محمدؒ","b"],[" اپنے والد (حضرت محمدؒ) سے نقل کرتے ہیں کہ حضرت علیؓ کو بتایا گیا کہ یہاں ایک آدمی ہے جو مشیت اور ارادے کے بارے میں باتیں کرتا ہے تو حضرت علیؓ نے اس سے فرمایا اے ",""],["ٱللَّٰه","a"],[" کے بندے! ",""],["ٱللَّٰه","a"],[" نے جیسے چاہا تمہیں ویسے پیدا کیا یا جیسے تم نے چاہا (تمہیں ویسے پیدا کیا)؟ اس نے کہا نہیں بلکہ جیسے ",""],["ٱللَّٰه","a"],[" نے چاہا ویسے پیدا کیا۔ حضرت علیؓ نے فرمایا جب وہ چاہتا ہے تمہیں بیمار کرتا ہے یا جب تم چاہتے ہو؟ اس نے کہا نہیں بلکہ جب وہ چاہتا ہے۔ حضرت علیؓ نے فرمایا پھر جب وہ چاہتا ہے تمہیں شفا دیتا ہے یا جب تم چاہتے ہو؟ اس نے کہا نہیں بلکہ جب وہ چاہتا ہے۔ حضرت علیؓ نے فرمایا جہاں تم چاہتے ہو ",""],["ٱللَّٰه","a"],[" تمہیں وہاں داخل کرے گا یا جہاں وہ چاہتا ہے؟ اس نے کہا جہاں وہ چاہتا ہے۔ حضرت علیؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! اگر تم اس کے علاوہ کچھ اور کہتے تو میں تمہارے اس دو آنکھوں والے سر کو تلوار سے اڑا دیتا۔",""],[" (16)","s"]]]],"f":[["(16)","Ibn Abi Haatim, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.211)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" فرماتے ہیں کہ صحابہ کرامؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! جب ہم آپؐ کے پاس ہوتے ہیں تو ہماری بڑی عجیب ایمانی حالت ہوتی ہے لیکن جب ہم آپؐ سے جدا ہوتے ہیں تو وہ حالت نہیں رہتی۔ نبی کریم ",""],["ﷺ","a"],[" نے فرمایا تمہارا اپنے رب کے ساتھ کیا معاملہ ہے؟ صحابہؓ نے عرض کیا ہم تنہائی میں بھی اور لوگوں کے سامنے بھی ",""],["ٱللَّٰه","a"],[" ہی کو اپنا رب سمجھتے ہیں۔ حضورؐ نے فرمایا:",""]]],["c",[["پھر یہ نفاق نہیں ہے۔",""],[" (17)","s"]]]],"f":[["(17)","Bazzaar, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.397)."]]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ ایک دیہاتی نے آ کر نبی کریم ",""],["ﷺ","a"],[" کی خدمت میں عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! قیامت کے دن مخلوق کا حساب کون لے گا؟ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ۔ اس دیہاتی نے کہا رب کعبہ کی قسم! پھر تو ہم نجات پا گئے۔ حضورؐ نے فرمایا اے دیہاتی! کیسے؟ اس نے عرض کیا کیونکہ کریم ذات جب کسی پر قابو پا لیتی ہے تو معاف کر دیتی ہے۔",""],[" (18)","s"]]]],"f":[["(18)","Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.7 Pg.270)."]]},{"b":[["n",[["حضرت سعید بن المسیبؒ","b"],[" کہتے ہیں کہ حضرت عمر بن خطابؓ نے حضرت معاذؓ کو قبیلہ بنو کلاب میں صدقات وصول کرنے کے لیے بھیجا۔ انہوں نے (وہاں جا کر صدقات وصول کر کے) ان ہی میں تقسیم کر دیے اور (اپنے لیے) کوئی چیز نہ چھوڑی اور اپنا ٹاٹ لے کر گئے تھے اسے ہی اپنی گردن پر رکھے ہوئے واپس آئے تو ان کی بیوی نے ان سے پوچھا کہ صدقات وصول کرنے والے اپنے گھر والوں کے لیے ہدیے لایا کرتے ہیں اور آپ بھی وہ لائے ہیں، وہ کہاں ہیں؟ حضرت معاذؓ نے کہا میرے ساتھ (مجھے) دبا کر رکھنے والا ایک نگران تھا (اس لیے ہدیے نہیں لا سکا)۔ ان کی بیوی نے کہا حضورؐ اور حضرت ابوبکرؓ کے ہاں تو آپ امین تھے، حضرت عمرؓ نے آپ کے ساتھ دبا کر رکھنے والا ایک نگران بھیج دیا (وہ آپ کو امین نہیں سمجھتے)۔ ان کی بیوی نے اپنے خاندان کی عورتوں میں اس کا بڑا شور مچایا اور حضرت عمرؓ کی شکایت کی۔ جب حضرت عمرؓ کو یہ خبر پہنچی تو انہوں نے حضرت معاذؓ کو بلا کر پوچھا کیا میں نے تمہارے ساتھ ایک نگران بھیجا تھا؟ حضرت معاذؓ نے کہا مجھے اپنی بیوی سے معذرت کرنے کے لیے اور کوئی بہانہ نہ ملا۔ یہ سن کر حضرت عمرؓ ہنسے اور انہیں کوئی چیز دی اور فرمایا (یہ دے کر) اسے راضی کر لو۔ ابن جریر کہتے ہیں کہ نگران سے حضرت معاذؓ کی مراد ",""],["ٱللَّٰه","a"],[" تعالیٰ ہیں۔",""],[" (19)","s"]]]],"f":[["(19)","Abdur Razzaaq and Muhaamili in his Amaali, as quoted in Kanzul Ummaal (Vol.7 Pg.87)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو تمام آوازوں کو سن لیتا ہے۔ ایک عورت اپنا جھگڑا لے کر حضورؐ کے پاس آئی اور حضورؐ سے باتیں کرنے لگی، حالانکہ کمرے کے ایک کونے میں میں تھی لیکن مجھے اس کی بات سنائی نہیں دے رہی تھی (اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس کی آواز سن لی)۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیت نازل فرمائی:",""]]],["q",[["قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَٰدِلُكَ فِى زَوْجِهَا وَتَشْتَكِىٓ إِلَى ٱللَّهِ وَٱللَّهُ يَسْمَعُ تَحَاوُرَكُمَآ ۚ إِنَّ ٱللَّهَ سَمِيعٌۢ بَصِيرٌ  (سورۃ المجادلہ: ۱)","a"]]],["p",[["ترجمہ: \"بے شک ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس عورت کی بات سن لی جو آپ سے اپنے شوہر کے معاملہ میں جھگڑ رہی تھی اور (اپنے رنج و غم کی) ",""],["ٱللَّٰه","a"],[" تعالیٰ سے شکایت کر رہی تھی اور ",""],["ٱللَّٰه","a"],[" تعالیٰ تم دونوں کی گفتگو سن رہا تھا۔ بے شک ",""],["ٱللَّٰه","a"],[" تعالیٰ سب کچھ سننے والا، سب کچھ دیکھنے والا ہے۔\"",""],[" (20)","s"]]]],"f":[["(20)","Ahmad and Bukhaari, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.318)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ برکت والی ہے وہ ذات جو ہر چیز کو سن لیتی ہے۔ میں حضرت خولہ بنت ثعلبہؓ کی بات سن رہی تھی لیکن کبھی ان کی آواز مجھے آتی تھی اور کبھی نہیں آتی تھی۔ وہ نبی کریم ",""],["ﷺ","a"],[" سے اپنے خاوند کی شکایت یوں کر رہی تھیں کہ یا رسول ",""],["ٱللَّٰه","a"],["! میرے خاوند نے میرا سارا مال کھا لیا اور میری جوانی ختم کر دی اور میرے پیٹ سے اس کے بہت سے بچے پیدا ہوئے یہاں تک کہ جب میری عمر زیادہ ہو گئی اور میرے بچے ہونے بند ہو گئے تو اس نے مجھ سے ظہار",""],["(21)","s"],[" کر لیا (ظہار طلاق کی ایک قسم ہے)۔ اے ",""],["ٱللَّٰه","a"],["! میں تجھ سے اس کی شکایت کرتی ہوں۔ حضرت عائشہؓ فرماتی ہیں کہ حضرت خولہؓ ابھی وہاں سے اٹھی نہیں تھیں کہ حضرت جبرائیل علیہ السلام قَدْ سَمِعَ ٱللَّهُ قَوْلَ ٱلَّتِى تُجَٰدِلُكَ فِى زَوْجِهَا والی آیت لے کر آ گئے۔ حضرت خولہؓ کے خاوند حضرت اوس بن صامتؓ تھے۔",""],[" (22)","s"]]]],"f":[["(21)","Zihaar: a form of divorce during that time."],["(22)","Ibn Abi Haatim, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.318). Bayhaqi has reported a similar narration in his Asmaa was Sifaat (Pg.36)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ جب حضورؐ کی وفات ہوئی تو حضرت ابوبکرؓ نے کہا اے لوگو! اگر محمدؐ تمہارے معبود تھے جن کی تم عبادت کرتے تھے تو ان کا انتقال ہو چکا اور اگر تمہارا معبود وہ ہے جو آسمان میں ہے تو پھر تمہارے معبود کا انتقال نہیں ہوا۔ پھر حضرت ابوبکرؓ نے یہ آیت پڑھی:",""]]],["q",[["وَمَا مُحَمَّدٌ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ  (سورۃ آل عمران: ۱۴۴)","a"]]],["p",[["ترجمہ: \"محمدؐ نرے رسول ہی تو ہیں، آپؐ سے پہلے اور بھی بہت سے رسول گزر چکے ہیں۔\"",""],["(23)","s"],[" صحابہ کرامؓ کے حضرت ابوبکر صدیقؓ کی خلافت پر اتفاق کے باب میں",""],["(24)","s"],[" حضرت ابوبکرؓ کا خطبہ گزر چکا ہے، اس میں یہ ہے کہ حضرت ابوبکرؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت محمدؐ کو اتنی عمر عطا فرمائی اور ان کو اتنا عرصہ دنیا میں باقی رکھا کہ اس عرصے میں آپؐ نے ",""],["ٱللَّٰه","a"],[" کے دین کو قائم کر دیا، ",""],["ٱللَّٰه","a"],[" کے حکم کو غالب کر دیا، ",""],["ٱللَّٰه","a"],[" کا پیغام پہنچا دیا اور ",""],["ٱللَّٰه","a"],[" کے راستے میں جہاد کیا۔ پھر آپؐ کو ",""],["ٱللَّٰه","a"],[" نے اسی حالت پر وفات دی اور محمدؐ تمہیں ایک (صاف اور کھلے) راستے پر چھوڑ کر گئے ہیں۔ اب جو بھی ہلاک ہوگا وہ اسلام کی واضح دلیلوں اور کفر و شرک سے شفا دینے والے قرآن کو دیکھ کر ہی ہوگا۔ جس آدمی کے رب ",""],["ٱللَّٰه","a"],[" تعالیٰ ہیں تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمیشہ زندہ ہیں جن پر موت نہیں آ سکتی اور جو حضرت محمدؐ کی عبادت کیا کرتا تھا اور ان کو معبود کا درجہ دیا کرتا تھا تو (وہ سن لے کہ) اس کا معبود مر گیا۔ لہٰذا اے لوگو! ",""],["ٱللَّٰه","a"],[" سے ڈرو اور اپنے دین کو مضبوط پکڑ لو اور اپنے رب پر توکل کرو کیونکہ ",""],["ٱللَّٰه","a"],[" کا دین موجود ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کی بات پوری ہے اور جو ",""],["ٱللَّٰه","a"],[" (کے دین) کی مدد کرے گا ",""],["ٱللَّٰه","a"],[" اس کی مدد فرمائیں گے اور اپنے دین کو عزت عطا فرمائیں گے۔ اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کی کتاب ہمارے پاس ہے جو نور اور شفاء ہے، اس کتاب کے ذریعے ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حضرت محمدؐ کو ہدایت عطا فرمائی اور اس کتاب میں ",""],["ٱللَّٰه","a"],[" کی حلال اور حرام کردہ چیزیں مذکور ہیں۔ ",""],["ٱللَّٰه","a"],[" کی قسم! ",""],["ٱللَّٰه","a"],[" کی مخلوق میں سے جو بھی ہمارے اوپر لشکر لائے گا ہم اس کی پرواہ نہیں کریں گے۔ بیشک ",""],["ٱللَّٰه","a"],[" کی تلواریں سونتی ہوئی ہیں اور ہم نے ابھی ان کو رکھا نہیں اور جو ہماری مخالفت کرے گا ہم اس سے جہاد کریں گے جیسے کہ ہم حضورؐ کے ساتھ مل کر جہاد کیا کرتے تھے۔ یہ حدیث بیہقی نے حضرت عروہ بن زبیرؓ سے روایت کی ہے۔",""]]]],"f":[["(23)","Bukhaari in his Taareekh, Uthmaan Daarimi in his Radd alal Jahamiyyah and Isfahaani in his Hujjah, reporting from reliable sources as confirmed by Ibn Katheer and quoted in Kanzul Ummaal (Vol.4 Pg.51)."],["(24)","Under the chapter entitled \"The Standpoint of the Sahabah Concerning the Khilaafah after the demise of Rasulullaah\" and under the subheading \"The Sahabah Unanimously Accept Hadhrat Abu Bakr as Khalifah\"."]]},{"b":[["n",[["حضرت علقمہؒ","b"],[" اپنی والدہ سے نقل کرتے ہیں کہ ایک عورت حضرت عائشہؓ کے گھر آئی اور حضورؐ کے حجرے (جس میں حضورؐ دفن ہیں اس) کے پاس نماز پڑھنے لگی۔ وہ بالکل ٹھیک ٹھاک تھی۔ جب سجدے میں گئی تو اس نے سجدے سے سر نہ اٹھایا بلکہ اسی حال میں مر گئی۔ حضرت عائشہؓ نے (اس کے یوں اچانک مر جانے پر) فرمایا کہ تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جو زندہ کرتا ہے اور موت دیتا ہے اور (میرے بھائی) عبدالرحمن بن ابی بکرؓ کی اچانک موت کے مسئلے میں مجھے اس عورت کے قصے سے بڑی عبرت ملی۔ حضرت عبدالرحمنؓ دوپہر کو اپنی جگہ سوئے ہوئے تھے۔ جب لوگ انہیں جگانے لگے تو دیکھا کہ ان کا انتقال ہو چکا ہے (چنانچہ ان کو جلدی سے غسل دے کر دفن کر دیا گیا)۔ اس سے میرے دل میں یہ خیال بیٹھ گیا کہ ان کے ساتھ شرارت کی گئی ہے اور وہ زندہ تھے لیکن جلدی میں انہیں دفن کر دیا گیا ہے۔ اب میں نے اس عورت کو یوں ایک دم مرتے دیکھا اس سے مجھے بڑی عبرت ہوئی اور حضرت عبدالرحمنؓ کے بارے میں جو میرا غلط خیال تھا وہ جاتا رہا۔",""],[" (25)","s"]]]],"f":[["(25)","Haakim (Vol.3 Pg.476)."]]}]},"7":{"lead":[],"stories":[{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ (",""],["ٱللَّٰه","a"],[" تعالیٰ نے پانی کے خزانے پر فرشتہ مقرر فرما رکھا ہے، اس) فرشتے کے ہاتھوں میں ایک پیمانہ ہے اور اس پیمانے میں سے گزر کر ہی پانی کا ہر قطرہ زمین پر آتا ہے، لیکن حضرت نوحؑ (کے طوفان) والے دن ایسا نہ ہوا بلکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے براہ راست پانی کو حکم دیا اور پانی کو سنبھالنے والے فرشتوں کو حکم نہ دیا جس پر وہ فرشتے پانی کو روکتے رہ گئے لیکن پانی نہ رکا بلکہ فرشتوں پر زور کر کے چل پڑا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ کا فرمان ہے:",""]]],["q",[["إِنَّا لَمَّا طَغَا ٱلْمَآءُ  (سورۃ الحاقہ: ۱۱)","a"]]],["p",[["ترجمہ: \"جبکہ (نوح علیہ السلام کے وقت میں) پانی کو طغیانی ہوئی۔\" اس فرمان کا مطلب یہی ہے کہ پانی (",""],["ٱللَّٰه","a"],[" کا فرمانبردار تھا لیکن) فرشتوں پر سرکش ہو گیا تھا۔ اور (اسی طرح سے ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہوا کے خزانے پر فرشتہ مقرر رکھا ہے) اس کے ہاتھ میں ایک پیمانہ ہے، ہوا اس میں سے گزر کر زمین پر آتی ہے لیکن قوم عاد (کی ہلاکت) والے دن ایسا نہ ہوا بلکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہوا کو براہ راست (چلنے کا) حکم دیا اور ہوا کو سنبھالنے والے فرشتوں کو حکم نہ دیا، اس پر وہ فرشتے ہوا کو روکتے رہ گئے لیکن ہوا زور کر کے چل پڑی۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ کا فرمان ہے:",""]]],["q",[["بِرِيحٍ صَرْصَرٍ عَاتِيَةٍ  (سورۃ الحاقہ: ۶)","a"]]],["p",[["ترجمہ: \"ایک تیز و تند ہوا\" وہ ہوا فرشتوں کی نافرمان ہو گئی تھی (اور ",""],["ٱللَّٰه","a"],[" کی فرمانبردار تھی)۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Jareer, as quoted in Kanzul Ummaal (Vol.1 Pg.273)."]]},{"b":[["n",[["حضرت سلمانؓ کی بیوی حضرت بقیرہؓ","b"],[" فرماتی ہیں کہ جب حضرت سلمانؓ کی وفات کا وقت قریب آیا تو انہوں نے مجھے بلایا۔ اس وقت وہ اپنے ایک بالا خانے میں تھے جس کے چار دروازے تھے۔ اور مجھ سے کہا اے بقیرہ! ان دروازوں کو کھول دو کیونکہ آج میرے پاس کچھ ملنے والے آئیں گے اور مجھے معلوم نہیں کہ وہ کون سے دروازے سے میرے پاس آئیں گے۔ پھر اپنا مشک منگوا کر مجھ سے کہا اسے ایک چھوٹے برتن میں پانی میں گھول کر لاؤ۔ میں نے گھول کر لا دیا تو مجھ سے کہا کہ یہ مشک والا پانی میرے بستر کے چاروں طرف چھڑک دو پھر نیچے چلی جاؤ اور وہاں تھوڑی دیر ٹھہری رہو، پھر جب تم اوپر آؤ گی تو تم میرے بستر پر (کوئی چیز) دیکھو گی۔ (چنانچہ میں نے ایسے ہی کیا اور) جب میں اوپر آئی تو دیکھا کہ ان کی روح پرواز کر چکی ہے اور وہ ایسے لگ رہے ہیں کہ جیسے وہ اپنے بستر پر سو رہے ہوں۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.4 Pg.92)."]]},{"b":[["n",[["حضرت شعبیؒ","b"],[" کہتے ہیں کہ جب حضرت سلمانؓ کی وفات کا وقت قریب آیا تو انہوں نے اپنی گھر والی سے کہا میں نے جو مشک والی تھیلی تمہیں چھپا کر رکھنے کے لیے دی تھی وہ لے آؤ۔ وہ کہتی ہیں میں مشک کی وہ تھیلی لے آئی۔ انہوں نے کہا ایک پیالے میں پانی لے آؤ (میں پیالے میں پانی لے آئی) انہوں نے اس میں مشک ڈال کر اسے اپنے ہاتھ سے گھولا۔ پھر کہا اسے میرے چاروں طرف چھڑک دو کیونکہ میرے پاس ",""],["ٱللَّٰه","a"],[" کی ایسی مخلوق آنے والی ہے جو خوشبو تو سونگھ لیتی ہے لیکن کھانا نہیں کھاتی۔ پھر تم دروازہ بند کر کے نیچے اتر جاؤ۔ ان کی گھر والی کہتی ہیں کہ میں نے پانی چھڑکا اور نیچے آ گئی اور تھوڑی دیر بیٹھی تھی کہ میں نے آہٹ سنی۔ میں اوپر گئی تو دیکھا کہ ان کا انتقال ہو چکا تھا۔",""],[" (3)","s"]]],["p",[["ابن سعد ہی میں حضرت عطاء بن سائبؒ کی روایت ہے جس میں یہ قصہ مختصر طور سے ہے، اس میں یہ مضمون ہے کہ حضرت سلمانؓ نے فرمایا آج رات میرے پاس فرشتے آئیں گے جو خوشبو تو سونگھ لیتے ہیں لیکن کھانا نہیں کھاتے۔ اور اسی طرح کے اور قصے تائیدات غیبیہ کے باب میں فرشتوں کے ذریعہ مدد کے ذیل میں ان شاء ",""],["ٱللَّٰه","a"],[" تعالیٰ آئیں گے۔",""]]]],"f":[["(3)","Ibn Sa'd (Vol.4 Pg.92)."]]}]},"8":{"lead":[],"stories":[{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ نبی کریم ",""],["ﷺ","a"],[" کو انصار کے ایک بچے کے جنازے کے لیے بلایا گیا۔ میں نے کہا اس بچے کو خوشخبری ہو، یہ جنت کی چڑیوں میں سے ایک چڑیا ہے اور اس نے کوئی گناہ نہیں کیا اور نہ گناہ کا زمانہ اس نے پایا (یعنی بالغ نہیں ہوا)۔ حضورؐ نے فرمایا:",""]]],["c",[["اے عائشہ! تم جو کچھ کہہ رہی ہو حق اس کے علاوہ کچھ اور ہے۔ ",""],["ٱللَّٰه","a"],[" نے جنت کو پیدا فرمایا اور جنت کے لیے کچھ لوگ پیدا فرمائے اور ان کے جنت میں جانے کا فیصلہ ",""],["ٱللَّٰه","a"],[" نے اس وقت کیا جبکہ وہ اپنے باپ کی پشتوں میں تھے اور ",""],["ٱللَّٰه","a"],[" نے جہنم کی آگ کو پیدا کیا اور اس میں جانے کے لیے کچھ لوگوں کو پیدا کیا اور ",""],["ٱللَّٰه","a"],[" نے ان کے لیے جہنم کا فیصلہ اس وقت کیا جبکہ وہ اپنے باپ کی پشتوں میں تھے۔",""],[" (1)","s"]]]],"f":[["(1)","Muslim, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.268)."]]},{"b":[["n",[["حضرت ولید بن عبادہؒ","b"],[" کہتے ہیں کہ میں (اپنے والد) حضرت عبادہؓ کی خدمت میں گیا، وہ بیمار تھے۔ میرا اندازہ یہ تھا کہ ان کا اس بیماری میں انتقال ہو جائے گا۔ میں نے عرض کیا اے ابا جان! ذرا کوشش فرما کر مجھے وصیت فرما دیں۔ انہوں نے فرمایا مجھے بٹھاؤ۔ جب لوگوں نے انہیں بٹھا دیا تو انہوں نے فرمایا اے میرے بیٹے! ",""],["تم ایمان کا ذائقہ اس وقت چکھ سکو گے اور ","h"],["ٱللَّٰه","ah"],[" کے علم کی حقیقت تک اس وقت پہنچ سکو گے جب تم اچھی اور بری تقدیر پر ایمان لے آؤ گے۔","h"],[" میں نے عرض کیا اے ابا جان! مجھے یہ کیسے پتہ چلے گا کہ کونسی تقدیر اچھی ہے اور کونسی بری ہے؟ انہوں نے فرمایا تم یہ سمجھ لو کہ جو اچھائی یا برائی تمہیں نہیں پہنچی وہ تمہیں پہنچنے والی نہیں تھی اور جو تمہیں پہنچی ہے وہ تمہیں چھوڑنے والی نہیں تھی۔ اے میرے بیٹے! میں نے نبی کریم ",""],["ﷺ","a"],[" کو فرماتے ہوئے سنا ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے سب سے پہلے قلم پیدا فرمایا، پھر اس سے فرمایا لکھ؛ چنانچہ اس نے اسی وقت وہ سب کچھ لکھ دیا جو قیامت تک ہونے والا ہے۔ اے میرے بیٹے! اگر تم اس حال پر مرے کہ تمہارے دل میں یہ یقین نہ ہو تو جہنم کی آگ میں داخل ہو جاؤ گے۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad and Tirmidhi, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.278)."]]},{"b":[["n",[["حضرت ابونضرہؒ","b"],[" کہتے ہیں کہ نبی کریم ",""],["ﷺ","a"],[" کے صحابہؓ میں سے ایک آدمی جن کو ابو عبد",""],["ٱللَّٰه","a"],[" کہا جاتا تھا وہ بیمار تھے، ان کے ساتھی ان کی عیادت کرنے آئے تو دیکھا کہ وہ رو رہے ہیں۔ ساتھیوں نے ان سے پوچھا آپ کیوں رو رہے ہیں؟ کیا آپ سے نبی کریم ",""],["ﷺ","a"],[" نے یہ نہیں فرمایا تھا کہ اپنی مونچھوں کو کترواؤ اور پھر اسی پر جمے رہو یہاں تک کہ تم مجھ سے (قیامت کے دن) آ ملو؟ اس میں آپ کے ایمان پر خاتمہ کی اور قیامت کے دن حضورؐ سے ملاقات کی بشارت ہے۔ انہوں نے کہا ہاں حضورؐ نے یہ فرمایا تھا لیکن میں نے حضورؐ کو یہ بھی فرماتے ہوئے سنا ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے (انسانوں کی) ایک مٹھی دائیں ہاتھ میں لی اور دوسری مٹھی دوسرے ہاتھ میں لی اور فرمایا کہ اس (داہنی) مٹھی والے اس (جنت) کے لیے ہیں اور اس (دوسری مٹھی) والے اس (جہنم) کے لیے ہیں اور مجھے کوئی پرواہ نہیں (کہ کون کس مٹھی میں ہے اور وہ کہاں جائے گا)۔ تو مجھے معلوم نہیں کہ میں کونسی مٹھی میں ہوں؟ (",""],["ٱللَّٰه","a"],[" کی ذات تو بہت بے نیاز ہے، اس پر کسی کا زور نہیں چلتا)۔",""],[" (3)","s"]]]],"f":[["(3)","Ahmad, reporting from reliable sources as confirmed by Haythami (Vol.7 Pg.186)."]]},{"b":[["n",[["حضرت معاذ بن جبلؓ","b"],[" کی وفات کا وقت جب قریب آیا تو وہ رونے لگے تو ان سے کسی نے پوچھا آپ کیوں رو رہے ہیں؟ حضرت معاذؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! نہ تو میں موت سے گھبرا کر رو رہا ہوں اور نہ ہی دنیا کو پیچھے چھوڑ کر جانے کے غم میں رو رہا ہوں بلکہ اس وجہ سے رو رہا ہوں کہ میں نے حضورؐ کو فرماتے ہوئے سنا ہے کہ (انسانوں کی) دو مٹھیاں ہیں، ایک مٹھی جہنم کی آگ میں جائے گی اور دوسری جنت میں۔ اور مجھے معلوم نہیں ہے کہ میں ان دونوں مٹھیوں میں سے کس میں ہوں؟",""],[" (4)","s"]]]],"f":[["(4)","Tabraani. Haythami (Vol.7 Pg.187) has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عباسؓ","b"],[" سے کسی آدمی نے کہا کہ ایک آدمی ہمارے پاس آیا ہے جو تقدیر کو جھٹلاتا ہے۔ حضرت ابن عباسؓ اس وقت نابینا ہو چکے تھے، انہوں نے فرمایا مجھے اس کے پاس لے جاؤ۔ لوگوں نے کہا اے ابن عباس! آپ اس کے ساتھ کیا کریں گے؟ انہوں نے فرمایا اس ذات کی قسم جس کے قبضے میں میری جان ہے! اگر وہ میرے قابو آ گیا تو میں اس کی ناک دانتوں سے ایسے کاٹوں گا کہ وہ کٹ کر الگ ہو جائے اور اگر اس کی گردن میرے قابو میں آ گئی تو میں اسے کچل دوں گا۔ کیونکہ میں نے حضورؐ کو یہ فرماتے ہوئے سنا ہے کہ گویا کہ میں بنو فہر کی مشرک عورتوں کو خزرج کا طواف کرتے ہوئے اور ان کے سرین ہلتے ہوئے دیکھ رہا ہوں اور یہ (تقدیر کو جھٹلانا) اس امت کا پہلا شرک ہے۔ اس ذات کی قسم جس کے قبضے میں میری جان ہے! پہلے تو یہ کہیں گے کہ شر ",""],["ٱللَّٰه","a"],[" کے مقدر کرنے سے نہیں ہے، پھر ان کا یہ برا اور غلط خیال انہیں اس پر لے آئے گا کہ خیر بھی ",""],["ٱللَّٰه","a"],[" کے مقدر کرنے سے نہیں ہے۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad."]]},{"b":[["n",[["حضرت عطاء بن ابی رباحؒ","b"],[" کہتے ہیں کہ میں حضرت ابن عباسؓ کی خدمت میں آیا، وہ زمزم (کے کنویں) سے پانی نکال رہے تھے جس سے ان کے کپڑوں کا نچلا حصہ گیلا ہو چکا تھا۔ میں نے ان سے کہا کچھ لوگوں نے تقدیر پر اعتراض کیا ہے۔ انہوں نے فرمایا اچھا کیا لوگوں نے ایسا کر لیا ہے؟ میں نے کہا جی ہاں۔ انہوں نے فرمایا تقدیر پر اعتراض کرنے والوں کے بارے میں ہی یہ آیات نازل ہوئی ہیں:",""]]],["q",[["ذُوقُوا۟ مَسَّ سَقَرَ ۝ إِنَّا كُلَّ شَىْءٍ خَلَقْنَٰهُ بِقَدَرٍ  (سورۃ القمر: ۴۸-۴۹)","a"]]],["p",[["ترجمہ: \"(ان سے) کہا جائے گا کہ دوزخ (کی آگ) کے لگنے کا مزہ چکھو۔ ہم نے ہر چیز کو اندازے سے پیدا کیا۔\" یہی لوگ اس امت میں سب سے برے ہیں۔ نہ تو ان کے بیماروں کی عیادت کرو اور نہ ان کے مردوں کی نماز جنازہ پڑھو۔ اگر مجھے ان میں سے کوئی نظر آ گیا تو میں اپنی ان دو انگلیوں سے اس کی دونوں آنکھیں پھوڑ دوں گا۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abi Haatim, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.267)."]]},{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ میرا دل یہ چاہتا ہے کہ تقدیر کے انکار کرنے والوں میں سے کوئی میرے پاس آ جائے تو میں اس کے سر کو کچل دوں۔ لوگوں نے پوچھا کیوں؟ انہوں نے فرمایا اس وجہ سے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے لوح محفوظ کو ایک سفید موتی سے پیدا کیا ہے۔ اس لوح محفوظ کے دونوں طرف کے پٹے سرخ یاقوت کے ہیں۔ اس کا قلم نور ہے، اس کی کتاب نور ہے۔ اس کی چوڑائی آسمان اور زمین کے درمیانی فاصلے کے برابر ہے۔ روزانہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اسے تین سو ساٹھ مرتبہ دیکھتے ہیں اور ہر دفعہ دیکھنے پر (نہ معلوم کتنی مخلوق کو) پیدا کرتے ہیں، زندہ کرتے ہیں اور موت دیتے ہیں، عزت دیتے ہیں اور ذلت دیتے ہیں اور جو چاہتے ہیں کرتے ہیں۔",""],[" (7)","s"]]]],"f":[["(7)","Abu Nu'aym in his Hilya (Vol.1 Pg.267)."]]},{"b":[["n",[["حضرت نافعؒ","b"],[" کہتے ہیں کہ حضرت ابن عمرؓ کا ایک دوست شام کا رہنے والا تھا جس سے ان کی خط و کتابت رہتی تھی۔ ایک دفعہ حضرت ابن عمرؓ نے اسے لکھا کہ مجھے یہ خبر پہنچی ہے کہ تم تقدیر کے بارے میں کچھ اعتراض کرنے لگ گئے ہو، خبردار! آئندہ مجھے کبھی خط نہ لکھنا کیونکہ میں نے حضورؐ کو یہ فرماتے ہوئے سنا ہے کہ ",""],["میری امت میں ایسے لوگ ہوں گے جو تقدیر کو جھٹلائیں گے۔","h"],[" (8)","s"]]]],"f":[["(8)","Ahmad and Abu Dawood, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.268)."]]},{"b":[["n",[["حضرت نزال بن سبرہؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت علیؓ سے عرض کیا کہ اے امیر المومنین! یہاں کچھ لوگ ایسے ہیں جو یہ کہتے ہیں کہ جو کام آئندہ ہونے والا ہے اس کا پتہ ",""],["ٱللَّٰه","a"],[" کو اس وقت چلتا ہے جب وہ کام ہو جاتا ہے۔ حضرت علیؓ نے فرمایا ان کی مائیں ان کو گم کریں، یعنی یہ مر جائیں، یہ لوگ یہ بات کہاں سے کہہ رہے ہیں؟ تو لوگوں نے بتایا کہ وہ قرآن کی اس آیت سے یہ بات نکالتے ہیں:",""]]],["q",[["وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَٰهِدِينَ مِنكُمْ وَٱلصَّٰبِرِينَ وَنَبْلُوَا۟ أَخْبَارَكُمْ  (سورۃ محمد: ۳۱)","a"]]],["p",[["ترجمہ: \"اور ہم ضرور تم سب کے اعمال کی آزمائش کریں گے تاکہ ہم ان لوگوں کو معلوم کر لیں جو تم میں جہاد کرنے والے ہیں اور ثابت قدم رہنے والے ہیں اور تاکہ تمہاری حالتوں کی جانچ کر لیں۔\" (یوں کہتے ہیں کہ ",""],["ٱللَّٰه","a"],[" کو معلوم نہیں ہے، آزمانے سے ",""],["ٱللَّٰه","a"],[" کو معلوم ہوگا، نعوذ ب",""],["ٱللَّٰه","a"],[" من ذلک)۔ حضرت علیؓ نے فرمایا جو علم حاصل نہ کرے وہ ہلاک ہو جائے گا۔ پھر حضرت علیؓ منبر پر تشریف فرما ہوئے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کی حمد و ثناء کے بعد فرمایا اے لوگو! علم حاصل کرو اور اس پر عمل کرو اور وہ علم دوسروں کو سکھاؤ اور جسے ",""],["ٱللَّٰه","a"],[" کی کتاب میں سے کوئی بات سمجھ میں نہ آئے وہ مجھ سے پوچھ لے۔ مجھے یہ پتہ چلا ہے کہ بعض لوگ یہ کہتے ہیں کہ جو کام آئندہ ہونے والا ہے اس کا پتہ ",""],["ٱللَّٰه","a"],[" کو اس وقت چلتا ہے جب وہ ہو جاتا ہے۔ کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے:",""]]],["q",[["وَلَنَبْلُوَنَّكُمْ حَتَّىٰ نَعْلَمَ ٱلْمُجَٰهِدِينَ","a"]]],["p",[["ترجمہ: \"اور ہم ضرور تم سب کے اعمال کی آزمائش کریں گے تاکہ ہم ان لوگوں کو معلوم کر لیں جو تم میں جہاد کرنے والے ہیں۔\" حالانکہ ",""],["ٱللَّٰه","a"],[" کے فرمان \"ہم معلوم کر لیں\" کا مطلب یہ ہے کہ ہم دیکھ لیں کہ جن لوگوں پر جہاد کرنا اور ثابت قدم رہنا فرض کیا گیا ہے کیا انہوں نے جہاد کیا ہے؟ اور میں نے ان کے بارے میں جن مصائب اور حوادث کے آنے کا فیصلہ کیا تھا کیا انہوں نے ان پر صبر کیا ہے؟",""],["(9)","s"],[" توکل کے باب میں",""],["(10)","s"],[" حضرت علیؓ کا یہ فرمان گزر چکا ہے کہ زمین پر اس وقت تک کوئی چیز نہیں ہو سکتی جب تک آسمان میں اس کے ہونے کا فیصلہ نہ ہو جائے۔ اور ہر انسان پر دو فرشتے مقرر ہیں جو ہر بلا کو اس سے دور کرتے رہتے ہیں اور اس کی حفاظت کرتے رہتے ہیں، یہاں تک کہ اس کی تقدیر کا لکھا ہوا فیصلہ آ جائے۔ اور جب تقدیر کا کوئی فیصلہ آ جاتا ہے تو یہ دونوں فرشتے اس کے اور تقدیر کے درمیان سے ہٹ جاتے ہیں۔ اور ",""],["ٱللَّٰه","a"],[" کی طرف سے میری حفاظت کا بڑا مضبوط انتظام ہے۔ جب میری موت کا وقت آ جائے گا تو وہ انتظام مجھ سے ہٹ جائے گا۔ اور آدمی کو ایمان کی حلاوت اس وقت تک نہیں مل سکتی جب تک اس کو یہ یقین نہ ہو جائے کہ جو کچھ اچھا یا برا اسے پہنچا ہے وہ اس سے ٹلنے والا نہیں تھا اور جو اس سے ٹل گیا ہے وہ اسے پہنچنے والا نہیں تھا۔ ابوداؤد نے اسے تقدیر میں روایت کیا ہے۔",""]]]],"f":[["(9)","Ibn Abdul Birr in his Ilm, as quoted in Kanzul Ummaal (Vol.1 Pg.265)."],["(10)","Under the heading \"The Tawakkul of the Sahabah\" and the subheading \"The Tawakkul of Ameerul Mu'mineen Hadhrat Ali\"."]]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" فرماتے ہیں کہ حضرت عمر بن خطابؓ منبر پر بیان فرماتے ہوئے یہ اشعار بہت پڑھا کرتے تھے:",""]]],["q",[["خَفِّضْ عَلَيْكَ فَإِنَّ الْأُمُورَ  ·  بِكَفِّ ٱللَّهِ مَقَادِيرُهَا","a"]]],["p",[["اپنے ساتھ آسانی کا معاملہ کرو (اور گھبراؤ مت) کیونکہ تمام کاموں کی تقدیریں ",""],["ٱللَّٰه","a"],[" تعالیٰ کی ہتھیلی میں ہیں۔",""]]],["q",[["فَلَيْسَ بِآتِيكَ مَنْهِيُّهَا  ·  وَلَا قَاصِرٌ عَنْكَ مَأْمُورُهَا","a"]]],["p",[["جس کام کو ",""],["ٱللَّٰه","a"],[" نے منع کر دیا ہے وہ تمہارے پاس آ نہیں سکتا اور جس کے ہونے کا حکم دے دیا ہے وہ تم سے ٹل نہیں سکتا۔",""],[" (11)","s"]]]],"f":[["(11)","Bayhaqi in his Asmaa was Sifaat (Pg.243)."]]}]},"9":{"lead":[],"stories":[{"b":[["n",[["حضرت ابن عباسؓ","b"],[" فرماتے ہیں کہ جب یہ آیت نازل ہوئی:",""]]],["q",[["فَإِذَا نُقِرَ فِى ٱلنَّاقُورِ  (سورۃ المدثر: ۸)","a"]]],["p",[["ترجمہ: \"پھر جس وقت صور پھونکا جائے گا\"، تو حضورؐ نے فرمایا:",""]]],["c",[["میں زندگی کے آرام و راحت سے کیسے گزاروں جبکہ صور (پھونکنے) والا (فرشتہ) صور اپنے منہ میں رکھ چکا ہے اور وہ اپنی پیشانی جھکائے انتظار کر رہا ہے کہ کب اسے (",""],["ٱللَّٰه","a"],[" کی طرف سے) حکم ملے اور وہ صور پھونک دے۔",""]]],["p",[["حضورؐ کے صحابہؓ نے عرض کیا پھر ہم کیا دعا کیا کریں؟ آپؐ نے فرمایا یہ دعا پڑھا کرو:",""]]],["q",[["حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ عَلَى ٱللَّهِ تَوَكَّلْنَا","a"],[" (1)","s"]]],["p",[["ایک روایت میں یہ ہے کہ جب حضورؐ کے صحابہؓ نے یہ سنا تو ان پر یہ بات بہت گراں ہوئی۔ انہوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہم کیا کریں؟ آپؐ نے فرمایا آپ لوگ یہ کہو:",""]]],["q",[["حَسْبُنَا ٱللَّهُ وَنِعْمَ ٱلْوَكِيلُ","a"],[" (2)","s"]]]],"f":[["(1)","Ibn Abi Shaybah, Tabraani and Ibn Mardway, as quoted in Kanzul Ummaal (Vol.7 Pg.270)."],["(2)","Baawardi, as quoted in Kanzul Ummaal (Vol.7 Pg.270)."]]},{"b":[["n",[["عورتوں کی معاشرت کے باب میں",""],["(3)","s"],[" یہ روایت گزر چکی ہے کہ ",""],["حضرت حفصہؓ","b"],[" نے حضرت سودہؓ سے کہا کانا (دجال) نکل آیا ہے۔ انہوں نے کہا اچھا! یہ سن کر وہ بہت زیادہ گھبرا گئیں اور کانپنے لگیں۔ پھر انہوں نے کہا میں کہاں چھپوں؟ حضرت حفصہؓ نے کہا اس خیمے میں چھپ جاؤ۔ وہاں کھجور کے پتوں کا بنا ہوا خیمہ تھا جس میں لوگ چھپتے تھے۔ حضرت سودہؓ جا کر اس میں چھپ گئیں۔ اس میں گرد و غبار اور مکڑی کے جالے بہت تھے۔ پھر آگے حدیث ذکر کی ہے۔ اس میں یہ ہے کہ پھر حضورؐ وہاں تشریف لے گئے تو دیکھا کہ حضرت سودہؓ کانپ رہی ہیں۔ حضورؐ نے ان سے پوچھا اے سودہ! تمہیں کیا ہوا؟ انہوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کانا دجال نکل آیا ہے۔ حضورؐ نے فرمایا وہ ابھی نکلا تو نہیں لیکن نکلے گا ضرور۔ وہ ابھی نکلا تو نہیں لیکن نکلے گا ضرور۔ پھر حضورؐ نے انہیں باہر نکالا اور ان کے کپڑوں اور جسم کے گرد و غبار اور مکڑی کے جالے صاف کیے۔ اس روایت کو حضورؐ کی آزاد کردہ باندی حضرت رزینہؓ سے ابویعلیٰ اور طبرانی نے نقل کیا ہے۔",""]]]],"f":[["(3)","Under the heading \"Relationships between Men, Women and Children\" and the subheading \"The Relationship Between Hadhrat Aa'isha and Hadhrat Hafsah with Hadhrat Sauda\"."]]},{"b":[["n",[["حضرت سعید بن مسیبؒ","b"],[" کہتے ہیں کہ حضرت ابوبکرؓ نے فرمایا کیا عراق میں خراسان نام کی کوئی جگہ ہے؟ لوگوں نے عرض کیا جی ہاں! آپؓ نے فرمایا دجال وہاں سے نکلے گا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Shaybah."]]},{"b":[["n",[["حضرت ابوبکر صدیقؓ","b"],[" کی ایک روایت نعیم بن حماد نے فتن میں یہ ذکر کی ہے کہ حضرت ابوبکر صدیقؓ نے فرمایا کہ مرو (شہر) کے یہودی فرقے میں سے دجال نکلے گا۔",""],[" (5)","s"]]]],"f":[["(5)","Nu'aym bin Hammaad, as quoted in Kanzul Ummaal (Vol.7 Pg.263)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن ابی ملیکہؒ","b"],[" فرماتے ہیں کہ ایک دن میں صبح کو حضرت ابن عباسؓ کے پاس گیا، انہوں نے کہا آج رات مجھے صبح تک نیند نہیں آئی۔ میں نے پوچھا کیوں؟ انہوں نے کہا لوگ کہہ رہے تھے کہ دُمدار ستارہ نکل آیا ہے تو مجھے اس کا ڈر ہوا کہ کہیں (وہ) دھواں نہ ہو (جسے قیامت کی نشانیوں میں سے بتایا گیا ہے)، اس وجہ سے مجھے صبح تک نیند نہیں آئی۔",""],["(6)","s"],[" حاکم کی روایت میں یہ ہے کہ مجھے ڈر ہوا کہ کہیں دجال نہ نکل آیا ہو۔",""],[" (7)","s"]]]],"f":[["(6)","Ibn Jareer, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.139)."],["(7)","Haakim (Vol.4 Pg.459), reporting from reliable sources as confirmed by Dhahabi."]]}]},"10":{"lead":[],"stories":[{"b":[["n",[["حضرت عبادہ بن نسیؒ","b"],[" کہتے ہیں کہ جب حضرت ابوبکرؓ کی وفات کا وقت قریب آیا تو انہوں نے حضرت عائشہؓ سے فرمایا ",""],["میرے ان کپڑوں کو دھو کر مجھے ان ہی میں کفن دے دینا","h"],[" کیونکہ (مرنے کے بعد) تمہارے باپ کی دو حالتوں میں سے ایک حالت ضرور ہوگی: یا تو اسے ان سے بھی اچھے کپڑے (جنت کے) پہنائے جائیں گے یا یہ کفن کے کپڑے بھی بری طرح چھین لیے جائیں گے۔",""],[" (1)","s"]]]],"f":[["(1)","Ahmad in his Zuhd, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.363)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ جب حضرت ابوبکرؓ کی وفات کا وقت قریب آیا تو میں نے (اظہار غم کے لیے) یہ شعر پڑھا:",""]]],["q",[["لَعَمْرُكَ مَا يُغْنِي الثَّرَاءُ عَنِ الْفَتَى  ·  إِذَا حَشْرَجَتْ يَوْمًا وَضَاقَ بِهَا الصَّدْرُ","a"]]],["p",[["آپ کی عمر کی قسم! جس دن موت کے وقت سانس اکھڑنے لگے اور اس کی وجہ سے سینہ گھٹنے لگے تو اس وقت جوان آدمی کو مال کی کثرت نفع نہیں دیتی۔ حضرت ابوبکرؓ نے فرمایا اے میری بیٹی! ایسے نہ کہو بلکہ یہ پڑھو:",""]]],["q",[["وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ۖ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ  (سورۃ ق: ۱۹)","a"]]],["p",[["ترجمہ: \"اور موت کی سختی (قریب) آ پہنچی۔ یہ (موت) وہ چیز ہے جس سے تو بدکتا تھا۔\" پھر حضرت ابوبکرؓ نے فرمایا میرے یہ دو کپڑے دیکھ لو، انہیں دھو کر مجھے ان ہی میں کفن دے دینا کیونکہ نئے کپڑے کی مردے سے زیادہ زندہ کو ضرورت ہے۔ ان کپڑوں کو تو مردے کے جسم کی پیپ اور خون ہی لگے گا (یا یہ کپڑے تو تھوڑی دیر کے لیے ہیں، چند دن میں گل سڑ کر ختم ہو جائیں گے)۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad, Ibn Sa'd and Daghooli."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ جب حضرت ابوبکرؓ کی بیماری اور بڑھ گئی تو میں ان کے پاس رونے لگی۔ پھر وہ بیہوش ہو گئے تو میں نے یہ شعر پڑھا:",""]]],["q",[["مَن لَا يَزَالُ دَمْعُهُ مُقَنَّعًا  ·  فَإِنَّهُ لَا بُدَّ مَرَّةً مَدْفُوقُ","a"]]],["p",[["جس کے آنسو ہمیشہ رکے رہیں، اس کے آنسو ایک دن ضرور بہیں گے۔ پھر ان کو ہوش آیا تو فرمایا ایسے نہیں اے میری بیٹی! صحیح بات وہ ہے جیسے اس آیت میں بتایا گیا ہے:",""]]],["q",[["وَجَآءَتْ سَكْرَةُ ٱلْمَوْتِ بِٱلْحَقِّ ۖ ذَٰلِكَ مَا كُنتَ مِنْهُ تَحِيدُ","a"]]],["p",[["پھر پوچھا حضورؐ کا کس دن انتقال ہوا تھا؟ میں نے عرض کیا پیر کے دن۔ فرمایا آج کونسا دن ہے؟ میں نے عرض کیا پیر کا دن۔ فرمایا مجھے ",""],["ٱللَّٰه","a"],[" کی ذات سے امید ہے کہ اب سے لے کر رات تک کسی وقت میں اس دنیا سے چلا جاؤں گا۔ چنانچہ منگل کی رات کو ان کا انتقال ہوا۔ اور یہ بھی فرمایا کہ حضورؐ کو کتنے کپڑوں میں دفن کیا گیا تھا؟ میں نے عرض کیا ہم نے حضورؐ کو یمن کی سحول بستی کے بنے ہوئے تین سفید اور نئے کپڑوں میں کفن دیا تھا، ان کپڑوں میں نہ کرتا تھا اور نہ عمامہ۔ انہوں نے فرمایا میرے اس کپڑے پر زعفران کا دھبہ لگا ہوا ہے اسے دھو لو اور اس کے ساتھ دو نئے کپڑے اور شامل کر لینا۔ میں نے عرض کیا یہ کپڑا تو پرانا ہے۔ فرمایا زندہ کو مردے سے زیادہ نئے کپڑے کی ضرورت ہے۔",""],["(3)","s"],[" کفن کے کپڑے تو جسم سے نکلنے والے خون اور پیپ سے خراب ہو جائیں گے۔",""],[" (4)","s"]]]],"f":[["(3)","Abu Ya'la, Abu Nu'aym, Daghooli and Bayhaqi, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.362)."],["(4)","Ibn Sa'd (Vol.3 Pg.197)."]]},{"b":[["n",[["حضرت یحییٰ بن ابی راشد نصریؒ","b"],[" کہتے ہیں کہ جب حضرت عمر بن خطابؓ کی وفات کا وقت قریب آیا تو انہوں نے اپنے بیٹے سے فرمایا اے میرے بیٹے! جب مجھے موت آنے لگے تو میرے جسم کو (دائیں پہلو کی طرف) موڑ دینا اور اپنے دونوں گھٹنے میری کمر کے ساتھ لگا دینا اور اپنا دایاں ہاتھ میری پیشانی پر اور بایاں ہاتھ میری ٹھوڑی پر رکھ دینا اور جب میری روح نکل جائے تو میری آنکھیں بند کر دینا اور مجھے درمیانی قسم کا کفن پہنانا۔ اگر مجھے ",""],["ٱللَّٰه","a"],[" کے ہاں سے خیر ملی ہوئی تو پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ مجھے اس سے بہتر کفن دیں گے اور اگر میرے ساتھ کچھ اور ہوا تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کفن کو مجھ سے جلدی چھین لیں گے۔ اور میری قبر درمیانی قسم کی بنانا کیونکہ اگر مجھے ",""],["ٱللَّٰه","a"],[" کے ہاں خیر ملی تو پھر قبر کو تاحد نگاہ کشادہ کر دیا جائے گا اور اگر معاملہ اس کے خلاف ہوا تو پھر قبر میرے لیے اتنی تنگ کر دی جائے گی کہ میری پسلیاں ایک دوسرے میں گھس جائیں گی۔ میرے جنازے کے ساتھ کوئی عورت نہ جائے اور جو خوبی مجھ میں نہیں ہے اسے مت بیان کرنا کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ مجھے تم لوگوں سے زیادہ جانتے ہیں۔ اور جب تم میرے جنازے کو لے کر چلو تو تیز چلنا کیونکہ اگر مجھے ",""],["ٱللَّٰه","a"],[" کے ہاں سے خیر ملنے والی ہے تو تم مجھے اس خیر کی طرف لے جا رہے ہو (اس لیے جلدی کرو) اور اگر معاملہ اس کے خلاف ہے تو تم ایک شر کو اٹھا کر لے جا رہے ہو، اسے اپنی گردن سے جلدی اتار دو۔",""],[" (5)","s"]]],["p",[["امر خلافت کی صلاحیت رکھنے والے حضرات کے مشورے پر امر خلافت کو موقوف کر دینے کے باب میں حضرت عمرؓ کا یہ فرمان گزر چکا ہے کہ جب حضرت عمرؓ نے سمجھ لیا کہ اب تو موت آنے والی ہے تو فرمایا اب اگر میرے پاس ساری دنیا ہو تو میں اسے موت کے بعد آنے والے ہولناک منظر کی گھبراہٹ کے بدلے میں دینے کو تیار ہوں۔",""],[" (6)","s"]]],["p",[["انہوں نے اپنے بیٹے سے کہا اے عبد",""],["ٱللَّٰه","a"],[" بن عمر! میرے رخسار کو زمین پر رکھ دو (حضرت ابن عمرؓ کہتے ہیں) میں نے ان کا سر اپنی ران سے اٹھا کر اپنی پنڈلی پر رکھ دیا تو فرمایا نہیں، میرے رخسار کو زمین پر رکھ دو؛ چنانچہ انہوں نے اپنی داڑھی اور رخسار کو اٹھا کر زمین پر رکھ دیا اور فرمایا عمر! اگر ",""],["ٱللَّٰه","a"],[" نے تیری مغفرت نہ کی تو پھر اے عمر! تیری بھی اور تیری ماں کی بھی ہلاکت ہے۔ اس کے بعد ان کی روح پرواز کر گئی، رحمہ ",""],["ٱللَّٰه","a"],["۔ اس واقعہ کو طبرانی نے حضرت ابن عمرؓ سے ایک لمبی حدیث میں نقل کیا ہے۔",""],[" (7)","s"]]]],"f":[["(5)","Ibn Sa'd (Vol.3 Pg.58). Ibn Abi Dunya has reported a similar narration in his Quboor, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.427)."],["(6)","Under the subheading \"The Narration of Hadhrat Abdullaah bin Abbaas Concerning the Fear Hadhrat Umar had for Allaah\"."],["(7)","Under the subheading \"The Narration of Hadhrat Abdullaah bin Umar and Hadhrat Miswar Concerning the Fear Hadhrat Umar had for Allaah\"."]]},{"b":[["n",[["رونے کے باب میں یہ حدیث گزر چکی ہے کہ ",""],["حضرت ہانیؒ","b"],[" کہتے ہیں کہ جب حضرت عثمانؓ کسی قبر پر کھڑے ہوتے تو اتنا روتے کہ داڑھی تر ہو جاتی۔ ان سے کسی نے پوچھا کہ آپ جنت اور جہنم کا تذکرہ کرتے ہیں تو نہیں روتے لیکن قبر کو یاد کر کے روتے ہیں؟ آگے پوری حدیث ذکر کی ہے۔ ترمذی نے اس حدیث کو نقل کیا ہے اور اسے حدیث حسن قرار دیا ہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت خالد بن ربیعؒ","b"],[" کہتے ہیں کہ جب حضرت حذیفہؓ کی بیماری بڑھی تو یہ خبر ان کی جماعت اور انصار تک پہنچی۔ یہ لوگ آدھی رات کو یا صبح کے قریب حضرت حذیفہؓ کے پاس آئے (میں بھی ان کے ساتھ تھا)۔ حضرت حذیفہؓ نے پوچھا اب کیا وقت ہے؟ ہم نے عرض کیا آدھی رات ہے یا صبح کے قریب۔ انہوں نے فرمایا میں جہنم کی صبح سے ",""],["ٱللَّٰه","a"],[" کی پناہ چاہتا ہوں۔ کیا تم لوگ میرے کفن کے لیے کچھ لائے ہو؟ ہم نے کہا جی ہاں! انہوں نے فرمایا کفن مہنگا نہ بنانا کیونکہ اگر ",""],["ٱللَّٰه","a"],[" کے ہاں میرے لیے خیر ہوئی تو مجھے اس کفن سے بہتر کپڑا مل جائے گا اور اگر دوسری صورت ہوئی تو یہ کفن مجھ سے جلدی چھین لیا جائے گا۔",""],[" (8)","s"]]]],"f":[["(8)","Bukhaari in his Adab (Pg.72). Abu Nu'aym has also reported the narration in his Hilya (Vol.1 Pg.282) from Hadhrat Abu Waa'il. In his Mustadrak (Vol.3 Pg.380), Haakim has also reported a similar narration in brief from Hadhrat Abu Mas'ood Ansaari."]]},{"b":[["n",[["حضرت ابو وائلؒ","b"],[" کہتے ہیں کہ جب حضرت حذیفہؓ کی بیماری بڑھ گئی تو بنو عبس کے کچھ لوگ ان کے پاس آئے۔ حضرت خالد بن ربیع عبسیؒ نے مجھے بتایا کہ حضرت حذیفہؓ مدائن میں تھے اور ہم آدھی رات کو ان کے پاس گئے۔ آگے پچھلی حدیث جیسا مضمون ذکر کیا ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Abu Nu'aym in his Hilya (Vol.1 Pg.282)."]]},{"b":[["n",[["حضرت صلہ بن زفرؒ","b"],[" کہتے ہیں کہ حضرت حذیفہؓ نے مجھے اور حضرت ابو مسعودؓ کو بھیجا، ہم نے ان کے کفن کے لیے دو دھاری دار منقش چادریں تین سو درہم میں خرید لیں۔ انہوں نے ہم سے کہا تم نے میرے لیے جو کفن خریدا ہے وہ ذرا مجھے دکھاؤ۔ ہم نے انہیں وہ کفن دکھایا۔ انہوں نے کہا یہ کفن تو میرے لیے (مناسب) نہیں ہے۔ میرے لیے تو دو سفید عام چادریں کافی تھیں۔ ان کے ساتھ قمیص کی بھی ضرورت نہیں کیونکہ قبر میں تھوڑی ہی دیر گزرنے کی ہے کہ یا تو ان دو چادروں سے بہتر کفن مجھے مل جائے گا یا پھر ان سے بھی زیادہ برے کپڑے پہنا دیے جائیں گے۔ چنانچہ ہم نے ان کے لیے دو سفید چادریں خرید لیں۔",""],["(10)","s"],[" ابونعیم کی دوسری روایت میں یہ مضمون ہے کہ حضرت حذیفہؓ نے کفن دیکھ کر فرمایا تم اس کفن کا کیا کرو گے؟ اگر تمہارا یہ ساتھی نیک ہوا تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے بدلے میں عمدہ کفن دے دیں گے اور اگر یہ نیک نہ ہوا تو قبر کے دونوں کنارے اسے قیامت تک (گیند کی طرح) پھینکتے رہیں گے۔ حاکم کی روایت میں یہ ہے کہ اگر تمہارا یہ ساتھی نیک نہ ہوا تو پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ یہ کفن قیامت کے دن اس کے چہرے پر ماریں گے۔",""],[" (11)","s"]]]],"f":[["(10)","Abu Nu'aym in his Hilya (Vol.1 Pg.282)."],["(11)","Haakim (Vol.3 Pg.380)."]]},{"b":[["n",[["حضرت ضحاک بن عبدالرحمنؒ","b"],[" کہتے ہیں کہ جب حضرت ابو موسیٰ اشعریؓ کی وفات کا وقت قریب آیا تو انہوں نے اپنے جوانوں کو بلا کر ان سے کہا جاؤ اور میرے لیے خوب گہری اور چوڑی قبر کھودو۔ وہ گئے اور واپس آ کر انہوں نے کہا کہ ہم خوب چوڑی اور گہری قبر کھود آئے ہیں۔ پھر انہوں نے فرمایا ",""],["ٱللَّٰه","a"],[" کی قسم! قبر میں دو قسم کے حالات میں سے ایک طرح کے حالات ضرور پیش آئیں گے: یا تو میری قبر کو اتنا کشادہ کر دیا جائے گا کہ اس کا ہر کونہ چالیس ہاتھ لمبا ہو جائے گا۔ پھر میرے لیے جنت کی طرف ایک دروازہ کھول دیا جائے گا اور میں اس میں سے اپنی بیویوں، محلات اور جو کچھ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے میرے اکرام و اعزاز کے لیے وہاں تیار کر رکھا ہے وہ سب کچھ دیکھوں گا اور آج مجھے جتنا اپنے گھر کا راستہ آتا ہے اس سے زیادہ مجھے اپنے اس ٹھکانے کا راستہ آتا ہوگا اور قبر سے اٹھائے جانے تک جنت کی ہوا اور راحت کا سامان مجھ تک پہنچتا رہے گا۔ اور اگر خدانخواستہ دوسری حالت ہوئی، اور اس سے ہم ",""],["ٱللَّٰه","a"],[" کی پناہ چاہتے ہیں، تو میری قبر مجھ پر اتنی تنگ کر دی جائے گی کہ جیسے نیزے کی لکڑی نیزے کے پھل میں تنگ ہوتی ہے، وہ قبر اس سے بھی زیادہ تنگ ہوگی۔ پھر میرے لیے جہنم کے دروازوں میں سے ایک دروازہ کھول دیا جائے گا اور میں اس میں سے اپنی زنجیروں، بیڑیوں اور جہنم کے قیدی ساتھیوں کو دیکھوں گا اور آج مجھے جتنا اپنے گھر کا راستہ آتا ہے اس سے زیادہ مجھے جہنم میں اپنے ٹھکانے کا راستہ آتا ہوگا اور قبر سے اٹھائے جانے تک جہنم کی گرم ہوا اور گرم پانی کا اثر مجھ تک پہنچتا رہے گا۔",""]]]],"f":[]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ حضرت اسید بن حضیرؓ فضیلت والے لوگوں میں سے تھے، وہ کہا کرتے تھے کہ میں تین حالتوں میں جیسا ہوتا ہوں اگر میں ہر وقت ویسا رہوں تو میں یقیناً جنت والوں میں سے ہو جاؤں اور مجھے اس میں کوئی شک نہیں ہے: ایک وہ حالت جبکہ میں خود قرآن پڑھ رہا ہوں یا کوئی اور قرآن پڑھ رہا ہو اور میں سن رہا ہوں۔ دوسری وہ حالت جبکہ میں نبی کریم ",""],["ﷺ","a"],[" کا خطبہ سن رہا ہوں۔ تیسری وہ حالت جبکہ میں کسی جنازے میں شریک ہوں، اور جب بھی میں کسی جنازے میں شریک ہوتا ہوں تو اپنے دل میں صرف یہی سوچتا ہوں کہ اس جنازے کے ساتھ کیا ہوگا اور یہ جنازہ کہاں جا رہا ہے۔",""]]]],"f":[]}]},"11":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ ہم نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! جب ہم آپؐ کو دیکھتے ہیں تو ہمارے دل نرم ہو جاتے ہیں اور آخرت کی فکر والے بن جاتے ہیں لیکن جب ہم آپؐ سے جدا ہو جاتے ہیں تو ہمیں دنیا اچھی لگنے لگتی ہے اور بیویوں اور بچوں میں مشغول ہو جاتے ہیں۔ حضورؐ نے فرمایا:",""]]],["c",[["تم میرے پاس جس حالت پر ہوتے ہو اگر تم ہر وقت اس حالت پر رہو تو فرشتے اپنے ہاتھوں سے تم سے مصافحہ کرنے لگیں اور تمہارے گھروں میں تم سے ملنے آئیں۔ اگر تم گناہ نہ کرو تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ایسے لوگوں کو لے آئیں گے جو گناہ کریں گے (اور استغفار کریں گے) تاکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ ان کی مغفرت فرمائے۔",""],[" (1)","s"]]],["p",[["ہم نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہمیں جنت کے بارے میں بتائیں کہ اس کی عمارت کس چیز سے بنی ہوئی ہے؟ آپؐ نے فرمایا ایک اینٹ سونے کی اور ایک اینٹ چاندی کی ہے۔ اس کا گارا خوب مہکتے ہوئے مشک کا ہے۔ اس کی کنکریاں موتی اور یاقوت ہیں۔ اس کی مٹی زعفران ہے۔ جو جنت میں جائے گا وہ ہمیشہ عیش و عشرت میں رہے گا، کبھی بدحال نہ ہوگا۔ اور ہمیشہ رہے گا، کبھی اسے موت نہیں آئے گی اور نہ ہی اس کے کپڑے پرانے ہوں گے اور نہ کبھی اس کی جوانی ختم ہوگی۔ تین آدمی ایسے ہیں جن کی دعا کبھی رد نہیں ہوتی: ایک عادل بادشاہ، دوسرا روزہ دار جب تک روزہ نہ کھول لے، تیسرے مظلوم کی بددعا جسے بادلوں سے اوپر اٹھا لیا جاتا ہے اور اس کے لیے آسمانوں کے دروازے کھول دیے جاتے ہیں۔ پھر ",""],["ٱللَّٰه","a"],[" تبارک و تعالیٰ فرماتے ہیں میری عزت کی قسم! میں تیری مدد ضرور کروں گا اگرچہ اس میں کچھ دیر ہو جائے۔",""],[" (2)","s"]]]],"f":[["(1)","Abu Nu'aym, Bayhaqi and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.138)."],["(2)","Ahmad, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.49). Tirmidhi and Ibn Maajah have reported part of the narration."]]},{"b":[["n",[["حضرت سوید بن غفلہؒ","b"],[" کہتے ہیں کہ حضرت علیؓ پر ایک مرتبہ فاقہ آیا تو انہوں نے حضرت فاطمہؓ سے کہا اگر تم حضورؐ کی خدمت میں جا کر کچھ مانگ لو تو اچھا ہے؛ چنانچہ حضرت فاطمہؓ حضورؐ کے پاس گئیں۔ اس وقت حضورؐ کے پاس حضرت ام ایمنؓ موجود تھیں۔ حضرت فاطمہؓ نے دروازہ کھٹکھٹایا تو حضورؐ نے حضرت ام ایمنؓ سے فرمایا یہ کھٹکھٹاہٹ تو فاطمہؓ کی ہے۔ آج اس وقت آئی ہے، پہلے تو کبھی اس وقت نہیں آیا کرتی۔ پھر حضرت فاطمہؓ (اندر آئیں اور انہوں نے) عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ان فرشتوں کا کھانا ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],["، سبحان ",""],["ٱللَّٰه","a"],[" اور الحمد للہ کہنا ہے۔ ہمارا کھانا کیا ہے؟ آپؐ نے فرمایا اس ذات کی قسم جس نے مجھے حق دے کر بھیجا ہے، محمدؐ کے گھرانے میں تیس دن سے آگ نہیں جلی۔ ہمارے پاس چند بکریاں آئی ہیں، اگر تم چاہو تو پانچ بکریاں تمہیں دے دوں اور اگر چاہو تو تمہیں وہ پانچ کلمات سکھا دوں جو حضرت جبرائیلؑ نے مجھے سکھائے ہیں۔ حضرت فاطمہؓ نے عرض کیا نہیں، بلکہ مجھے تو وہی پانچ کلمات سکھا دیں جو آپؐ کو حضرت جبرائیل علیہ السلام نے سکھائے ہیں۔ حضورؐ نے فرمایا تم یہ کہا کرو:",""]]],["q",[["يَا أَوَّلَ ٱلْأَوَّلِينَ وَيَا آخِرَ ٱلْآخِرِينَ وَيَا ذَا ٱلْقُوَّةِ ٱلْمَتِينِ وَيَا رَاحِمَ ٱلْمَسَاكِينِ وَيَا أَرْحَمَ ٱلرَّاحِمِينَ","a"]]],["p",[["پھر حضرت فاطمہؓ واپس چلی گئیں۔ جب حضرت علیؓ کے پاس پہنچیں تو حضرت علیؓ نے پوچھا کیا ہوا؟ حضرت فاطمہؓ نے عرض کیا میں آپ کے پاس سے دنیا لینے گئی تھی لیکن وہاں سے آخرت لے کر آئی ہوں۔ حضرت علیؓ نے فرمایا پھر تو یہ دن تمہارا سب سے بہترین دن ہے۔",""],[" (3)","s"]]]],"f":[["(3)","Abu Sheikh, as quoted in Kanzul Ummaal (Vol.1 Pg.302)."]]},{"b":[["n",[["حضرت انس بن مالکؓ","b"],[" فرماتے ہیں کہ ہم لوگ ایک سفر میں حضرت ابو موسیٰؓ کے ساتھ تھے۔ انہوں نے لوگوں کو باتیں کرتے ہوئے اور فصیح و بلیغ گفتگو کرتے ہوئے سنا تو فرمایا اے انس! مجھے ان کی باتوں سے کیا تعلق؟ آؤ ہم اپنے رب کا ذکر کریں کیونکہ یہ لوگ تو اپنی زبان سے کھال ہی اتار دیں گے۔ پھر مجھ سے فرمایا اے انس! کس چیز نے ان لوگوں کو آخرت سے پیچھے کر دیا اور کس چیز نے انہیں آخرت سے روک دیا؟ میں نے عرض کیا خواہشات نے اور شیطان نے۔ حضرت ابو موسیٰؓ نے فرمایا نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! بلکہ انہوں نے اس وجہ سے آخرت کو چھوڑ دیا کہ دنیا تو سامنے ہے اور آخرت بعد میں آئے گی۔ اگر یہ آنکھوں سے آخرت دیکھ لیتے تو اس سے نہ ہٹتے اور شک نہ کرتے۔",""],[" (4)","s"]]]],"f":[["(4)","Abu Nu'aym in his Hilya (Vol.1 Pg.259)."]]}]},"12":{"lead":[],"stories":[{"b":[["n",[["حضرت عمران بن حصینؓ","b"],[" فرماتے ہیں کہ جب یَآ أَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ سے لے کر وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌ تک دو آیتیں نازل ہوئیں:",""]]],["q",[["يَٰٓأَيُّهَا ٱلنَّاسُ ٱتَّقُوا۟ رَبَّكُمْ ۚ إِنَّ زَلْزَلَةَ ٱلسَّاعَةِ شَىْءٌ عَظِيمٌ ... وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌ  (سورۃ الحج: ۱-۲)","a"]]],["p",[["ترجمہ: \"اے لوگو! اپنے رب سے ڈرو، (کیونکہ) یقیناً قیامت (کے دن) کا زلزلہ بڑی بھاری چیز ہے۔ جس روز تم لوگ اس (زلزلے) کو دیکھو گے تمام دودھ پلانے والیاں (مارے ہیبت کے) اپنے دودھ پیتے بچوں کو بھول جائیں گی اور تمام حمل والیاں اپنا حمل (دن پورے ہونے سے پہلے) ڈال دیں گی اور (اے مخاطب!) تجھ کو لوگ نشے کی سی حالت میں دکھائی دیں گے؛ حالانکہ وہ (واقع میں) نشے میں نہ ہوں گے لیکن ",""],["ٱللَّٰه","a"],[" کا عذاب ہی سخت چیز ہے۔\" تو اس وقت حضورؐ سفر میں تھے۔ حضورؐ نے فرمایا تم لوگ جانتے ہو یہ کونسا دن ہے؟ صحابہؓ نے عرض کیا ",""],["ٱللَّٰه","a"],[" اور اس کا رسول زیادہ جانتے ہیں۔ حضورؐ نے فرمایا یہ وہ دن ہے جس دن ",""],["ٱللَّٰه","a"],[" تعالیٰ حضرت آدم (علیہ السلام) سے فرمائیں گے آگ میں جانے والوں کو بھیج دو۔ وہ عرض کریں گے اے میرے رب! آگ میں جانے والے کتنے ہیں؟ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے نو سو ننانوے تو آگ میں جائیں گے اور ایک آدمی جنت میں جائے گا۔ یہ سن کر سارے مسلمان رونے لگ پڑے۔ حضورؐ نے فرمایا میانہ روی اختیار کرو اور ٹھیک ٹھیک چلتے رہو۔ ہر نبوت سے پہلے جاہلیت کا زمانہ ہوا کرتا تھا، پہلے یہ تعداد ان جاہلیت والوں سے پوری کی جائے گی، پھر منافقوں سے پوری کی جائے گی۔ تمہاری اور باقی تمام امتوں کی مثال ایسی ہے جیسے کسی جانور کے پاؤں میں ابھری ہوئی غدود ہو یا جیسے اونٹ کے پہلو میں تل ہو۔ پھر فرمایا مجھے امید ہے کہ آپ لوگ جنت والوں میں سے چوتھائی ہوں گے۔ اس پر صحابہؓ نے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ پھر فرمایا مجھے امید ہے آپ لوگ جنت میں جانے والوں کا تہائی حصہ ہوں گے۔ اس پر صحابہؓ نے پھر ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ پھر آپؐ نے فرمایا مجھے امید ہے کہ آپ لوگ جنت میں جانے والوں میں سے آدھے ہوں گے۔ صحابہؓ نے پھر ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ راوی کہتے ہیں مجھے معلوم نہیں کہ حضورؐ نے دو تہائی بھی فرمایا یا نہیں (لیکن طبرانی اور ترمذی کی دوسری روایت میں یہ ہے کہ یہ امت جنت والوں کا دو تہائی ہوگی، یعنی ",""],["ٱللَّٰه","a"],[" نے حضورؐ کی امید سے زیادہ کر دیا)۔",""],[" (1)","s"]]],["p",[["اسی آیت کی تفسیر میں بخاری میں یہ روایت ہے کہ حضرت ابوسعیدؓ فرماتے ہیں کہ نبی کریم ",""],["ﷺ","a"],[" نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ قیامت کے دن فرمائیں گے اے آدم! وہ عرض کریں گے اے ہمارے رب! میں حاضر ہوں، ہر خدمت کے لیے تیار ہوں۔ پھر ان کو بلند آواز سے کہا جائے گا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ آپ کو حکم دے رہے ہیں کہ آپ اپنی اولاد میں سے آگ میں جانے والوں کو نکال لیں۔ حضرت آدمؑ پوچھیں گے آگ میں جانے والے کتنے ہیں؟ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرمائیں گے ہر ہزار میں سے نو سو ننانوے۔ تو اس وقت ہر حمل والی اپنا حمل ڈال دے گی اور بچہ بوڑھا ہو جائے گا:",""]]],["q",[["وَتَرَى ٱلنَّاسَ سُكَٰرَىٰ وَمَا هُم بِسُكَٰرَىٰ وَلَٰكِنَّ عَذَابَ ٱللَّهِ شَدِيدٌ","a"]]],["p",[["(ترجمہ گزر چکا ہے)۔ یہ سن کر صحابہؓ پر ایسا رنج و غم طاری ہوا کہ ان کے چہرے (غم کے مارے) بدل گئے۔ حضورؐ نے فرمایا یاجوج ماجوج میں سے نو سو ننانوے ہوں گے (جو جہنم میں جائیں گے) اور تم میں سے ایک ہوگا (جو جنت میں جائے گا)۔ تم باقی لوگوں میں ایسے ہو جیسے سفید بیل کے پہلو میں کالا بال یا کالے بیل کے پہلو میں سفید بال۔ مجھے امید ہے کہ تم جنت والوں کا چوتھائی حصہ ہو گے۔ ہم نے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ پھر حضورؐ نے فرمایا تم جنت والوں کا تہائی ہو گے۔ ہم نے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ پھر حضورؐ نے فرمایا تم جنت والوں کے آدھے ہو گے، پھر ہم نے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔",""],["(2)","s"],[" ایک روایت میں یہ ہے کہ یہ بات صحابہؓ پر بڑی گراں گزری اور ان پر رنج و غم طاری ہو گیا۔",""],[" (3)","s"]]]],"f":[["(1)","Tirmidhi, Ahmad and Ibn Abi Haatim."],["(2)","Bukhaari, Muslim and Nasa'ee, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.204)."],["(3)","Haakim (Vol.4 Pg.568)."]]},{"b":[["n",[["حضرت ابن زبیرؓ","b"],[" فرماتے ہیں کہ جب یہ آیت نازل ہوئی:",""]]],["q",[["ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ  (سورۃ الزمر: ۳۱)","a"]]],["p",[["ترجمہ: \"پھر قیامت کے روز تم مقدمات اپنے رب کے سامنے پیش کرو گے (اس وقت عملی فیصلہ ہو جائے گا)\"، تو حضرت زبیرؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! کیا مقدمات بار بار پیش کیے جائیں گے؟ حضورؐ نے فرمایا ہاں۔ حضرت زبیرؓ نے کہا پھر تو معاملہ بڑا سخت ہوگا۔",""],["(4)","s"],[" ایسے ہی اس حدیث کو امام احمد نے روایت کیا ہے۔ اس میں مزید یہ مضمون بھی ہے کہ جب یہ آیت نازل ہوئی:",""]]],["q",[["ثُمَّ لَتُسْـَٔلُنَّ يَوْمَئِذٍ عَنِ ٱلنَّعِيمِ  (سورۃ التکاثر: ۸) ","a"]]],["p",[["ترجمہ: \"پھر (اور بات سنو کہ) اس روز تم سب سے نعمتوں کی پوچھ ہوگی۔\" تو حضرت زبیرؓ نے پوچھا یا رسول ",""],["ٱللَّٰه","a"],["! ہم سے کس نعمت کا سوال ہوگا؟ ہمارے پاس تو صرف یہ دو سیاہ چیزیں ہیں، کھجور اور پانی۔",""],[" (5)","s"]]]],"f":[["(4)","Ibn Abi Haatim."],["(5)","Ahmad, Tirmidhi and Ibn Maajah."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن زبیرؓ","b"],[" فرماتے ہیں کہ جب یہ سورت حضورؐ پر نازل ہوئی:",""]]],["q",[["إِنَّكَ مَيِّتٌ وَإِنَّهُم مَّيِّتُونَ ۝ ثُمَّ إِنَّكُمْ يَوْمَ ٱلْقِيَٰمَةِ عِندَ رَبِّكُمْ تَخْتَصِمُونَ  (سورۃ الزمر: ۳۰-۳۱)","a"]]],["p",[["ترجمہ: \"آپ کو بھی مرنا ہے اور ان کو بھی مرنا ہے، پھر قیامت کے روز تم مقدمات اپنے رب کے سامنے پیش کرو گے (اس وقت عملی فیصلہ ہو جائے گا)\"، تو حضرت زبیر بن عوامؓ نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! خاص خاص گناہوں کے ساتھ ہم پر وہ جھگڑے بھی بار بار پیش کیے جائیں گے جو دنیا میں ہمارے آپس میں تھے؟ حضورؐ نے فرمایا ہاں، یہ مقدمات بار بار پیش کیے جاتے رہیں گے یہاں تک کہ ہر حق والے کو اس کا حق مل جائے۔ حضرت زبیرؓ نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! پھر تو معاملہ بہت سخت ہے۔",""],[" (6)","s"]]]],"f":[["(6)","Ahmad and Tirmidhi, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.52). Haakim (Vol.4 Pg.572) has reported a similar narration from reliable sources."]]},{"b":[["n",[["حضرت قیس بن ابی حازمؒ","b"],[" کہتے ہیں کہ حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہؓ اپنی بیوی کی گود میں سر رکھے ہوئے تھے کہ اتنے میں رونے لگے، پھر ان کی بیوی بھی رونے لگی۔ ابن رواحہؓ نے کہا تم کیوں رو رہی ہو؟ انہوں نے کہا میں نے آپ کو روتے ہوئے دیکھا اس لیے میں بھی رونے لگی۔ حضرت ابن رواحہؓ نے کہا ",""],["ٱللَّٰه","a"],[" تعالیٰ کا یہ فرمان یاد آ گیا:",""]]],["q",[["وَإِن مِّنكُمْ إِلَّا وَارِدُهَا  (سورۃ مریم: ۷۱)","a"]]],["p",[["ترجمہ: \"اور تم میں سے کوئی بھی نہیں جس کا اس (جہنم) سے گزر نہ ہو۔\" اب مجھے معلوم نہیں کہ میں جہنم سے نجات پا سکوں گا یا نہیں۔ ایک روایت میں یہ ہے کہ حضرت ابن رواحہؓ اس وقت بیمار تھے۔",""],[" (7)","s"]]]],"f":[["(7)","Abdur Razzaaq, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.132)."]]},{"b":[["n",[["حضرت عبادہ بن محمد بن عبادہ بن صامتؒ","b"],[" کہتے ہیں کہ جب حضرت عبادہؓ کی وفات کا وقت قریب آیا تو انہوں نے فرمایا میرا بستر گھر کے صحن میں باہر نکال دو، پھر فرمایا میرے سارے غلام، خادم اور پڑوسی اور وہ تمام آدمی یہاں جمع کرو جو میرے پاس آیا کرتے تھے۔ جب یہ سب ان کے پاس جمع ہو گئے تو فرمایا میرا تو یہی خیال ہے کہ آج کا دن میری دنیا کی زندگی کا آخری دن ہے اور آج کی رات میری آخرت کی پہلی رات ہے اور مجھے معلوم تو نہیں لیکن ہو سکتا ہے کہ میرے ہاتھ سے یا میری زبان سے تم لوگوں کے ساتھ کوئی زیادتی ہوئی ہو، اور اس ذات کی قسم جس کے قبضے میں میری جان ہے مجھے قیامت کے دن اس کا بدلہ دینا پڑے گا۔ میں پورے زور سے تم لوگوں سے درخواست کرتا ہوں کہ تم لوگوں میں سے کسی کے دل میں اگر ایسی کوئی بات ہو تو وہ میری جان کے نکلنے سے پہلے مجھ سے بدلہ لے لے۔ ان سب نے کہا نہیں، آپ تو ہمارے لیے والد کی طرح تھے اور ہمیں ادب سکھاتے تھے۔ راوی کہتے ہیں کہ انہوں نے کبھی کسی خادم کو برا بھلا نہیں کہا تھا۔ پھر انہوں نے کہا جو کچھ بھی ہوا ہو، کیا تم نے مجھے معاف کر دیا ہے؟ سب نے کہا جی ہاں۔ فرمایا اے ",""],["ٱللَّٰه","a"],["! تو گواہ ہو جا۔ پھر فرمایا اگر ایسی کوئی بات نہیں ہے تو پھر میری وصیت یاد رکھنا۔ میں پر زور تاکید کرتا ہوں کہ تم میں سے کوئی بھی میرے مرنے پر ہرگز نہ روئے بلکہ جب میری جان نکل جائے تو تم وضو کرنا اور اچھی طرح وضو کرنا اور پھر تم میں سے ہر آدمی مسجد میں جا کر نماز پڑھے، پھر عبادہ کے لیے یعنی میرے لیے استغفار کر لے کیونکہ ",""],["ٱللَّٰه","a"],[" تبارک و تعالیٰ نے فرمایا ہے:",""]]],["q",[["وَٱسْتَعِينُوا۟ بِٱلصَّبْرِ وَٱلصَّلَوٰةِ  (سورۃ البقرہ: ۴۵، ۱۵۳)","a"]]],["p",[["ترجمہ: \"صبر اور نماز سے سہارا حاصل کرو۔\" پھر مجھے قبر کی طرف جلدی جلدی لے جانا، میرے جنازے کے پیچھے آگ لے کر نہ چلنا اور نہ میرے نیچے ارغوانی رنگ کا کپڑا ڈالنا۔",""],[" (8)","s"]]],["p",[["بیت المال میں سے اپنے اوپر اور اپنے رشتہ داروں پر خرچ کرنے میں احتیاط برتنے کے باب میں",""],["(9)","s"],[" یہ قصہ گزر چکا ہے کہ جب حضرت عمرؓ نے حضرت عبدالرحمن بن عوفؓ سے چار ہزار درہم ادھار مانگے تو حضرت عبدالرحمنؓ نے حضرت عمرؓ کے قاصد سے کہا جا کر حضرت عمرؓ سے کہہ دو کہ ابھی وہ بیت المال سے چار ہزار لے لیں، پھر بعد میں واپس کر دیں۔ جب قاصد نے واپس آ کر حضرت عمرؓ کو ان کا جواب بتایا تو حضرت عمرؓ کو بڑی گرانی ہوئی۔ پھر جب حضرت عمرؓ کی حضرت عبدالرحمنؓ سے ملاقات ہوئی تو ان سے کہا تم نے کہا تھا کہ عمر چار ہزار بیت المال سے ادھار لے لے اگر میں (بیت المال سے ادھار لے کر تجارتی قافلے کے ساتھ بھیج دوں اور پھر) تجارتی قافلے کی واپسی سے پہلے مر جاؤں تو تم لوگ کہو گے کہ امیر المومنین نے چار ہزار لیے تھے، اب ان کا انتقال ہو گیا ہے، اس لیے ان کے چار ہزار چھوڑ دو (تم لوگ تو چھوڑ دو گے) اور میں ان کے بدلے قیامت کے دن پکڑا جاؤں گا۔",""]]],["p",[["اور عنقریب ",""],["ٱللَّٰه","a"],[" تعالیٰ کے علم سے اور اس کے رسولؐ کے علم سے اثر لینے کے باب میں یہ قصہ آئے گا کہ جب حضرت ابوہریرہؓ قاری، عالم، مالدار اور ",""],["ٱللَّٰه","a"],[" کے راستے میں شہید ہونے والے کے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ کے (اخلاص نہ ہونے کی وجہ سے دوزخ میں جانے کے) فیصلے والی حدیث ذکر کرتے تو اتنا زیادہ روتے کہ بیہوش ہو جاتے اور چہرے کے بل گر جاتے، یہاں تک کہ حضرت شفی اصبحیؒ انہیں سہارا دیتے اور بہت دیر تک ان کا یہی حال رہتا۔ اور حضرت معاویہؓ جب یہ حدیث سنتے تو اتنا زیادہ روتے کہ لوگ یہ سمجھتے کہ ان کی تو اب جان نکل جائے گی۔",""]]]],"f":[["(8)","Bayhaqi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.79)."],["(9)","Under the heading \"Abstention from using Public Funds for Personal use and for Close Relatives\" and the subheading \"The Incident of Hadhrat Umar and Hadhrat Abdur Rahmaan bin Auf\"."]]}]},"13":{"lead":[],"stories":[{"b":[["n",[["حضرت عوف بن مالکؓ","b"],[" فرماتے ہیں کہ ایک سفر میں حضورؐ نے آخر شب میں ایک جگہ پڑاؤ ڈالا۔ ہم بھی آپؐ کے ساتھ تھے۔ ہم میں سے ہر آدمی اپنے کجاوے کی لکڑی کے ساتھ ٹیک لگا کر سو گیا۔ کچھ دیر بعد میری آنکھ کھلی تو مجھے حضورؐ اپنے کجاوے کے پاس نظر نہ آئے۔ اس سے میں گھبرا گیا اور حضورؐ کو تلاش کرنے چل پڑا۔ ڈھونڈتے ڈھونڈتے ایک جگہ مجھے حضرت معاذ بن جبلؓ اور حضرت ابو موسیٰ اشعریؓ ملے۔ وہ دونوں بھی اسی وجہ سے گھبرائے ہوئے تھے جس وجہ سے میں گھبرایا ہوا تھا۔ ہم لوگ یونہی ڈھونڈ رہے تھے کہ اچانک ہمیں وادی کے اوپر کے حصے سے چکی چلنے جیسی آواز سنائی دی۔ (ہم لوگ اس آواز کی طرف گئے تو دیکھا حضورؐ رو رہے ہیں)۔ پھر ہم نے حضورؐ کو اپنی بات بتائی۔ حضورؐ نے فرمایا:",""]]],["c",[["آج رات میرے پاس میرے رب کی طرف سے ایک فرشتہ آیا اور اس نے مجھے دو باتوں میں اختیار دیا کہ یا تو میں شفاعت کروں یا میری آدھی امت جنت میں چلی جائے۔ میں نے شفاعت کو اختیار کر لیا۔",""]]],["p",[["میں نے عرض کیا اے ",""],["ٱللَّٰه","a"],[" کے نبی! میں آپؐ کو ",""],["ٱللَّٰه","a"],[" کا اور آپؐ کی صحبت میں رہنے کا واسطہ دے کر عرض کرتا ہوں کہ آپؐ ہمیں بھی اپنی شفاعت والوں میں شامل کر لیں۔ حضورؐ نے فرمایا آپ لوگ تو میری شفاعت والوں میں ہو ہی۔ پھر ہم لوگ حضورؐ کے ساتھ چل پڑے یہاں تک کہ ہم لوگوں کے پاس پہنچ گئے تو وہ بھی حضورؐ کو اپنی جگہ نہ پا کر گھبرائے ہوئے تھے۔ یہ دیکھ کر حضورؐ نے فرمایا میرے پاس میرے رب کی طرف سے ایک فرشتہ آیا اور اس نے مجھے ان باتوں میں اختیار دیا کہ یا تو میں شفاعت اختیار کر لوں یا میری آدھی امت جنت میں داخل ہو جائے؛ چنانچہ میں نے شفاعت کو اختیار کر لیا۔ صحابہؓ نے حضورؐ کی خدمت میں عرض کیا ہم آپؐ کو ",""],["ٱللَّٰه","a"],[" کا اور آپؐ کی صحبت میں رہنے کا واسطہ دے کر عرض کرتے ہیں کہ آپؐ ہمیں بھی اپنی شفاعت والوں میں شامل کر لیں۔ جب تمام صحابہؓ آپؐ کے پاس جمع ہو گئے تو آپؐ نے فرمایا:",""]]],["c",[["میں تمام حاضرین کو اس بات پر گواہ بناتا ہوں کہ میری شفاعت میری امت میں سے ہر اس آدمی کے لیے ہے جو اس حال میں مرے کہ ",""],["ٱللَّٰه","a"],[" کے ساتھ کسی کو شریک نہ ٹھہراتا ہو۔",""],[" (1)","s"]]]],"f":[["(1)","Baghawi and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.271)."]]},{"b":[["n",[["حضرت عبدالرحمن بن ابی عقیلؓ","b"],[" فرماتے ہیں کہ میں قبیلہ ثقیف کے وفد کے ساتھ حضورؐ کے پاس گیا۔ جب ہم نے دروازے کے پاس سواریاں بٹھائیں تو اس وقت جس ذات کے پاس جا رہے تھے ہمارے نزدیک اس سے زیادہ مبغوض اور کوئی انسان نہیں تھا لیکن جب اس کی خدمت میں حاضری دے کر باہر آئے تو اس وقت ہمارے نزدیک اس ذات سے زیادہ محبوب اور کوئی انسان نہیں تھا جس کی خدمت میں ہم گئے تھے۔ ہم میں سے ایک آدمی نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ نے اپنے رب سے حضرت سلیمانؑ جیسا ملک کیوں نہ مانگ لیا؟ اس پر حضورؐ ہنس پڑے اور فرمایا ہو سکتا ہے تمہارے نبی کو ",""],["ٱللَّٰه","a"],[" کے ہاں ملک سلیمانی سے بہتر کوئی چیز مل جائے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جو نبی بھی بھیجا اسے ایک خاص دعا ضرور عطا فرمائی۔ کسی نبیؑ نے وہ دعا مانگ کر دنیا لے لی، کسی نبی کی قوم نافرمان تھی تو اس نے اپنی قوم کے خلاف بددعا کی تو وہ ساری قوم ہلاک ہو گئی۔ اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے مجھے بھی وہ خاص دعا عطا فرمائی لیکن میں نے وہ دعا اپنے رب کے ہاں چھپا کر رکھی ہوئی ہے اور وہ دعا یہ ہے کہ میں قیامت کے دن اپنی امت کے لیے شفاعت کروں گا۔",""],[" (2)","s"]]]],"f":[["(2)","Baghawi, Ibn Mandah and Ibn Asaakir, as quoted in Kanzul Ummaal (Vol.7 Pg.272). Bukhaari and Haarith bin Abu Usaamah have reported a similar narration, as quoted in Isaabah (Vol.2 Pg.411)."]]},{"b":[["n",[["حضرت ام سلمہؓ","b"],[" فرماتی ہیں کہ حضورؐ نے فرمایا میں اپنی امت کے برے لوگوں کے لیے بہترین آدمی ہوں۔ تو قبیلہ مزینہ کے ایک آدمی نے حضورؐ کی خدمت میں عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! جب آپ اپنی امت کے بروں کے لیے ایسے ہیں تو ان کے نیکوں کے لیے کیسے ہیں؟ آپؐ نے فرمایا میری امت کے نیک لوگ اپنے اعمال کی برکت سے جنت میں داخل ہو جائیں گے اور میری امت کے برے لوگ میری شفاعت کا انتظار کریں گے۔ غور سے سنو! میری شفاعت قیامت کے دن میری امت کے تمام لوگوں کے لیے ہوگی سوائے اس آدمی کے جو میرے صحابہؓ میں کمی نکالتا ہو۔",""],[" (3)","s"]]]],"f":[["(3)","Shiraazi in his Alqaab and Ibn Najjaar, as quoted in Kanzul Ummaal (Vol.7 Pg.272)."]]},{"b":[["n",[["حضرت علی بن ابی طالبؓ","b"],[" فرماتے ہیں کہ حضورؐ نے فرمایا میں اپنی امت کے لیے شفاعت کرتا رہوں گا یہاں تک کہ میرا رب مجھے پکار کر پوچھے گا اے محمد! کیا تم راضی ہو گئے؟ میں کہوں گا جی ہاں میں راضی ہو گیا۔ پھر حضرت علیؓ نے (لوگوں کی طرف) متوجہ ہو کر فرمایا تم عراق والے یہ کہتے ہو کہ قرآن میں سب سے زیادہ امید والی آیت یہ ہے:",""]]],["q",[["قُلْ يَٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ  (سورۃ الزمر: ۵۳)","a"]]],["p",[["ترجمہ: \"آپ کہہ دیجیے کہ اے میرے بندو جنہوں نے (کفر و شرک کر کے) اپنے اوپر زیادتیاں کی ہیں کہ تم خدا کی رحمت سے ناامید مت ہو، بالیقین ",""],["ٱللَّٰه","a"],[" تعالیٰ تمام (گزشتہ) گناہوں کو معاف فرما دے گا۔ واقعی وہ بڑا بخشنے والا بڑی رحمت والا ہے۔\" میں نے کہا ہم تو یہی کہتے ہیں۔ حضرت علیؓ نے فرمایا لیکن ہم اہل بیت یہ کہتے ہیں کہ ",""],["ٱللَّٰه","a"],[" کی کتاب میں سے سب سے زیادہ امید والی آیت یہ ہے:",""]]],["q",[["وَلَسَوْفَ يُعْطِيكَ رَبُّكَ فَتَرْضَىٰٓ  (سورۃ الضحیٰ: ۵) ","a"]]],["p",[["ترجمہ: \"اور عنقریب ",""],["ٱللَّٰه","a"],[" تعالیٰ آپ کو (آخرت میں بکثرت نعمتیں) دے گا سو آپ خوش ہو جائیں گے\" اور اس دینے سے مراد شفاعت ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Mardway, as quoted in Kanzul Ummaal (Vol.7 Pg.273)."]]},{"b":[["n",[["حضرت ابن بریدہؒ","b"],[" کہتے ہیں کہ میرے والد حضرت بریدہؓ حضرت معاویہؓ کے پاس گئے، وہاں اس وقت ایک آدمی بات کر رہا تھا۔ حضرت بریدہؓ نے کہا کیا آپ مجھے بات کرنے کی اجازت دیتے ہیں؟ حضرت معاویہؓ نے کہا جی ہاں! اجازت ہے۔ حضرت معاویہؓ کا خیال تھا کہ حضرت بریدہؓ بھی ویسی بات کریں گے جیسی دوسرا کر رہا تھا۔ حضرت بریدہؓ نے کہا میں نے حضورؐ کو فرماتے ہوئے سنا کہ ",""],["مجھے امید ہے کہ میں قیامت کے دن اتنے لوگوں کی شفاعت کروں گا جتنے زمین پر درخت اور پتھر ہیں۔","h"],[" پھر حضرت بریدہؓ نے کہا اے معاویہ! آپ تو اس شفاعت کے امیدوار ہیں اور حضرت علیؓ اس شفاعت کے امیدوار نہیں ہیں۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.56)."]]},{"b":[["n",[["حضرت طلق بن حبیبؒ","b"],[" کہتے ہیں کہ میں لوگوں میں سے سب سے زیادہ شفاعت کو جھٹلایا کرتا تھا یہاں تک کہ ایک دن میری ملاقات حضرت جابر بن عبد",""],["ٱللَّٰه","a"],["ؓ سے ہوئی اور (اپنی بات کو ثابت کرنے کے لیے) میں نے ان کو وہ تمام آیتیں پڑھ کر سنائیں جو مجھے آتی تھیں اور جن میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جہنم والوں کے جہنم میں ہمیشہ رہنے کا ذکر فرمایا ہے۔ حضرت جابرؓ نے فرمایا اے طلق! کیا تم یہ سمجھتے ہو کہ تم مجھ سے زیادہ ",""],["ٱللَّٰه","a"],[" کی کتاب کو پڑھنے والے ہو اور مجھ سے زیادہ رسول ",""],["ٱللَّٰه","a"],["ؐ کی سنت کو جاننے والے ہو؟ تم نے جو آیتیں پڑھی ہیں ان سے مراد تو وہ جہنم والے ہیں جو مشرک ہیں اور شفاعت ان لوگوں کے بارے میں ہے جو (مسلمان تھے لیکن وہ) بہت سے گناہ کر بیٹھے اور انہیں (جہنم میں) عذاب دیا جائے گا، پھر ان کو (حضورؐ کی شفاعت پر) جہنم سے نکالا جائے گا۔ پھر حضرت جابرؓ نے اپنے دونوں ہاتھ اپنے کانوں کو لگا کر کہا یہ دونوں کان بہرے ہو جائیں اگر میں نے حضورؐ کو یہ فرماتے ہوئے نہ سنا ہو کہ جہنم میں ڈالنے کے بعد ان کو اس میں سے نکالا جائے گا۔ جیسے تم قرآن پڑھتے ہو ہم بھی ویسے ہی پڑھتے ہیں۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Mardway."]]},{"b":[["n",[["حضرت یزید الفقیرؒ","b"],[" کہتے ہیں کہ حضرت جابر بن عبد",""],["ٱللَّٰه","a"],["ؓ حدیثیں بیان فرما رہے تھے، میں ان کی مجلس میں جا کر بیٹھ گیا۔ انہوں نے یہ بیان کیا کہ کچھ لوگ جہنم کی آگ سے باہر نکلیں گے۔ ان دنوں میں اس بات کو نہیں مانتا تھا اس لیے مجھے غصہ آ گیا اور میں نے کہا اور لوگوں پر تو مجھے تعجب نہیں ہے لیکن اے محمدؐ کے صحابہؓ! مجھے آپ لوگوں پر بڑا تعجب ہے۔ آپ لوگ یہ کہہ رہے ہیں کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ آگ سے کچھ لوگوں کو نکالیں گے حالانکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ فرماتے ہیں:",""]]],["q",[["يُرِيدُونَ أَن يَخْرُجُوا۟ مِنَ ٱلنَّارِ وَمَا هُم بِخَٰرِجِينَ مِنْهَا  (سورۃ المائدہ: ۳۷)","a"]]],["p",[["ترجمہ: \"اس بات کی خواہش کریں گے کہ جہنم سے نکل آویں اور وہ اس سے کبھی نہ نکلیں گے۔\" حضرت جابرؓ کے ساتھی مجھے ڈانٹنے لگے۔ حضرت جابرؓ خود ان میں سب سے زیادہ بردبار تھے۔ انہوں نے فرمایا اس آدمی کو چھوڑ دو اور فرمایا یہ آیت تو کفار کے بارے میں ہے، پھر یہ آیت پڑھی:",""]]],["q",[["إِنَّ ٱلَّذِينَ كَفَرُوا۟ لَوْ أَنَّ لَهُم مَّا فِى ٱلْأَرْضِ جَمِيعًا وَمِثْلَهُۥ مَعَهُۥ لِيَفْتَدُوا۟ بِهِۦ مِنْ عَذَابِ يَوْمِ ٱلْقِيَٰمَةِ مَا تُقُبِّلَ مِنْهُمْ ۖ وَلَهُمْ عَذَابٌ أَلِيمٌ  (سورۃ المائدہ: ۳۶-۳۷)","a"]]],["p",[["ترجمہ: \"یقیناً جو لوگ کافر ہیں اگر ان کے پاس تمام دنیا بھر کی چیزیں ہوں اور ان چیزوں کے ساتھ اتنی چیزیں اور بھی ہوں تاکہ وہ اس سب کو دے کر روز قیامت کے عذاب سے چھوٹ جاویں تب بھی وہ چیزیں ہرگز ان سے قبول نہ کی جاویں گی اور ان کو دردناک عذاب ہوگا۔ اس بات کی خواہش کریں گے کہ جہنم سے نکل آئیں اور وہ اس سے کبھی نہ نکلیں گے اور ان کو عذاب دائمی ہوگا۔\" پھر حضرت جابرؓ نے کہا کیا تم قرآن نہیں پڑھتے ہو؟ میں نے کہا پڑھتا ہوں بلکہ میں نے قرآن یاد کیا ہوا ہے۔ انہوں نے کہا کیا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ نہیں فرمایا:",""]]],["q",[["وَمِنَ ٱلَّيْلِ فَتَهَجَّدْ بِهِۦ نَافِلَةً لَّكَ عَسَىٰٓ أَن يَبْعَثَكَ رَبُّكَ مَقَامًا مَّحْمُودًا  (سورۃ بنی اسرائیل: ۷۹)","a"]]],["p",[["ترجمہ: \"اور کسی قدر رات کے حصے میں سو اس میں تہجد پڑھا کیجیے جو کہ آپ کے لیے (فرض نمازوں کے علاوہ) زائد چیز ہے، امید ہے کہ آپ کا رب آپ کو مقام محمود میں جگہ دے گا۔\" یہی وہ مقام ہے (جو شفاعت کبریٰ کا ہے)۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ کچھ لوگوں کو ان کے گناہوں کی وجہ سے کچھ عرصہ جہنم میں رکھیں گے اور ان سے بات بھی نہ فرمائیں گے اور جب ان کو وہاں سے نکالنا چاہیں گے نکال لیں گے۔ حضرت یزید الفقیرؒ کہتے ہیں اس کے بعد میں نے کبھی شفاعت کو نہیں جھٹلایا۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abi Haatim, as quoted in Kanzul Ummaal (Vol.2 Pg.54)."]]}]},"14":{"lead":[],"stories":[{"b":[["n",[["حضرت حنظلہ کاتب اسیدیؓ","b"],[" جو حضورؐ کے کاتبوں میں سے تھے، وہ فرماتے ہیں کہ ہم حضورؐ کے پاس تھے۔ حضورؐ نے ہمارے سامنے جنت اور جہنم کا ذکر اس طرح فرمایا کہ گویا ہم دونوں کو آنکھوں سے دیکھ رہے ہیں۔ پھر میں اٹھ کر بیوی بچوں کے پاس چلا گیا اور ان کے ساتھ ہنسنے کھیلنے لگ گیا۔ پھر مجھے وہ حالت یاد آئی جو (حضورؐ کے سامنے) ہماری تھی (کہ ہم دنیا بھولے ہوئے تھے اور جنت اور جہنم آنکھوں کے سامنے تھیں اور اب وہ نہ رہی تھیں)۔ یہ سوچ کر میں باہر نکلا تو حضرت ابوبکرؓ مجھے ملے۔ میں نے کہا اے ابوبکر! میں تو منافق ہو گیا۔ انہوں نے کہا کیا بات ہوئی؟ میں نے کہا ہم لوگ حضورؐ کے پاس ہوتے ہیں، حضورؐ ہمارے سامنے جنت اور جہنم کا ذکر اس طرح فرماتے ہیں کہ گویا ہم دونوں کو آنکھوں سے دیکھ رہے ہیں۔ جب ہم آپؐ کے پاس سے باہر آ جاتے ہیں اور بیوی بچوں اور کام کاج میں لگ جاتے ہیں تو ہم (جنت جہنم سب) بھول جاتے ہیں۔ حضرت ابوبکرؓ نے کہا ہمارا بھی یہی حال ہے۔ پھر میں نے جا کر حضورؐ کی خدمت میں یہ ساری بات ذکر کی۔ آپؐ نے فرمایا:",""]]],["c",[["اے حنظلہ! تمہاری جو حالت میرے پاس ہوتی ہے وہی اگر گھر والوں کے پاس جا کر بھی رہے تو فرشتے تم سے بستروں پر اور راستوں میں مصافحہ کرنے لگیں، لیکن حنظلہ! بات یہ ہے کہ گاہے گاہے ہوتا ہے۔",""],[" (1)","s"]]]],"f":[["(1)","Hasan bin Sufyaan and Abu Nu'aym, as quoted in Kanzul Ummaal (Vol.1 Pg.100)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن مسعودؓ","b"],[" فرماتے ہیں کہ ایک رات ہم نے حضورؐ کے پاس جاگ کر گزاری اور صبح ہم حضورؐ کی خدمت میں گئے۔ آپؐ نے فرمایا آج رات مجھے خواب میں انبیاء علیہم السلام اور ان کی تابعدار امتیں دکھائی گئیں۔ ایک ایک میرے پاس سے گزرتا تھا، کوئی نبی ایک جماعت میں ہوتا، کسی کے ساتھ تین آدمی ہوتے، کسی کے ساتھ کوئی بھی نہ ہوتا۔ حضرت قتادہؒ نے یہ آیت پڑھی:",""]]],["q",[["أَلَيْسَ مِنكُمْ رَجُلٌ رَّشِيدٌ  (سورۃ ہود: ۷۸)","a"]]],["p",[["ترجمہ: \"کیا تم میں کوئی بھی (معقول آدمی اور) بھلا مانس نہیں\" پھر حضورؐ نے فرمایا پھر میرے پاس سے حضرت موسیٰ بن عمران علیہ السلام بنی اسرائیل کی ایک بہت بڑی جماعت کے ساتھ گزرے۔ حضورؐ فرماتے ہیں، میں نے پوچھا یہ کون ہیں؟ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا یہ آپ کے بھائی حضرت موسیٰ بن عمران اور ان کے تابعدار امتی ہیں۔ میں نے عرض کیا اے میرے رب! میری امت کہاں ہے؟ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا اپنی دائیں طرف ٹیلوں میں دیکھو۔ میں نے وہاں دیکھا تو بہت سے آدمیوں کے چہرے نظر آئے۔ پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا کیا آپ راضی ہو گئے؟ میں نے کہا اے میرے رب! میں راضی ہو گیا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا اب اپنی بائیں طرف آسمان کے کنارے میں دیکھو۔ میں نے وہاں دیکھا تو بہت سے آدمیوں کے چہرے نظر آئے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا کیا آپ راضی ہو گئے؟ میں نے کہا اے میرے رب! میں راضی ہو گیا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ان کے ساتھ ستر ہزار اور بھی ہیں جو جنت میں حساب کے بغیر داخل ہوں گے۔ پھر قبیلہ بنو اسد کے حضرت عکاشہ بن محصنؓ جو کہ بدری تھے وہ کہنے لگے اے ",""],["ٱللَّٰه","a"],[" کے نبی! ",""],["ٱللَّٰه","a"],[" سے میرے لیے دعا کریں کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ مجھے ان میں شامل کر دے۔ حضورؐ نے دعا فرمائی اے ",""],["ٱللَّٰه","a"],["! اسے ان میں شامل فرما دے۔ پھر ایک اور آدمی نے کہا اے ",""],["ٱللَّٰه","a"],[" کے نبی! ",""],["ٱللَّٰه","a"],[" سے دعا کریں ",""],["ٱللَّٰه","a"],[" مجھے بھی ان میں شامل کر دے۔ حضورؐ نے فرمایا اس دعا میں عکاشہ تم سے سبقت لے گئے۔ پھر حضورؐ نے صحابہؓ سے فرمایا میرے ماں باپ تم پر قربان ہوں، اگر تم ستر ہزار والوں میں سے ہو سکتے ہو تو ان میں سے ضرور ہو جاؤ اور اگر یہ نہ ہو سکے تو تم ٹیلوں والوں میں سے ہو جاؤ اور اگر یہ بھی نہ ہو سکے تو پھر ان میں سے ہو جاؤ جن کو میں نے آسمان کے کنارے میں دیکھا تھا کیونکہ میں نے ایسے بہت سے آدمی دیکھے ہیں جن کے حالات ان تین قسم کے انسانوں کے خلاف ہیں۔ پھر آپؐ نے فرمایا مجھے امید ہے کہ تم جنت والوں کا تہائی حصہ ہو گے۔ اس پر ہم نے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ پھر حضورؐ نے فرمایا تم جنت والوں میں سے آدھے ہو گے، ہم نے پھر ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ پھر آپؐ نے فرمایا مجھے امید ہے کہ تم جنت والوں کا چوتھائی حصہ ہو گے، اس پر ہم نے ",""],["ٱللَّٰه","a"],[" اکبر کہا۔ پھر حضورؐ نے یہ آیت پڑھی:",""]]],["q",[["ثُلَّةٌ مِّنَ ٱلْأَوَّلِينَ وَثُلَّةٌ مِّنَ ٱلْءَاخِرِينَ  (سورۃ الواقعہ: ۳۹-۴۰)","a"]]],["p",[["ترجمہ: \"(اصحاب الیمین) کا ایک بڑا گروہ اگلے لوگوں میں ہوگا اور ایک بڑا گروہ پچھلے لوگوں میں سے ہوگا۔\" حضرت عبد",""],["ٱللَّٰه","a"],["ؓ کہتے ہیں کہ ہم آپس میں یہ بات کرنے لگے کہ یہ ستر ہزار کون ہیں؟ ہم نے کہا یہ وہ لوگ ہیں جو اسلام میں پیدا ہوئے اور انہوں نے زندگی میں کبھی شرک نہیں کیا۔ ہوتے ہوتے یہ بات حضورؐ تک پہنچی تو آپؐ نے فرمایا نہیں، یہ وہ لوگ ہیں جو (علاج کے لیے) جسم پر داغ نہیں لگائیں گے اور کبھی منتر نہیں پڑھیں گے اور نہ کبھی بدفالی لیں گے اور اپنے رب پر توکل کریں گے۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abi Haatim, Ibn Jareer and several other reliable sources, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.293). In his Mustadrak (Vol.4 Pg.578), Haakim has reported a similar narration from reliable sources as confirmed by Dhahabi."]]},{"b":[["n",[["حضرت سلیم بن عامرؒ","b"],[" کہتے ہیں کہ حضورؐ کے صحابہؓ کہا کرتے تھے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ ہمیں دیہاتی لوگوں کے سوالات سے بڑا نفع پہنچاتے ہیں؛ چنانچہ ایک دن ایک دیہاتی آیا اور اس نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" تعالیٰ نے جنت میں ایک ایسے درخت کا ذکر کیا ہے جس سے انسان کو تکلیف ہوتی ہے۔ حضورؐ نے پوچھا وہ کونسا درخت ہے؟ اس نے کہا بیری کا درخت کیونکہ اس میں تکلیف دہ کانٹے ہوتے ہیں۔ حضورؐ نے فرمایا کیا ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ نہیں فرمایا:",""]]],["q",[["فِى سِدْرٍ مَّخْضُودٍ  (سورۃ الواقعہ: ۲۸)","a"]]],["p",[["ترجمہ: \"وہ ان باغوں میں ہوں گے جہاں بے خار بیریاں ہوں گی۔\" ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس کے کانٹے دور کر دیے ہیں اور ہر کانٹے کی جگہ پھل لگا دیا ہے۔ اس درخت میں ایسے پھل لگیں گے کہ ہر پھل میں بہتر قسم کے ذائقے ہوں گے اور ہر ذائقہ دوسرے سے مختلف ہوگا۔",""],[" (3)","s"]]]],"f":[["(3)","Ibn Najjaar."]]},{"b":[["n",[["حضرت عتبہ بن عبد سلمیؓ","b"],[" فرماتے ہیں کہ میں حضورؐ کے پاس بیٹھا ہوا تھا کہ اتنے میں ایک دیہاتی آدمی آیا۔ اس نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے آپؐ سے جنت میں ایک ایسے درخت کا ذکر سنا ہے کہ میرے خیال میں اس سے زیادہ کانٹے والا درخت اور کوئی نہیں ہوگا، یعنی ببول کا درخت۔ حضورؐ نے فرمایا ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے ہر کانٹے کی جگہ بھرے ہوئے گوشت والے بکرے کے خصیہ کے برابر پھل لگا دیں گے اور اس پھل میں بہتر قسم کے ذائقے ہوں گے۔ ہر ذائقہ دوسرے سے مختلف ہوگا۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Dawood, as quoted in Kanzul Ummaal (Vol.4 Pg.288)."]]},{"b":[["n",[["حضرت عتبہ بن عبد سلمیؓ","b"],[" فرماتے ہیں کہ ایک دیہاتی حضورؐ کی خدمت میں آیا اور اس نے حضورؐ سے حوض کے بارے میں پوچھا اور جنت کا تذکرہ کیا۔ پھر اس دیہاتی نے کہا کیا اس میں پھل بھی ہوں گے؟ حضورؐ نے فرمایا ہاں۔ اس میں ایک درخت ہے جسے طوبیٰ کہا جاتا ہے۔ راوی کہتے ہیں کہ حضورؐ نے کسی اور چیز کا بھی ذکر فرمایا لیکن مجھے معلوم نہ ہو سکا کہ وہ کیا چیز تھی۔ اس دیہاتی نے کہا ہمارے علاقے کے کس درخت کے مشابہ ہے؟ حضورؐ نے فرمایا تمہارے علاقے کے کسی درخت کے مشابہ نہیں۔ پھر حضورؐ نے فرمایا کیا تم شام گئے ہو؟ اس نے کہا نہیں۔ حضورؐ نے فرمایا وہ شام کے ایک درخت کے مشابہ ہے جسے اخروٹ کہا جاتا ہے۔ وہ ایک تنے پر ہوتا ہے اور اس کی اوپر والی شاخیں پھیلی ہوئی ہوتی ہیں۔ پھر اس دیہاتی نے کہا گچھا کتنا بڑا ہوگا؟ حضورؐ نے فرمایا سیاہ و سفید داغوں والا کوا بغیر رکے ایک مہینہ مسلسل اڑ کر جتنا فاصلہ طے کرتا ہے وہ گچھا اس فاصلے کے برابر ہوگا۔ پھر اس دیہاتی نے کہا اس درخت کی جڑ کتنی موٹی ہوگی؟ آپؐ نے فرمایا تمہارے گھر والوں کے اونٹوں میں سے ایک جوان اونٹ چلنا شروع کرے اور چلتے چلتے بوڑھا ہو جائے اور بڑھاپے کی وجہ سے اس کی پسلی کی ہڈی ٹوٹ جائے پھر بھی وہ اس کی جڑ کا ایک چکر نہیں لگا سکے گا۔ پھر اس دیہاتی نے پوچھا کیا جنت میں انگور ہوں گے؟ حضورؐ نے فرمایا ہاں! اس نے پوچھا انگور کا دانہ کتنا بڑا ہوگا؟ حضورؐ نے فرمایا کیا تیرے باپ نے کبھی اپنی بکریوں میں سے بڑا بکرا ذبح کیا ہے؟ اس نے کہا جی کیا ہے۔ حضورؐ نے فرمایا پھر اس نے اس کی کھال اتار کر تیری ماں کو دے دی اور اس سے کہا ہو کہ اس کھال کو ہمارے لیے ڈول بنا دو؟ اس دیہاتی نے کہا جی ہاں۔ (حضورؐ نے فرمایا وہ دانہ اس ڈول کے برابر ہوگا۔) پھر دیہاتی نے کہا (جب وہ دانہ ڈول کے برابر ہوگا) تو پھر ایک دانے سے میرا اور میرے گھر والوں کا پیٹ بھر جائے گا۔ حضورؐ نے فرمایا ہاں، بلکہ تیرے سارے خاندان کا پیٹ بھر جائے گا۔",""],[" (5)","s"]]]],"f":[["(5)","Ahmad, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.290)."]]},{"b":[["n",[["حضرت ابن عمرؓ","b"],[" فرماتے ہیں کہ حبشہ کا ایک آدمی حضورؐ کے پاس آیا۔ حضورؐ نے فرمایا جو چاہو پوچھو۔ اس نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! آپ کو شکل و صورت، رنگ اور نبوت کی وجہ سے ہم پر فضیلت حاصل ہے، ذرا بتائیں کہ اگر میں ان چیزوں پر ایمان لے آؤں جن پر آپ ایمان لائے ہیں اور وہ تمام عمل کروں جو آپ کر رہے ہیں تو کیا میں بھی جنت میں آپ کے ساتھ ہو سکتا ہوں؟ حضورؐ نے فرمایا:",""]]],["c",[["بالکل ضرور۔ اس ذات کی قسم جس کے قبضے میں میری جان ہے! کالے حبشی کی سفیدی جنت میں ہزار سال کی مسافت سے نظر آئے گی۔",""]]],["p",[["پھر حضورؐ نے فرمایا جو آدمی ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہے وہ ",""],["ٱللَّٰه","a"],[" کی ذمہ داری میں آ جاتا ہے اور جو سبحان ",""],["ٱللَّٰه","a"],[" و بحمدہ کہے اس کے لیے ایک لاکھ چوبیس ہزار نیکیاں لکھی جاتی ہیں۔ اس پر ایک آدمی نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! اس کے بعد ہم کیسے ہلاک ہوں گے؟ حضورؐ نے فرمایا قیامت کے دن ایک آدمی اتنے اعمال لے کر آئے گا کہ اگر وہ اعمال کسی پہاڑ پر رکھ دیے جائیں تو پہاڑ کو بھاری لگیں۔ پھر ان اعمال پھر حضورؐ نے وہ آیتیں پڑھ کر سنائیں: کے مقابلے میں ",""],["ٱللَّٰه","a"],[" کی نعمتیں آئیں گی اور وہ ان سارے اعمال کو ختم کرنے کے قریب ہوں گی؛ البتہ اگر ",""],["ٱللَّٰه","a"],[" اسے اپنی رحمت سے ڈھانپ لے تو اس کے اعمال بچ سکیں گے۔ اور جب یہ سورت نازل ہوئی:",""]]],["q",[["هَلْ أَتَىٰ عَلَى ٱلْإِنسَٰنِ حِينٌ مِّنَ ٱلدَّهْرِ لَمْ يَكُن شَيْـًٔا مَّذْكُورًا ... مُلْكًا كَبِيرًا  (سورۃ الدھر: ۱-۲۰)","a"],[" (6)","s"]]],["p",[["ترجمہ: \"بے شک انسان پر زمانہ میں ایک وقت ایسا بھی آ چکا ہے جس میں وہ کوئی چیز قابل تذکرہ نہ تھا (یعنی انسان نہ تھا بلکہ نطفہ تھا)\"، تو اس حبشی نے کہا میری آنکھیں بھی وہ سب کچھ جنت میں دیکھیں گی جو آپؐ کی آنکھیں دیکھیں گی؟ حضورؐ نے فرمایا ہاں! یہ سن کر (خوشی کے مارے) وہ رونے لگا اور اتنا رویا کہ اس کی جان نکل گئی۔ حضرت ابن عمرؓ فرماتے ہیں کہ میں نے دیکھا کہ حضورؐ اپنے ہاتھ سے اسے قبر میں اتار رہے تھے۔",""],[" (7)","s"]]]],"f":[["(6)","Ahmad, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.290)."],["(7)","Tabraani, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.457)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن وہبؒ","b"],[" کہتے ہیں کہ حضرت ابن زیدؓ نے ہمیں بتایا کہ جب حضورؐ پر یہ سورت نازل ہوئی: ھَلْ أَتَىٰ عَلَى ٱلْإِنسَٰنِ حِينٌ مِّنَ ٱلدَّهْرِ، تو اس وقت آپؐ کے پاس ایک کالا آدمی بیٹھا ہوا تھا۔ حضورؐ نے یہ سورت پڑھ کر سنائی، جب حضورؐ اس سورت میں جنت کی نعمتوں کے ذکر پر پہنچے تو اس نے ایک لمبا سانس زور سے لیا اور اس کی جان نکل گئی۔ حضورؐ نے فرمایا:",""]]],["c",[["جنت کے شوق نے تمہارے ساتھی اور بھائی کی جان لے لی۔",""],[" (8)","s"]]]],"f":[["(8)","Ibn Katheer, Tafseer (Vol.4 Pg.453)."]]},{"b":[["n",[["حضرت ابومطرؒ","b"],[" کہتے ہیں کہ میں نے حضرت علیؓ کو فرماتے ہوئے سنا کہ جب حضرت عمر بن خطابؓ کو ابولولو نے زخمی کیا تو میں ان کے پاس گیا، وہ رو رہے تھے۔ میں نے کہا اے امیر المومنین! آپ کیوں رو رہے ہیں؟ حضرت عمرؓ نے فرمایا میں آسمان کے فیصلے کی وجہ سے رو رہا ہوں۔ مجھے معلوم نہیں کہ مجھے جنت میں لے جایا جائے گا یا جہنم میں؟ میں نے ان سے کہا آپ کو جنت کی بشارت ہو کیونکہ میں نے حضورؐ کو بے شمار دفعہ فرماتے ہوئے سنا ہے کہ ابوبکرؓ و عمرؓ جنت کے بڑی عمر کے لوگوں کے سردار ہیں اور دونوں بہت عمدہ آدمی ہیں۔ حضرت عمرؓ نے فرمایا اے علی! کیا تم میرے جنتی ہونے کے گواہ ہو؟ میں نے کہا جی ہاں، اور اے حسن! تم اپنے باپ کے گواہ رہنا کہ حضورؐ نے فرمایا کہ عمرؓ جنت والوں میں سے ہے۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.438)."]]},{"b":[["n",[["حضرت عمرؓ کے زہد کے باب میں یہ گزر چکا ہے کہ انہوں نے اپنی ایک ضیافت کے موقع پر فرمایا کہ ہمیں تو یہ کھانا مل گیا لیکن وہ مسلمان فقراء جن کا اس حال میں انتقال ہوا کہ ان کو پیٹ بھر جو کی روٹی بھی نہ ملتی تھی ان کو کیا ملے گا؟ حضرت عمر بن ولیدؓ نے کہا انہیں جنت ملے گی۔ یہ سن کر حضرت عمرؓ کی آنکھیں ڈبڈبا آئیں اور فرمایا اگر ہمارے حصے میں دنیا کا یہ مال و متاع ہے اور وہ جنت لے جائیں تو وہ ہم سے بہت آگے نکل گئے اور بڑی فضیلت حاصل کر لی۔",""],[" (10)","s"]]]],"f":[["(10)","Under the subheading \"His Abstinence in Eating\"."]]},{"b":[["n",[["حضرت مصعب بن سعدؒ","b"],[" کہتے ہیں کہ جب میرے والد (حضرت سعد بن ابی وقاصؓ) کی جان نکل رہی تھی، ان کا سر میری گود میں تھا، میری آنکھوں میں آنسو آ گئے۔ انہوں نے میری طرف دیکھا اور فرمایا اے میرے بیٹے! کیوں روتے ہو؟ میں نے کہا آپ کے مقام کی وجہ سے اور آپ کو مرتے ہوئے دیکھ کر رو رہا ہوں۔ میرے والد نے کہا مجھ پر مت روئیں کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ مجھے کبھی عذاب نہیں دیں گے اور میں یقیناً جنت والوں میں سے ہوں۔ اور مومن بندے جب تک ",""],["ٱللَّٰه","a"],[" کے لیے عمل کریں گے ",""],["ٱللَّٰه","a"],[" ان کی نیکیوں کا بدلہ دے گا اور کفار کی نیکیوں کی وجہ سے ان کے عذاب میں تخفیف ہوگی، اور جب وہ عمل ختم ہو جائیں گے جو انہوں نے ",""],["ٱللَّٰه","a"],[" کے لیے کیے تھے تو ان سے کہا جائے گا کہ جس کے لیے عمل کیا تھا ہر ایک اس کا ثواب بھی اسی سے لے لے۔",""],[" (11)","s"]]]],"f":[["(11)","Ibn Sa'd (Vol.3 Pg.147)."]]},{"b":[["n",[["حضرت ابن شماسہ مہریؒ","b"],[" کہتے ہیں کہ ہم لوگ حضرت عمرو بن عاصؓ کی خدمت میں گئے، ان کی جان نکل رہی تھی۔ انہوں نے اپنا چہرہ دیوار کی طرف پھیر لیا اور کافی دیر تک روتے رہے۔ ان کا بیٹا انہیں کہتا رہا آپ کیوں رو رہے ہیں؟ کیا آپ کو حضورؐ نے یہ اور یہ بشارت نہیں دی؟ لیکن وہ دیوار کی طرف منہ کر کے روتے رہے، پھر ہماری طرف منہ کر کے فرمایا ",""],["تم جو میرے فضائل شمار کر رہے ہو ان سب سے افضل تو کلمہ شہادت","h"],[" اشھد ان ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" واشھد ان محمدا رسول ",""],["ٱللَّٰه","a"],[" ہے۔ لیکن میری زندگی کے تین دور ہیں جن میں پہلا دور تو وہ ہے کہ مجھے اس زمانے میں حضورؐ سے زیادہ مبغوض کوئی نہیں تھا اور حضورؐ پر قابو پا کر قتل کر دینے سے زیادہ محبوب اور کوئی کام نہیں تھا، اگر میں اس حال میں مر جاتا تو میں جہنم والوں میں سے ہوتا۔ پھر ",""],["ٱللَّٰه","a"],[" نے میرے دل میں اسلام کی حقانیت ڈال دی اور میں بیعت ہونے کے لیے حضورؐ کی خدمت میں حاضر ہوا اور میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ اپنا دایاں ہاتھ بڑھائیں تاکہ میں آپؐ سے بیعت ہو جاؤں۔ حضورؐ نے اپنا دست مبارک بڑھا دیا۔ میں نے اپنا ہاتھ پیچھے کر لیا۔ حضورؐ نے فرمایا اے عمرو! تمہیں کیا ہوا؟ میں نے کہا میں کچھ شرط لگانا چاہتا ہوں۔ حضورؐ نے فرمایا کیا شرط لگانا چاہتے ہو؟ میں نے کہا یہ شرط لگانا چاہتا ہوں کہ میری مغفرت ہو جائے۔ حضورؐ نے فرمایا:",""]]],["c",[["اے عمرو! کیا تم نہیں جانتے کہ اسلام اپنے سے پہلے کے گناہوں کو مٹا دیتا ہے اور ہجرت کرنے سے بھی پہلے کے تمام گناہ معاف ہو جاتے ہیں اور حج کرنے سے بھی پہلے کے تمام گناہ معاف ہو جاتے ہیں۔",""]]],["p",[["پھر میرا یہ حال ہو گیا کہ حضورؐ سے زیادہ مجھے کوئی محبوب نہیں تھا اور میری نگاہ میں حضورؐ سے زیادہ اور کوئی عظمت والا نہیں تھا۔ اگر کوئی مجھ سے کہتا کہ حضورؐ کا حلیہ بیان کرو تو میں بیان نہیں کر سکتا کیونکہ میں حضورؐ کی عظمت اور ہیبت کی وجہ سے آپؐ کو آنکھ بھر کر دیکھ نہیں سکتا تھا۔ اگر میں اس حالت پر مرتا تو مجھے یقین تھا کہ میں جنت والوں میں سے ہوتا۔ اس کے بعد ہمیں بہت سے کام کرنے پڑے۔ اب مجھے معلوم نہیں کہ ان کاموں کے کرنے کے بعد میرا کیا حال ہوگا؟ لہٰذا جب میں مر جاؤں تو میرے جنازے کے ساتھ نہ کوئی نوحہ کرنے والی عورت جائے اور نہ آگ۔ اور جب تم مجھے دفن کرو تو میرے اوپر اچھی طرح مٹی ڈالنا اور دفن کر کے میری قبر کے پاس اتنی دیر ٹھہرے رہنا جتنی دیر میں اونٹ کو ذبح کر کے اس کا گوشت تقسیم کر دیا جاتا ہے۔ تم لوگوں کے قریب ہونے سے مجھے انس رہے گا یہاں تک کہ مجھے پتہ چل جائے گا کہ میں اپنے رب کے قاصدوں کے سوالوں کا کیا جواب دیتا ہوں۔",""],[" (12)","s"]]]],"f":[["(12)","Ibn Sa'd (Vol.4 Pg.258). Muslim (Vol.1 Pg.76) has reported a similar narration."]]},{"b":[["n",[["حضرت عبدالرحمن بن شماسہؒ","b"],[" کہتے ہیں کہ جب حضرت عمرو بن عاصؓ کی وفات کا وقت قریب آیا تو وہ رونے لگے۔ ان سے ان کے بیٹے حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے کہا آپ کیوں رو رہے ہیں؟ کیا آپ موت سے گھبرا رہے ہیں؟ حضرت عمروؓ نے کہا نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! (موت کی وجہ سے نہیں رو رہا ہوں) بلکہ موت کے بعد جو حالات آنے والے ہیں ان کی وجہ سے رو رہا ہوں۔ حضرت عبد",""],["ٱللَّٰه","a"],["ؓ نے ان سے کہا آپ نے تو خیر کا زمانہ گزارا ہے، پھر حضرت عبد",""],["ٱللَّٰه","a"],["ؓ انہیں یاد دلانے لگے کہ آپ حضورؐ کے ساتھ رہے ہیں، آپ نے شام میں بڑی فتوحات حاصل کی ہیں۔ حضرت عمروؓ نے فرمایا تم نے ان سب سے افضل چیز کو تو چھوڑ دیا اور وہ ہے کلمہ شہادت اشھد ان ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],["۔ پھر آگے حدیث کو مختصر کر کے ذکر کیا اور اس کے آخر میں یہ مضمون ہے کہ جب میں مر جاؤں تو کوئی عورت مجھ پر بین نہ کرے اور نہ کوئی تعریف کرنے والا جنازے کے ساتھ جائے اور نہ (جاہلیت کے دستور کے مطابق) میرے جنازے کے ساتھ آگ ہو۔ اب میری لنگی اچھی طرح مضبوطی سے باندھ دو کیونکہ (جان نکالتے وقت) فرشتے مجھ سے جھگڑا کریں گے (کہ کہیں اس حالت میں ستر نہ کھل جائے)۔ اور میرے اوپر دونوں طرف اچھی طرح مٹی ڈالنا کیونکہ میرا دایاں پہلو بائیں پہلو سے زیادہ مٹی کا حقدار نہیں ہے اور میری قبر میں کوئی لکڑی اور پتھر استعمال نہ کرنا (تاکہ قبر شاندار نہ بنے)۔",""],[" (13)","s"]]],["p",[["ایک روایت میں یہ ہے کہ اس کے بعد حضرت عمروؓ نے اپنا چہرہ دیوار کی طرف پھیر لیا اور کہنے لگے اے ",""],["ٱللَّٰه","a"],["! تو نے ہمیں بہت سے حکم دیے لیکن ہم نے تیری نافرمانی کی اور تو نے ہمیں بہت سے کاموں سے روکا لیکن ہم باز نہ آئے، اب ہمیں تیری مغفرت کے سوا کچھ نہیں چاہیے۔ اور ایک روایت میں یہ ہے کہ انہوں نے اپنا ہاتھ اپنے گلے پر اس طرح رکھا جیسے کہ گلے میں طوق ڈالا جاتا ہے، پھر آسمان کی طرف سر اٹھا کر کہا اے ",""],["ٱللَّٰه","a"],["! میں طاقتور بھی نہیں کہ بدلہ لے سکوں اور نہ بے قصور ہوں کہ عذر پیش کر سکوں اور نہ ہی مجھے اپنی غلطیوں اور گناہوں سے انکار ہے۔ بلکہ میں تو استغفار کرتا ہوں، لا الٰہ الا انت۔ وہ یہ کلمات بار بار کہتے رہے یہاں تک کہ ان کا انتقال ہو گیا۔",""],[" (14)","s"]]],["p",[["ابن سعد کی روایت کے آخر میں یہ الفاظ ہیں کہ پھر حضرت عمروؓ نے کہا اے ",""],["ٱللَّٰه","a"],["! تو نے ہمیں بہت سے حکم دیے جنہیں ہم نے پورا نہ کیا اور تو نے ہمیں برے کاموں سے روکا لیکن ہم نے اپنے آپ کو ضائع کر دیا۔ تو میں بے قصور نہیں ہوں کہ عذر پیش کروں اور نہ ایسا زور دار ہوں کہ بدلہ لے سکوں، ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],["۔ انتقال تک ان ہی کلمات کو دہراتے رہے۔",""],[" (15)","s"]]]],"f":[["(13)","Ahmad, as quoted in Al Bidaayah wan Nihaayah (Vol.8 Pg.26)."],["(14)","Muslim."],["(15)","Ibn Sa'd (Vol.4 Pg.260)."]]},{"b":[["n",[["نصرت کے باب میں یہ گزر چکا ہے کہ نبی کریم ",""],["ﷺ","a"],[" نے ",""],["انصار","b"],[" سے فرمایا تمہارے اوپر جو ہماری نصرت کا حق تھا وہ تم نے پورا پورا ادا کر دیا۔ اب اگر تم چاہو تو خیبر کا اپنا حصہ خوشی خوشی مہاجرین کو دے دو اور (مدینہ کے باغات کے) سارے پھل خود کھایا کرو (اور مہاجرین کو اب ان میں سے کچھ نہ دیا کرو؛ یوں مدینہ کا سارا پھل تمہارا اور خیبر کا سارا پھل مہاجرین کا ہو جائے گا)۔ انصار نے کہا (ہمیں منظور ہے)۔ آپؐ نے ہمارے ذمہ اپنے کئی کام لگائے تھے، وہ ہم نے سارے کر دیے۔ اب ہم چاہتے ہیں کہ ہماری چیز ہمیں مل جائے۔ حضورؐ نے فرمایا:",""]]],["c",[["وہ جنت تمہیں ضرور ملے گی۔",""]]],["p",[["اسے بزار نے روایت کیا ہے۔",""],[" (16)","s"]]]],"f":[["(16)","Under the heading \"The Financial Assistance that the Ansaar gave to the Muhaajireen\" and the subheading \"Sharing Dates and an Ansaari Refuses to be Paid Back\"."]]},{"b":[["n",[["جہاد کے باب میں یہ گزر چکا ہے کہ بدر کے دن حضورؐ نے لڑنے کے لیے ابھارا تو ",""],["حضرت عمیرؓ","b"],[" نے کہا واہ واہ! کیا میرے اور جنت میں داخل ہونے کے درمیان صرف یہی چیز حائل ہے کہ یہ (کافر) لوگ مجھے قتل کر دیں؟ یہ کہہ کر کھجوریں ہاتھ سے پھینک دیں اور تلوار لے کر کافروں سے لڑنا شروع کیا یہاں تک کہ شہید ہو گئے۔ دوسری روایت میں یہ ہے کہ حضورؐ نے فرمایا تم واہ واہ کیوں کہہ رہے ہو؟ انہوں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ",""],["ٱللَّٰه","a"],[" کی قسم! صرف اس امید پر کہہ رہا ہوں کہ میں بھی جنت والوں میں سے ہو جاؤں۔ آپؐ نے فرمایا تم جنت والوں میں سے ہو۔ پھر وہ اپنی جھولی میں سے کھجوریں نکال کر کھانے لگے۔ پھر کہنے لگے ان کھجوروں کے کھانے تک میں زندہ رہوں تو یہ بڑی لمبی زندگی ہے، یہ کہہ کر ان کھجوروں کو پھینک دیا اور شہید ہونے تک کافروں سے لڑتے رہے۔ اس حدیث کو امام احمد وغیرہ نے حضرت انسؓ سے روایت کیا ہے۔",""],[" (17)","s"]]]],"f":[["(17)","Under the heading \"Rasulullaah Encourages Striving in the path of Allaah and Spending One's Wealth for this Cause\" and the subheading \"Rasulullaah gives Encouragement before Battle and the Statement of Hadhrat Umayr bin Hamaam\"."]]},{"b":[["n",[["اور جہاد کے باب میں زخمی ہونے کے عنوان میں یہ گزر چکا ہے کہ ",""],["حضرت انس بن نضرؓ","b"],[" نے کہا واہ واہ! جنت کی خوشبو دار ہوا کیا ہی عمدہ ہے جو مجھے احد پہاڑ کے پیچھے سے آ رہی ہے۔ پھر انہوں نے کافروں سے جنگ شروع کر دی یہاں تک کہ شہید ہو گئے۔ اور صحابہ کرامؓ کے ",""],["ٱللَّٰه","a"],[" کے راستے میں شہید ہونے کے شوق میں یہ گزر چکا ہے کہ جب ",""],["حضرت سعد بن خیثمہؓ","b"],[" سے ان کے والد نے کہا اب ہم دونوں میں سے ایک کا یہاں رہنا ضروری ہو گیا ہے تو حضرت سعدؓ نے کہا اگر جنت کے علاوہ کوئی اور چیز ہوتی تو میں (حضورؐ کے ساتھ جانے میں) آپؐ کو اپنے سے آگے رکھتا۔ میں اپنے اس سفر میں شہادت کی امید لگائے ہوئے ہوں۔",""],[" (18)","s"],[" (19)","s"]]]],"f":[["(18)","Under the heading \"Enduring Injuries while in Jihaad in the path of Allaah\" and the subheading \"The Injury of Hadhrat Anas bin Nadhr\"."],["(19)","Under the heading \"The Enthusiasm of the Sahabah to Die and Give their Lives in the path of Allaah\" and the subheading \"The Incident of Hadhrat Khaythama and his son\"."]]},{"b":[["n",[["اور ",""],["حضرت سعد بن ربیعؓ","b"],[" کا قصہ بھی گزر چکا ہے کہ جب حضرت زید بن ثابتؓ نے ان سے کہا کہ ",""],["ٱللَّٰه","a"],[" کے رسولؐ سلام کہتے ہیں اور تم سے پوچھتے ہیں کہ بتاؤ تم اپنے آپ کو کیسا پا رہے ہو؟ تو حضرت سعدؓ نے ان سے کہا تم حضورؐ سے کہہ دینا کہ یا رسول ",""],["ٱللَّٰه","a"],["! میرا حال یہ ہے کہ میں جنت کی خوشبو پا رہا ہوں۔",""],[" (20)","s"]]]],"f":[["(20)","Also under the heading \"The Enthusiasm of the Sahabah to Die and Give their Lives in the path of Allaah\", under the subheading \"The Incident of Hadhrat Sa'd bin Rabee\"."]]},{"b":[["n",[["اور یہ بھی گزر چکا ہے کہ غزوہ بئر معونہ کے دن ",""],["حضرت حرام بن ملحانؓ","b"],[" نے کہا تھا کہ رب کعبہ کی قسم! میں کامیاب ہو گیا، یعنی جنت ملنے کی کامیابی مل گئی۔",""],[" (21)","s"]]]],"f":[["(21)","Also under the heading \"The Enthusiasm of the Sahabah to Die and Give their Lives in the path of Allaah\", under the subheading \"The Last Words of Hadhrat Haraam Because of which his Killer Accepted Islaam\"."]]},{"b":[["n",[["اور ",""],["حضرت عمار بن یاسرؓ","b"],[" کی بہادری کے عنوان میں یہ گزر چکا ہے کہ حضرت عمارؓ نے کہا اے ہاشم! آگے بڑھو، جنت تلواروں کے سائے کے نیچے ہے اور موت نیزوں کے کناروں پر ہے۔ جنت کے دروازے کھولے جا چکے ہیں اور بڑی آنکھوں والی حوریں آراستہ ہو چکی ہیں۔ آج میں اپنے محبوب دوستوں حضرت محمدؐ اور ان کی جماعت سے ملوں گا۔ پھر حضرت عمارؓ اور حضرت ہاشمؓ دونوں نے زور دار حملہ کیا اور دونوں شہید ہو گئے۔ اور حضرت عمارؓ کی بہادری کے عنوان میں یہ بھی گزر چکا ہے کہ حضرت عمارؓ نے کہا اے مسلمانو! کیا تم جنت سے بھاگ رہے ہو؟ میں عمار بن یاسر ہوں، میری طرف آؤ۔",""],[" (22)","s"],[" (23)","s"]]]],"f":[["(22)","Under the subheading \"His Desire for Jannah as he Fought\"."],["(23)","Under the subheading \"He Lends Courage to the Muslims and Fights Bravely During the Battle of Yamaamah\"."]]},{"b":[["n",[["اور امارت قبول کرنے سے انکار کرنے کے باب میں یہ گزر چکا ہے کہ ",""],["حضرت ابن عمرؓ","b"],[" نے فرمایا کہ اس سے پہلے بھی میرے دل میں دنیا کا خیال نہیں آیا تھا، میں نے سوچا کہ ان سے جا کر یہ کہوں کہ اس خلافت کی امید و طمع وہ آدمی کر رہا ہے جس نے آپ کو اور آپ کے باپ کو اسلام کی وجہ سے مارا تھا اور (مار مار کر) تم دونوں کو اسلام میں داخل کیا تھا (اس سے حضرت ابن عمرؓ اپنی ذات مراد لے رہے ہیں)؛ لیکن پھر مجھے جنتیں اور نعمتیں یاد آ گئیں تو میں نے ان سے یہ بات کہنے کا ارادہ چھوڑ دیا۔ حضرت ابن عمرؓ نے یہ بات اس وقت کہی تھی جب دومۃ الجندل میں حضرت معاویہؓ نے کہا کون خلافت کی طمع اور امید رکھتا ہے؟",""],[" (24)","s"]]]],"f":[["(24)","Under the subheading \"The Incident that Occurred Between Hadhrat Abdullaah bin Umar and Ummul Mu'mineen Hadhrat Hafsah Concerning Dowmatul Jandal\"."]]},{"b":[["n",[["اور ",""],["حضرت سعید بن عامرؓ","b"],[" کا قصہ پہلے گزر چکا ہے کہ جب انہوں نے صدقہ کیا تو کچھ لوگوں نے ان سے کہا کہ آپ کے گھر والوں کا بھی آپ پر حق ہے، آپ کے سوال والوں کا بھی آپ پر حق ہے، تو حضرت سعیدؓ نے کہا میں نے ان کے حقوق کی ادائیگی میں کبھی کسی کو ان پر ترجیح نہیں دی۔ میں موٹی آنکھوں والی حوریں حاصل کرنا چاہتا ہوں، تو اس لیے میں کسی بھی انسان کو اس طرح خوش نہیں کرنا چاہتا کہ اس سے حوروں کے ملنے میں کمی آ جائے، کیونکہ اگر جنت کی ایک بھی حور آسمان سے جھانک لے تو اس کی وجہ سے ساری زمین ایسے چمکنے لگے گی جیسے سورج چمکتا ہے۔ دوسری روایت میں یہ آیا ہے کہ حضرت سعیدؓ نے اپنی بیوی سے کہا ایسے ہی آرام سے بیٹھی رہو، میرے کچھ ساتھی تھے جو تھوڑا عرصہ پہلے مجھ سے جدا ہو گئے (اس دنیا سے چلے گئے)۔ اگر مجھے ساری دنیا بھی مل جائے تو بھی مجھے ان کا راستہ چھوڑنا پسند نہیں ہے۔ اگر جنت کی خوبصورت حوروں میں سے ایک حور آسمان دنیا سے جھانک لے تو ساری زمین اس کے نور سے روشن ہو جائے اور اس کے چہرے کا نور چاند سورج کی روشنی پر غالب آ جائے اور جو دوپٹہ اسے پہنایا جاتا ہے وہ دنیا و مافیہا سے زیادہ قیمتی ہے۔ اب میرے لیے یہ تو آسان ہے کہ ان حوروں کی خاطر تجھے چھوڑ دوں لیکن تیری خاطر ان کو نہیں چھوڑ سکتا۔ یہ سن کر وہ نرم پڑ گئی اور راضی ہو گئی۔",""],[" (25)","s"]]]],"f":[["(25)","In the chapter discussing how the Sahabah spent in the path of Allaah, under the heading \"The Spending of Hadhrat Sa'eed bin Aamir bin Judhaym Jumhi\" and the subheading \"His Spending as the Governor of Shaam\"."]]},{"b":[["n",[["بیماریوں پر صبر کرنے کے باب میں یہ قصہ گزر چکا ہے کہ جب حضورؐ نے ایک ",""],["انصاری عورت","b"],[" سے یہ فرمایا کہ تمہیں ان دو باتوں میں سے کونسی بات پسند ہے؟ ایک یہ کہ میں تمہارے لیے دعا کروں اور تمہارا بخار چلا جائے، دوسری یہ کہ تم صبر کرو اور تمہارے لیے جنت واجب ہو جائے۔ تو اس انصاری عورت نے تین دفعہ کہا ",""],["ٱللَّٰه","a"],[" کی قسم! یا رسول ",""],["ٱللَّٰه","a"],["! میں صبر کروں گی، اور پھر کہا میں ",""],["ٱللَّٰه","a"],[" کی جنت کو خطرے میں نہیں ڈال سکتی۔",""]]]],"f":[]},{"b":[["n",[["اور ",""],["حضرت ابوالدرداءؓ","b"],[" کا قصہ بھی گزر چکا ہے کہ جب وہ بیمار ہوئے تو ان کے ساتھیوں نے ان کو کہا آپ کیا چاہتے ہیں؟ حضرت ابوالدرداءؓ نے کہا میں جنت چاہتا ہوں۔",""],[" (26)","s"]]]],"f":[["(26)","Under the heading \"The Sahabah Exercise Patience with Illness\" and the subheading \"The Patience of Hadhrat Abu Bakr and Hadhrat Abu Dardaa\"."]]},{"b":[["n",[["اور اولاد کے مرنے پر صبر کرنے کے باب میں ",""],["حضرت ام حارثہؓ","b"],[" کا قصہ گزر چکا ہے کہ جب ان کا بیٹا حضرت حارثہؓ بدر کے دن شہید ہوا تو انہوں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! آپؐ مجھے بتائیں حارثہ کہاں ہے؟ اگر وہ جنت میں ہے تو میں صبر کروں گی ورنہ ",""],["ٱللَّٰه","a"],[" تعالیٰ بھی دیکھ لیں گے کہ میں کیا کرتی ہوں، یعنی کتنا نوحہ کرتی ہوں۔ اس وقت تک نوحہ کرنا حرام نہیں ہوا تھا۔ دوسری روایت میں یہ ہے کہ حضرت ام حارثہؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! اگر میرا بیٹا جنت میں ہے تو میں نہ روؤں گی اور نہ غم کا اظہار کروں گی اور اگر وہ جہنم میں ہے تو میں جب تک دنیا میں زندہ رہوں گی روتی رہوں گی۔ حضورؐ نے فرمایا:",""]]],["c",[["اے ام حارثہ! وہاں ایک جنت نہیں ہے بلکہ کئی جنتیں ہیں اور (تمہارا بیٹا) حارث (پیار کی وجہ سے حارثہ کی جگہ حارث فرمایا) تو فردوس اعلیٰ میں ہے۔",""]]],["p",[["اس پر وہ ہنستی ہوئی واپس چلی گئیں اور کہہ رہی تھیں واہ واہ! اے حارث تیرے کیا کہنے!",""]]]],"f":[]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ ایک مرتبہ میں جہنم کو یاد کر کے رونے لگی۔ حضورؐ نے فرمایا اے عائشہ! تمہیں کیا ہوا؟ میں نے کہا میں جہنم کو یاد کر کے رو رہی ہوں۔ کیا آپؐ قیامت کے دن اپنے گھر والوں کو یاد رکھیں گے؟ حضورؐ نے فرمایا:",""]]],["c",[["تین جگہوں پر کوئی کسی کو یاد نہیں رکھے گا: ایک تو اعمال کے ترازو کے پاس جب تک یہ نہ معلوم ہو جائے کہ اس کا ترازو (نیک اعمال کی وجہ سے) ہلکا ہوگا یا (گناہوں کی وجہ سے) بھاری۔ دوسرے اعمال نامے ملنے کے وقت، جسے دائیں ہاتھ میں ملے گا وہ کہے گا لو میرا اعمال نامہ پڑھ لو یہاں تک کہ اسے یہ معلوم ہو جائے کہ اعمال نامہ اس کے دائیں ہاتھ میں آئے گا یا بائیں میں اور (سامنے سے ملے گا) یا پشت کے پیچھے سے۔ تیسرے پل صراط کے پاس، جب پل صراط جہنم کی پشت پر رکھا جائے گا اس کے دونوں کناروں پر بہت سارے آنکڑے اور کانٹے ہوں گے۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ اپنی مخلوق میں سے جسے چاہیں گے ان آنکڑوں اور کانٹوں میں پھنسا کر روک لیں گے یہاں تک کہ یہ معلوم ہو جائے کہ اس نے نجات پائی ہے یا نہیں۔",""],[" (27)","s"]]]],"f":[["(27)","Haakim (Vol.4 Pg.578). Dhahabi has commented on the chain of narrators."]]},{"b":[["n",[["حضرت عبدالعزیز بن ابی رواد","b"],[" کہتے ہیں کہ مجھے یہ روایت پہنچی ہے کہ حضورؐ نے یہ آیت پڑھی:",""]]],["q",[["يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ قُوٓا۟ أَنفُسَكُمْ وَأَهْلِيكُمْ نَارًا وَقُودُهَا ٱلنَّاسُ وَٱلْحِجَارَةُ  (سورۃ التحریم: ۶)","a"]]],["p",[["ترجمہ: \"اے ایمان والو! تم اپنے آپ کو اور اپنے گھر والوں کو (دوزخ کی) اس آگ سے بچاؤ جس کا ایندھن (اور سوختہ) آدمی اور پتھر ہیں۔\" اس وقت حضورؐ کے پاس کچھ صحابہؓ بیٹھے ہوئے تھے، ان میں ایک بڑے میاں بھی تھے۔ بڑے میاں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! جہنم کے پتھر دنیا کے پتھر جیسے ہوں گے؟ حضورؐ نے فرمایا اس ذات کی قسم جس کے قبضے میں میری جان ہے! جہنم کی چٹانوں میں سے ایک چٹان دنیا کے تمام پہاڑوں سے زیادہ بڑی ہے۔ یہ سن کر وہ بڑے میاں بے ہوش ہو کر گر پڑے۔ حضورؐ نے اس کے دل پر ہاتھ رکھا تو وہ زندہ تھا۔ حضورؐ نے اسے پکار کر کہا اے بڑے میاں! ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" پڑھو۔ اس نے کلمہ پڑھا، حضورؐ نے اسے جنت کی بشارت دی۔ حضورؐ کے صحابہؓ نے کہا یہ بشارت ہم میں سے صرف اسی کے لیے ہے؟ حضورؐ نے فرمایا ہاں، ",""],["ٱللَّٰه","a"],[" تعالیٰ فرماتے ہیں:",""]]],["q",[["ذَٰلِكَ لِمَنْ خَافَ مَقَامِى وَخَافَ وَعِيدِ  (سورۃ ابراہیم: ۱۴)","a"]]],["p",[["ترجمہ: \"یہ ہر اس شخص (عام) کے لیے ہے جو میرے رو برو کھڑا ہونے سے ڈرے اور میری وعید سے ڈرے۔\"",""]]],["p",[["حاکم کی ایک روایت میں بڑے میاں کے بجائے ایک نوجوان کے بے ہوش ہو کر گرنے کا ذکر ہے۔ ",""],["ٱللَّٰه","a"],[" سے ڈرنے کے باب میں یہ قصہ گزر چکا ہے کہ ایک انصاری نوجوان کے دل میں ",""],["ٱللَّٰه","a"],[" کا ڈر اتنا زیادہ بیٹھ گیا تھا کہ جب بھی اس کے سامنے جہنم کا ذکر ہوتا تو وہ رونے لگ جاتا۔ اور اس کیفیت کے غلبے کی وجہ سے وہ ہر وقت گھر ہی رہنے لگا، باہر نکلنا چھوڑ دیا۔ کسی نے حضورؐ سے اس کا تذکرہ کیا تو آپؐ اس کے گھر تشریف لے گئے۔ جب اس نوجوان کی حضورؐ پر نگاہ پڑی تو وہ کھڑے ہو کر حضورؐ کے گلے لگ گیا اور اسی حال میں اس کی جان نکل گئی اور وہ مر کر نیچے گر پڑا۔ حضورؐ نے فرمایا تم اپنے ساتھی کی تجہیز و تکفین کرو، جہنم کے ڈر نے اس کے جگر کے ٹکڑے کر دیے۔",""],[" (28)","s"]]],["p",[["اور ",""],["حضرت شداد بن اوسؓ","b"],[" کا قصہ بھی گزر چکا ہے کہ جب وہ بستر پر لیٹتے تو کروٹیں بدلتے رہتے اور ان کو نیند نہ آتی اور یوں فرماتے اے ",""],["ٱللَّٰه","a"],["! جہنم نے میری نیند اڑا دی ہے۔ پھر کھڑے ہو کر نماز شروع کر دیتے اور صبح تک اسی میں مشغول رہتے۔ اس باب کے کچھ قصے حضورؐ کے صحابہؓ کے رونے کے باب میں گزر چکے ہیں۔ اور غزوہ موتہ کے دن کے واقعات میں یہ گزر چکا ہے کہ ",""],["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن رواحہؓ","b"],[" رونے لگے اور کہنے لگے کہ غور سے سنو ",""],["ٱللَّٰه","a"],[" کی قسم! نہ تو میرے دل میں دنیا کی محبت ہے اور نہ تم لوگوں سے تعلق اور لگاؤ، بلکہ میں نے حضورؐ کو قرآن کی اس آیت کو پڑھتے ہوئے سنا ہے جس میں دوزخ کی آگ کا تذکرہ ہے:",""]]],["q",[["وَإِن مِّنكُمْ إِلَّا وَارِدُهَا ۚ كَانَ عَلَىٰ رَبِّكَ حَتْمًا مَّقْضِيًّا  (سورۃ مریم: ۷۱)","a"]]],["p",[["ترجمہ: \"اور تم میں سے کوئی بھی نہیں جس کا اس پر سے گزر نہ ہو۔ یہ آپ کے رب کے اعتبار سے لازم ہے جو (ضرور) پورا ہو کر رہے گا۔\" اب مجھے معلوم نہیں کہ اس آگ پر پہنچنے کے بعد واپسی کس طرح ہوگی؟",""]]]],"f":[["(28)","Haakim has reported the narration from reliable sources from Hadhrat Sahl, while Ibn Abi Dunya has reported it from Hadhrat Hudhayfah."]]}]},"15":{"lead":[],"stories":[{"b":[["n",[["حضرت نیار بن مکرم اسلمیؓ","b"],[" فرماتے ہیں کہ جب یہ آیات نازل ہوئیں:",""]]],["q",[["الٓمٓ ۝ غُلِبَتِ ٱلرُّومُ ۝ فِىٓ أَدْنَى ٱلْأَرْضِ وَهُم مِّنۢ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ ۝ فِى بِضْعِ سِنِينَ  (سورۃ الروم: ۱-۴)","a"]]],["p",[["ترجمہ: \"الم۔ اہل روم ایک قریب کے موقع میں مغلوب ہو گئے اور وہ اپنے مغلوب ہونے کے بعد عنقریب تین سال سے لے کر نو سال کے اندر اندر غالب آ جائیں گے\"، تو اس وقت فارس والے روم والوں پر غالب آئے ہوئے تھے اور مسلمان یہ چاہتے تھے کہ روم والے فارس والوں پر غالب آ جائیں کیونکہ مسلمان اور روم والے اہل کتاب تھے، اور اس بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ کا یہ فرمان ہے:",""]]],["q",[["وَيَوْمَئِذٍ يَفْرَحُ ٱلْمُؤْمِنُونَ ۝ بِنَصْرِ ٱللَّهِ ۚ يَنصُرُ مَن يَشَآءُ ۖ وَهُوَ ٱلْعَزِيزُ ٱلرَّحِيمُ  (سورۃ الروم: ۴-۵)","a"]]],["p",[["ترجمہ: \"اس روز مسلمان ",""],["ٱللَّٰه","a"],[" تعالیٰ کی اس امداد پر خوش ہوں گے جس کو چاہے غالب کر دیتا ہے اور وہ زبردست ہے (اور) رحیم ہے۔\" اور قریش چاہتے تھے کہ فارس والے روم والوں پر غالب رہیں کیونکہ قریش اور فارس والے دونوں نہ تو اہل کتاب تھے اور نہ انہیں مرنے کے بعد دوبارہ زندہ ہونے کا یقین تھا۔ جب ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ آیت نازل فرمائی تو حضرت ابوبکرؓ مکہ کے مختلف علاقوں میں جا کر بلند آواز سے یہ آیت پڑھنے لگے۔ تو قریش کے کچھ لوگوں نے حضرت ابوبکرؓ سے کہا یہ آیت ہمارے اور تمہارے درمیان فیصلہ کر دے گی۔ آپ کے حضرت (یعنی نبی کریم ",""],["ﷺ","a"],[") یہ کہتے ہیں کہ روم والے فارس والوں پر تین سے لے کر نو سال کے اندر اندر غالب آ جائیں گے۔ کیا ہم آپ کے ساتھ اس بات پر شرط نہ لگا لیں؟ حضرت ابوبکرؓ نے کہا ٹھیک ہے، اور یہ شرط لگانے کے حرام ہونے سے پہلے کا واقعہ ہے؛ چنانچہ حضرت ابوبکرؓ اور مشرکوں نے شرط لگائی اور ہارنے پر جو چیز دینی پڑے گی اسے طے کیا۔ اور مشرکوں نے حضرت ابوبکرؓ سے کہا آپ تین سال سے لے کر نو سال تک کی مدت میں سے کتنے سال طے کیا کرتے ہیں؟ آپ ہمارے اور اپنے درمیان کوئی مدت طے کر دیں تاکہ اس کے پورا ہونے پر پتہ چلے کہ شرط میں کون ہارتا ہے اور کون جیتتا ہے۔) چنانچہ انہوں نے چھ سال متعین کر دیے۔ پھر چھ سال گزرنے پر بھی رومی لوگ غلبہ نہ پا سکے تو مشرکین نے حضرت ابوبکرؓ سے شرط لگائی ہوئی چیز لے لی۔ پھر جب ساتواں سال شروع ہوا تو روم والے فارس والوں پر غالب آ گئے۔ مسلمان حضرت ابوبکرؓ پر چھ سال مقرر کرنے پر اعتراض کرنے لگے کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تو یہ کہا تھا کہ تین سال سے نو سال کے اندر اندر۔ جب نو سال سے پہلے پہلے روم والوں نے فارس والوں پر غلبہ حاصل کر لیا تو اس سے بہت سے لوگ مسلمان ہو گئے۔",""],[" (1)","s"]]]],"f":[["(1)","Tirmidhi."]]},{"b":[["n",[["حضرت براءؓ","b"],[" فرماتے ہیں کہ جب یہ آیات نازل ہوئیں:",""]]],["q",[["الٓمٓ ۝ غُلِبَتِ ٱلرُّومُ ۝ فِىٓ أَدْنَى ٱلْأَرْضِ وَهُم مِّنۢ بَعْدِ غَلَبِهِمْ سَيَغْلِبُونَ","a"]]],["p",[["تو مشرکوں نے حضرت ابوبکرؓ سے کہا کیا آپ نہیں دیکھ رہے کہ آپ کے حضرت کیا کہہ رہے ہیں؟ یوں کہہ رہے ہیں کہ روم والے فارس والوں پر غالب آ جائیں گے۔ حضرت ابوبکرؓ نے فرمایا میرے حضرت بالکل سچ کہتے ہیں۔ ان مشرکوں نے کہا کیا آپ ہم سے اس پر شرط لگانے کو تیار ہیں؟ چنانچہ حضرت ابوبکرؓ نے روم والوں کے غالب آنے کی مدت مقرر کر دی لیکن وہ مدت گزر گئی اور رومی فارس والوں پر غالب نہ آ سکے۔ جب حضورؐ کو اس کی خبر ہوئی تو آپؐ نے ناگواری کا اظہار فرمایا۔ یہ شرط لگا کر سال مقرر کر دینا حضورؐ کو پسند نہ آیا۔ آپؐ نے حضرت ابوبکرؓ سے فرمایا تم نے ایسا کیوں کیا؟ حضرت ابوبکرؓ نے عرض کیا میں نے ",""],["ٱللَّٰه","a"],[" اور اس کے رسولؐ کو سچا سمجھتے ہوئے ایسا کیا۔ حضورؐ نے فرمایا اب مشرکوں کے پاس جاؤ اور شرط میں جو چیز مقرر کی ہے اس کی مقدار بھی بڑھا دو اور مدت بھی بڑھا دو۔ چنانچہ حضرت ابوبکرؓ نے جا کر مشرکوں سے کہا کیا آپ لوگ دوبارہ شرط لگاؤ گے؟ کیونکہ دوبارہ شرط پہلے سے زیادہ اچھی ہوگی۔ مشرکوں نے کہا ٹھیک ہے۔ (چنانچہ دوبارہ جو مدت متعین کی تھی) اس مدت کے پورا ہونے سے پہلے ہی روم نے فارس پر غلبہ پا لیا اور انہوں نے اپنے گھوڑے مدائن میں باندھ دیے اور رومیہ شہر کی بنیاد رکھی۔ پھر حضرت ابوبکرؓ شرط والا مال لے کر حضورؐ کی خدمت میں آئے اور عرض کیا یہ حرام مال ہے۔ حضورؐ نے فرمایا یہ دوسروں کو دے دو۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Abi Haatim, Ahmad, Tirmidhi, Nasa'ee and Ibn Jareer, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.423)."]]},{"b":[["n",[["حضرت کعب بن عدیؓ","b"],[" فرماتے ہیں کہ میں اہل حیرہ کے وفد کے ساتھ حضورؐ کی خدمت میں حاضر ہوا۔ آپؐ نے ہم پر اسلام پیش کیا۔ ہم مسلمان ہو گئے اور حیرہ واپس آ گئے۔ چند دن گزرے تھے کہ حضورؐ کی وفات کی خبر آ گئی جس سے میرے ساتھی تو شک میں پڑ گئے اور کہنے لگے اگر وہ نبی ہوتے تو ان کا انتقال نہ ہوتا۔ میں نے کہا نہیں۔ ان سے پہلے اور انبیاء کا بھی تو انتقال ہو چکا ہے۔ میں اسلام پر پکا رہا، پھر میں مدینہ کے ارادے سے چل پڑا۔ راستے میں میرا گزر ایک راہب کے پاس سے ہوا۔ ہم اس سے پوچھے بغیر کوئی فیصلہ نہیں کرتے تھے۔ میں نے جا کر اس سے کہا جس کام کا میں نے ارادہ کیا ہے اس کے بارے میں مجھے بتاؤ، اس بارے میں میرے دل میں کچھ کھٹک سی ہے۔ اس راہب نے کہا اپنے نام کی کوئی چیز لاؤ۔ میں ٹخنے کی ہڈی لایا (عربی میں ٹخنے کی ہڈی کو کعب کہتے ہیں اور ان کا نام بھی کعب تھا)۔ اس نے کچھ بال نکالے اور کہا اس ہڈی کو ان بالوں میں ڈال دو۔ میں نے وہ ہڈی ان بالوں میں ڈال دی تو مجھے حضورؐ بالکل اسی صورت میں نظر آئے جس میں میں نے آپؐ کو دیکھا تھا اور مجھے آپؐ کی موت کا منظر بھی سارا اسی طرح نظر آیا جس طرح ہوا تھا (بظاہر جادو کے زور سے یہ سب کچھ نظر آیا)۔ اس سے میرے ایمان کی بصیرت اور بڑھ گئی۔ میں نے حضرت ابوبکرؓ کی خدمت میں حاضر ہو کر یہ سارا قصہ سنایا اور میں ان کے پاس ٹھہر گیا۔ پھر انہوں نے مجھے (اسکندریہ کے بادشاہ) مقوقس کے پاس بھیجا، وہاں سے واپس آیا تو پھر حضرت عمرؓ نے مجھے مقوقس کے پاس بھیجا اور جنگ یرموک کے بعد حضرت عمرؓ کا خط لے کر مقوقس کے پاس پہنچا۔ مجھے جنگ یرموک کی اس وقت تک خبر نہیں تھی۔ مقوقس نے کہا مجھے پتہ چلا ہے کہ رومیوں نے عربوں کو قتل کر دیا ہے اور انہیں شکست دے دی ہے۔ میں نے کہا نہیں، ایسا نہیں ہو سکتا۔ اس نے کہا کیوں؟ میں نے کہا کیونکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ وعدہ خلافی نہیں کرتے۔ اس پر اس نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! عربوں نے رومیوں کو ایسے قتل کیا ہے جیسے قوم عاد کو قتل کیا گیا تھا اور تمہارے نبیؐ نے بالکل سچ کہا۔ پھر اس نے مجھ سے بڑے بڑے صحابہؓ کے بارے میں پوچھا اور مجھے ان کے لیے ہدیے دیے۔ میں نے کہا اس نبیؐ کے چچا حضرت عباسؓ زندہ ہیں، ان کے ساتھ بھی حسن سلوک اور صلہ رحمی کرو۔ حضرت کعبؓ کہتے ہیں میں تجارت وغیرہ میں حضرت عمر بن خطابؓ کا شریک تھا۔ جب حضرت عمرؓ نے عطایا کا رجسٹر بنایا تو مجھے (اپنے خاندان) بنو عدی بن کعب میں شمار کر کے میرا بھی حصہ مقرر کیا۔",""],[" (3)","s"]]]],"f":[["(3)","Baghawi, Ibn Shaaheen, Abu Nu'aym, Ibn Sakan and Ibn Yunus in his history of Egypt, as quoted in Isaabah (Vol.3 Pg.298)."]]},{"b":[["n",[["حضرت ابوبکرؓ","b"],[": مرتدین سے جنگ کرنے کے باب میں حضرت ابوبکرؓ کا یہ قول گزر چکا ہے کہ ",""],["ٱللَّٰه","a"],[" کی قسم! میں ",""],["ٱللَّٰه","a"],[" کی بات کو لے کر کھڑا رہوں گا اور ",""],["ٱللَّٰه","a"],[" کے راستے میں جہاد کرتا رہوں گا یہاں تک کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ اپنے وعدے کو پورا فرما دیں اور اپنے عہد کو ہمارے لیے پورا فرما دیں؛ چنانچہ ہم میں سے جو مارا جائے گا وہ شہید ہو کر جنت میں جائے گا اور ہم میں سے جو باقی رہے گا وہ ",""],["ٱللَّٰه","a"],[" کی زمین پر خلیفہ اور ",""],["ٱللَّٰه","a"],[" کی عبادت کا وارث بن کر رہے گا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے حق کو مضبوط فرمایا ہے اور ان کے فرمان کے خلاف نہیں ہو سکتا۔ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا ہے:",""]]],["q",[["وَعَدَ ٱللَّهُ ٱلَّذِينَ ءَامَنُوا۟ مِنكُمْ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ لَيَسْتَخْلِفَنَّهُمْ فِى ٱلْأَرْضِ كَمَا ٱسْتَخْلَفَ ٱلَّذِينَ مِن قَبْلِهِمْ  (سورۃ النور: ۵۵)","a"]]],["p",[["ترجمہ: \"(اے مجموعہ امت!) تم میں جو لوگ ایمان لاویں اور نیک عمل کریں ان سے ",""],["ٱللَّٰه","a"],[" تعالیٰ وعدہ فرماتا ہے کہ ان کو (اس اتباع کی برکت سے) زمین میں حکومت عطا فرمائے گا جیسا کہ ان سے پہلے (اہل ہدایت) لوگوں کو حکومت دی تھی۔\"",""],[" (4)","s"]]]],"f":[["(4)","Under the heading \"Hadhrat Abu Bakr Ensures that Jihaad is Waged Against the Murtaddeen and Those Who Refused to Pay Zakaah\" and the subheading \"Hadhrat Abu Bakr Consults with the Muhaajireen and the Ansaar about Waging Jihaad and Delivers a Sermon in this Regard\"."]]},{"b":[["n",[["حضرت عمرؓ","b"],[": جہاد اور ",""],["ٱللَّٰه","a"],[" کے راستے میں نکلنے کی ترغیب دینے کے باب میں ان کا یہ فرمان گزر چکا ہے کہ وہ مہاجرین کہاں ہیں جو ",""],["ٱللَّٰه","a"],[" کے دین کے لیے ایک دم دوڑ کر آیا کرتے تھے، وہ آج ",""],["ٱللَّٰه","a"],[" کے وعدے سے کہاں دور جا پڑے ہیں؟ تم اس سرزمین میں جہاد کے لیے چلو جس کے بارے میں ",""],["ٱللَّٰه","a"],[" تعالیٰ نے یہ فرمایا ہے:",""]]],["q",[["لِيُظْهِرَهُۥ عَلَى ٱلدِّينِ كُلِّهِۦ  (سورۃ التوبہ: ۳۳)","a"]]],["p",[["ترجمہ: \"تاکہ اس کو تمام (بقیہ) دینوں پر غالب کر دے۔\" ",""],["ٱللَّٰه","a"],[" اپنے دین کو ضرور غالب کریں گے اور اپنے مددگار کو عزت دیں گے اور اپنے دین والوں کو تمام قوموں کا وارث بنائیں گے۔ ",""],["ٱللَّٰه","a"],[" کے نیک بندے کہاں ہیں؟",""],[" (5)","s"]]]],"f":[["(5)","Under the heading \"Hadhrat Umar Encourages Jihaad in the Path of Allaah and Consults with the Sahabah in Matters Arising Before him\" and the subheading \"Hadhrat Umar Encourages People Towards Jihaad\"."]]},{"b":[["n",[["حضرت سعدؓ","b"],[": اور جہاد کے لیے ترغیب دینے کے باب میں حضرت سعدؓ کا یہ قول گزر چکا ہے کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ حق ہیں اور بادشاہت میں ان کا کوئی شریک نہیں، اس کی کسی بات کے خلاف نہیں ہو سکتا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ نے فرمایا:",""]]],["q",[["وَلَقَدْ كَتَبْنَا فِى ٱلزَّبُورِ مِنۢ بَعْدِ ٱلذِّكْرِ أَنَّ ٱلْأَرْضَ يَرِثُهَا عِبَادِىَ ٱلصَّٰلِحُونَ  (سورۃ الانبیاء: ۱۰۵)","a"]]],["p",[["ترجمہ: \"اور ہم (سب آسمانی) کتابوں میں لوح محفوظ (میں لکھنے) کے بعد لکھ چکے ہیں کہ اس زمین (جنت) کے مالک میرے نیک بندے ہوں گے۔\" یہ زمین تمہاری میراث ہے اور تمہارے رب نے تمہیں یہ دینے کا وعدہ کیا ہوا ہے اور تین سال سے ",""],["ٱللَّٰه","a"],[" تعالیٰ نے تمہیں اس زمین کو استعمال کرنے کا موقع دیا ہوا ہے۔ تم خود بھی اس میں سے کھا رہے ہو اور دوسروں کو بھی کھلا رہے ہو اور یہاں کے رہنے والوں کو قتل کر رہے ہو اور ان کا مال سمیٹ رہے ہو اور آج تک ان کی عورتوں اور بچوں کو قید کر رہے ہو۔ غرضیکہ گزشتہ تمام جنگوں میں تمہارے ناموروں نے ان کو بڑا نقصان پہنچایا ہے اور اب تمہارے سامنے ان کا بہت بڑا لشکر جمع ہو کر آ گیا ہے (اس لشکر کی تعداد دو لاکھ بتائی جاتی ہے) اور تم عرب کے سردار اور معزز لوگ ہو اور تم میں سے ہر ایک اپنے قبیلے کا بہترین آدمی ہے اور تمہارے پیچھے رہ جانے والوں کی عزت تم ہی سے وابستہ ہے۔ اگر تم دنیا کی بے رغبتی اور آخرت کا شوق اختیار کرو تو ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہیں دنیا اور آخرت دونوں دے دیں گے۔",""],[" (6)","s"]]]],"f":[["(6)","Under the heading \"Hadhrat Sa'd bin Abi Waqqaas Encourages the Muslims to wage Jihaad\" and the subheading \"The Speech of Hadhrat Sa'd during the Battle of Qaadisiyyah\"."]]}]},"16":{"lead":[],"stories":[{"b":[["n",[["حضرت عمارہ بن خزیمہ بن ثابتؓ","b"],[" اپنے چچا سے نقل کرتے ہیں جو کہ حضورؐ کے صحابی ہیں کہ ایک مرتبہ نبی کریم ",""],["ﷺ","a"],[" نے ایک دیہاتی آدمی سے گھوڑا خریدا اور اسے اپنے پیچھے آنے کے لیے کہا تاکہ اسے گھوڑے کی قیمت دے دیں۔ حضورؐ تیز تیز چلتے ہوئے آگے نکل گئے۔ وہ دیہاتی آہستہ آہستہ چل رہا تھا۔ لوگوں کو معلوم نہیں تھا کہ حضورؐ نے اس سے یہ گھوڑا خرید لیا ہے، اس لیے لوگ اس سے اس گھوڑے کا سودا کرنے لگے۔ ہوتے ہوتے ایک آدمی نے اس گھوڑے کی قیمت حضورؐ سے زیادہ لگا دی تو اس نے حضورؐ کو آواز دے کر کہا آپؐ یہ گھوڑا خریدنا چاہتے ہیں تو خرید لیں ورنہ میں اسے بیچنے لگا ہوں۔ حضورؐ نے جب اس دیہاتی کی یہ بات سنی تو رک گئے۔ جب دیہاتی آپؐ کے پاس پہنچا تو آپؐ نے اس سے کہا کیا میں نے تم سے یہ گھوڑا نہیں خرید لیا؟ اس نے کہا نہیں، ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے آپؐ کو یہ گھوڑا نہیں بیچا۔ حضورؐ نے فرمایا نہیں، میں تم سے یہ گھوڑا خرید چکا ہوں۔ حضورؐ اور وہ دیہاتی آپس میں بات کرنے لگے تو دونوں کے گرد لوگ جمع ہو گئے۔ پھر وہ دیہاتی کہنے لگا آپؐ اپنا کوئی گواہ لائیں جو اس بات کی گواہی دے کہ میں نے آپؐ کے ہاتھ یہ گھوڑا بیچا ہے۔ جو بھی مسلمان وہاں آتا وہ اس دیہاتی کو بھی کہتا تیرا ناس ہو، رسول ",""],["ٱللَّٰه","a"],["ؐ تو ہمیشہ صرف حق بات ہی کہتے ہیں، یہاں تک کہ حضرت خزیمہ بن ثابتؓ بھی آ گئے اور انہوں نے حضورؐ اور دیہاتی کی گفتگو سنی۔ اور دیہاتی کہہ رہا تھا آپؐ اپنا کوئی گواہ لائیں جو اس بات کی گواہی دے کہ میں نے یہ گھوڑا آپؐ کے ہاتھ بیچا ہے۔ حضرت خزیمہؓ نے فوراً کہا میں اس بات کی گواہی دیتا ہوں کہ تم نے حضورؐ کے ہاتھ یہ گھوڑا بیچا ہے۔ حضورؐ نے حضرت خزیمہؓ کی طرف متوجہ ہو کر فرمایا تم کس بنیاد پر گواہی دے رہے ہو؟ حضرت خزیمہؓ نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! میں اس بنیاد پر گواہی دے رہا ہوں کہ میں آپؐ کو سچا مانتا ہوں۔ ",""],["اس پر حضورؐ نے اکیلے حضرت خزیمہؓ کی گواہی کو دو آدمیوں کی گواہی کے برابر قرار دے دیا۔","h"],[" (1)","s"]]]],"f":[["(1)","Ibn Sa'd (Vol.4 Pg.378). Abu Dawood (Pg.508) has reported a similar narration."]]},{"b":[["n",[["حضرت محمد بن عمارہ بن خزیمہؒ","b"],[" کہتے ہیں کہ حضورؐ نے فرمایا اے خزیمہ! تم تو ہمارے ساتھ نہیں تھے تو تم کس بنیاد پر گواہی دے رہے ہو؟ انہوں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! جب میں آپؐ کو آسمان کی باتوں میں سچا مانتا ہوں تو آپؐ یہ جو بات کہہ رہے ہیں اس میں میں آپؐ کو سچا کیسے نہ مانوں؟ چنانچہ حضورؐ نے ان کی گواہی کو دو مردوں کی گواہی کے برابر قرار دے دیا۔ ابن سعد کی دوسری روایت میں یہ ہے کہ حضرت خزیمہؓ نے کہا مجھے اس بات کا یقین ہے کہ آپؐ ہمیشہ صرف حق بات ہی کہتے ہیں، بلکہ اس سے بھی بہتر بات یعنی دینی معاملات میں ہم آپؐ پر ایمان لا چکے ہیں۔ حضورؐ نے ان کی گواہی کو درست قرار دیا۔",""],[" (2)","s"]]]],"f":[["(2)","Ibn Sa'd (Vol.4 Pg.379)."]]},{"b":[["n",[["حضرت عائشہؓ","b"],[" فرماتی ہیں کہ جب حضورؐ شب معراج میں مسجد اقصیٰ تشریف لے گئے تو لوگ اس بارے میں باتیں کرنے لگے اور جو لوگ آپؐ پر ایمان لائے تھے اور آپؐ کی تصدیق کر چکے تھے ان میں سے کچھ لوگ مرتد ہو گئے۔ پھر یہ لوگ حضرت ابوبکرؓ کے پاس گئے اور ان سے جا کر کہا آپ اپنے حضرت کے بارے میں کیا خیال رکھتے ہیں؟ وہ یہ کہہ رہے ہیں کہ وہ آج رات بیت المقدس گئے تھے۔ حضرت ابوبکرؓ نے کہا کیا انہوں نے یہ بات کہی ہے؟ لوگوں نے کہا جی ہاں! حضرت ابوبکرؓ نے کہا اگر انہوں نے یہ بات کہی ہے تو بالکل سچ ہے۔ لوگوں نے کہا تو کیا آپ اس بات کی تصدیق کرتے ہیں کہ وہ آج رات بیت المقدس گئے تھے اور صبح سے پہلے واپس بھی آ گئے؟ حضرت ابوبکرؓ نے کہا جی ہاں! ",""],["میں تو اس سے بھی زیادہ بعید نظر آنے والے امور میں ان کی تصدیق کرتا ہوں۔","h"],[" اسی وجہ سے حضرت ابوبکرؓ کا نام صدیق رکھا گیا۔",""]]],["p",[["ایک روایت میں یہ ہے کہ حضورؐ پر جو لوگ ایمان لا چکے تھے ان میں سے کچھ لوگ اس موقع پر مرتد ہو گئے اور ان میں سے بہت سے لوگوں نے اس واقعہ کی تصدیق کی۔ بہرحال یہ واقعہ بھی بہت بڑی آزمائش کا تھا۔",""],[" (3)","s"]]]],"f":[["(3)","Bayhaqi, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.21)."]]},{"b":[["n",[["حضرت انسؓ","b"],[" شب معراج کا واقعہ تفصیل سے ذکر کرتے ہیں، آخر میں یہ ہے کہ جب مشرکوں نے حضورؐ کی بات سنی تو وہ حضرت ابوبکر صدیقؓ کے پاس گئے اور ان سے کہا اے ابوبکر! آپ کا اپنے حضرت کے بارے میں کیا خیال ہے؟ وہ بتا رہے ہیں کہ وہ آج رات ایک مہینے کی مسافت پر گئے تھے اور پھر رات ہی واپس آ گئے۔ آگے پچھلی حدیث جیسا مضمون ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Abi Haatim, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.7)."]]},{"b":[["n",[["حضرت جابر بن عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں کہ حضرت عمرؓ کے زمانہ خلافت میں ایک سال ٹڈیاں کم ہو گئیں۔ حضرت عمرؓ نے ٹڈیوں کے بارے میں بہت پوچھا لیکن کہیں سے کوئی خبر نہ ملی تو وہ اس سے بہت پریشان ہوئے؛ چنانچہ انہوں نے ایک سوار ادھر یعنی یمن بھیجا اور دوسرا شام اور تیسرا عراق بھیجا تاکہ یہ سوار پوچھ کر آئیں کہ کہیں ٹڈی نظر آئی ہے یا نہیں۔ جو سوار یمن گیا تھا وہ وہاں سے ٹڈیوں کی ایک مٹھی لایا اور لا کر حضرت عمرؓ کے سامنے ڈال دی۔ حضرت عمرؓ نے جب انہیں دیکھا تو تین دفعہ ",""],["ٱللَّٰه","a"],[" اکبر کہا، پھر فرمایا میں نے حضورؐ کو فرماتے ہوئے سنا ہے کہ ",""],["ٱللَّٰه","ah"],[" تعالیٰ نے ایک ہزار قسم کی مخلوق پیدا کی ہے، چھ سو سمندر میں اور چار سو خشکی میں اور ان میں سے سب سے پہلے ٹڈی ختم ہوگی۔","h"],[" جب ٹڈیاں ختم ہو جائیں گی تو پھر اور مخلوقات بھی ایسے آگے پیچھے ہلاک ہونی شروع ہو جائیں گی جیسے موتیوں کی لڑی کا دھاگہ ٹوٹ گیا ہو۔",""],[" (5)","s"]]]],"f":[["(5)","Abu Nu'aym, as quoted in Muntakhab Kanzul Ummaal (Vol.4 Pg.353)."]]},{"b":[["n",[["حضرت فضالہ بن ابی فضالہ انصاریؓ","b"],[" فرماتے ہیں کہ حضرت علی بن ابی طالبؓ ینبع میں بیمار تھے اور بیماری کافی شدید تھی۔ میں اپنے والد کے ساتھ ان کی عیادت کرنے ینبع گیا۔ میرے والد صاحب نے ان سے کہا آپ یہاں کیوں ٹھہرے ہوئے ہیں؟ اگر آپ کا یہاں انتقال ہو گیا تو آپ کے پاس صرف جہینہ کے دیہاتی ہوں گے۔ آپ تھوڑی سی تکلیف فرما کر مدینہ تشریف لے چلیں۔ اگر آپ کا وہاں انتقال ہوا تو پھر آپ کے ساتھی آپ کے پاس ہوں گے جو آپ کی نماز جنازہ پڑھیں گے۔ (میرے والد) حضرت ابوفضالہؓ بدری صحابہؓ میں سے تھے (اس لیے حضرت علیؓ کی نگاہ میں ان کا بڑا مقام تھا)۔ حضرت علیؓ نے فرمایا مجھے یقین ہے کہ میرا اس بیماری میں انتقال نہیں ہوگا کیونکہ حضورؐ نے مجھے بتایا تھا کہ ",""],["جب تک میں امیر نہ بنایا جاؤں اور پھر میری یہ داڑھی میرے اس سر کے خون سے رنگی نہ جائے اس وقت تک میں نہیں مروں گا۔","h"],[" (6)","s"]]]],"f":[["(6)","Abu Ya'la, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.131)."]]},{"b":[["n",[["حضرت علیؓ","b"],[" فرماتے ہیں کہ میں اونٹ کی رکاب میں پاؤں رکھ چکا تھا کہ اتنے میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن سلامؓ میرے پاس آئے اور کہنے لگے آپ کہاں جا رہے ہیں؟ میں نے کہا عراق۔ انہوں نے کہا اگر آپ وہاں گئے تو کوئی آپ کو تلوار مارے گا۔ حضرت علیؓ کہتے ہیں کہ ",""],["ٱللَّٰه","a"],[" کی قسم! میں نے ان سے پہلے یہ بات حضورؐ سے سنی ہوئی ہے۔",""],[" (7)","s"]]]],"f":[["(7)","Ahmad in his Zawaa'id, Ibn Abi Shaybah, Bazzaar, Haarith, Abu Nu'aym, Bayhaqi in his Dalaa'il and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.59)."]]},{"b":[["n",[["حضرت معاویہ بن جریر حضرمیؒ","b"],[" کہتے ہیں کہ حضرت علیؓ نے فرمایا کہ گھوڑے سوار میرے سامنے سے گزریں (چنانچہ سوار گزرنے لگے)۔ پھر حضرت علیؓ کے پاس سے ابن ملجم گزرا۔ حضرت علیؓ نے اس سے اس کا نام اور نسب پوچھا، اس نے اپنے باپ کے علاوہ کسی اور کا نام بتا دیا۔ حضرت علیؓ نے فرمایا تم غلط کہتے ہو۔ پھر اس نے اپنے باپ کا نام لیا۔ حضرت علیؓ نے فرمایا اب تم نے ٹھیک کہا۔ حضورؐ نے مجھے بتایا تھا کہ میرا قاتل یہودیوں میں سے ہوگا۔ یہ ابن ملجم یہودی تھا۔ حضرت علیؓ نے اس سے کہا چلے جاؤ۔",""],[" (8)","s"]]]],"f":[["(8)","Humaydi, Bazzaar, Abu Ya'la, Ibn Hibbaan, Haakim and others, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.59)."]]},{"b":[["n",[["حضرت عبیدہؒ","b"],[" کہتے ہیں کہ جب حضرت علیؓ ابن ملجم کو دیکھتے تو یہ شعر پڑھتے:",""]]],["q",[["أُرِيدُ حَبَاءَهُ وَيُرِيدُ قَتْلِي  ·  عَذِيرَكَ مِنْ خَلِيلِكَ مِنْ مُرَادِ ","a"]]],["p",[["میں اسے عطیہ دینا چاہتا ہوں اور وہ مجھے قتل کرنا چاہتا ہے۔ تم قبیلہ مراد میں سے اپنا وہ دوست لاؤ جو تمہارا عذر بیان کرے (مراد ابن ملجم کا قبیلہ تھا)۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Adi and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.62)."]]},{"b":[["n",[["حضرت ابوطفیلؒ","b"],[" کہتے ہیں کہ میں حضرت علی بن ابی طالبؓ کے پاس تھا، اس وقت ان کے پاس عبدالرحمن بن ملجم آیا۔ حضرت علیؓ نے حکم دیا کہ اسے عطیہ دیا جائے۔ پھر اپنی داڑھی کی طرف اشارہ کرتے ہوئے فرمایا اس داڑھی کو اوپر کے حصے (کے خون) سے رنگنے سے اس بدبخت کو کوئی نہیں روک سکتا۔ پھر حضرت علیؓ نے یہ اشعار پڑھے:",""]]],["q",[["اُشْدُدْ حَيَازِيمَكَ لِلْمَوْتِ  ·  فَإِنَّ الْمَوْتَ آتِيكَا","a"]]],["p",[["تو موت کے لیے اپنی کمر کس لے کیونکہ موت تمہیں ضرور آئے گی۔",""]]],["q",[["وَلَا تَجْزَعْ مِنَ الْقَتْلِ  ·  إِذَا حَلَّ بِوَادِيكَا","a"]]],["p",[["اور جب قتل تمہاری وادی میں اتر جائے تو پھر قتل ہونے سے نہ گھبرانا۔",""],[" (10)","s"]]]],"f":[["(10)","Abdur Razzaaq, Ibn Sa'd and Wakee, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.61)."]]},{"b":[["n",[["حضرت ام عمارؓ","b"],[" جنہوں نے حضرت عمارؓ کی پرورش کی تھی، وہ بیان کرتی ہیں کہ ایک مرتبہ حضرت عمارؓ بیمار ہو گئے تو کہنے لگے اس بیماری میں مجھے موت نہیں آئے گی کیونکہ میرے محبوب محمدؐ نے مجھے بتایا تھا کہ مسلمانوں کی دو جماعتوں میں لڑائی ہوگی اور میں ان دو جماعتوں کے درمیان شہید ہو کر ہی مروں گا۔",""],[" (11)","s"]]],["p",[["صحابہ کرامؓ کے ",""],["ٱللَّٰه","a"],[" کے راستے میں شوق شہادت کے قصوں میں حضرت عمارؓ کا قول گزر چکا ہے کہ حضورؐ نے مجھ سے فرمایا تھا کہ دنیا میں تمہارا آخری توشہ دودھ کی لسی ہوگی (اور وہ میں پی چکا ہوں اور اب میں دنیا سے جانے والا ہوں)۔ جنگ صفین کے دن حضرت عمارؓ جب لڑ رہے تھے لیکن شہید نہیں ہو رہے تھے اس وقت ان کے حضرت علیؓ کے پاس جانے کا قصہ بھی گزر چکا ہے اور ان کا یہ قول بھی گزر چکا ہے کہ اے امیر المومنین! یہ فلاں دن ہے (یعنی حضورؐ نے مجھے جس دن شہید ہونے کی خوشخبری دی تھی وہ دن یہی ہے)۔ حضرت علیؓ جواب میں فرماتے اے ابوالیقظان! اس خیال کو جانے دو۔ اس طرح تین مرتبہ ہوا۔ پھر ان کے پاس دودھ لایا گیا جسے انہوں نے پی لیا۔ پھر فرمایا کہ رسول ",""],["ٱللَّٰه","a"],["ؐ نے فرمایا تھا کہ دودھ ہی وہ چیز ہے جسے میں دنیا سے جاتے وقت سب سے آخر میں پیوں گا۔ پھر کھڑے ہو کر جنگ کی یہاں تک کہ شہید ہو گئے۔",""],[" (12)","s"],[" (13)","s"]]]],"f":[["(11)","Ibn Sa'd and Abu Nu'aym, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.59)."],["(12)","Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.247)."],["(13)","Under the heading \"Miscellaneous Stories about the Enthusiasm of the Sahabah to Fight in the path of Allaah\" and the subheading \"The Enthusiasm of Hadhrat Ammaar bin Yaasir to Fight in the Path of Allaah\"."]]},{"b":[["n",[["حضرت خالد بن ولیدؓ","b"],[" کہتے ہیں کہ حضرت ہشام بن ولید بن مغیرہ کی بیٹی حضرت عمارؓ کی تیمارداری کیا کرتی تھیں، وہ کہتی ہیں کہ حضرت معاویہؓ حضرت عمارؓ کی عیادت کے لیے آئے۔ جب حضرت معاویہؓ ان کے پاس سے باہر گئے تو کہنے لگے اے ",""],["ٱللَّٰه","a"],["! ان کی موت ہمارے ہاتھوں سے نہ ہو کیونکہ میں نے حضورؐ کو یہ فرماتے ہوئے سنا ہے کہ ",""],["عمارؓ کو ایک باغی جماعت قتل کرے گی۔","h"],[" (14)","s"]]]],"f":[["(14)","Abu Ya'la and Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.247)."]]},{"b":[["n",[["حضرت ابراہیم بن اشترؒ","b"],[" اپنے والد سے نقل کرتے ہیں کہ جب حضرت ابوذرؓ کی وفات کا وقت قریب آیا تو ان کی بیوی رونے لگی۔ انہوں نے اپنی بیوی سے کہا تم کیوں رو رہی ہو؟ اس نے کہا میں اس لیے رو رہی ہوں کہ مجھ میں آپ کو دفن کرنے کی طاقت نہیں اور نہ ہی میرے پاس اتنا کپڑا ہے جو آپ کے دفن کے لیے کافی ہو۔ حضرت ابوذرؓ نے کہا مت روؤ کیونکہ میں نے حضورؐ کو کچھ لوگوں کو فرماتے ہوئے سنا اور ان لوگوں میں میں بھی تھا۔ آپؐ نے فرمایا تم لوگوں میں سے ایک آدمی کی موت جنگل بیابان میں آئے گی اور اس کے جنازے میں مسلمانوں کی ایک جماعت شریک ہوگی۔ اب ان لوگوں میں ہر ایک کا انتقال کسی نہ کسی بستی میں اور مسلمانوں کے مجمع میں ہوا ہے، اب میں ہی ایسا ہوں کہ جسے جنگل بیابان میں موت آئے گی۔ ",""],["ٱللَّٰه","a"],[" کی قسم! نہ تو میں غلط کہہ رہا ہوں اور نہ حضورؐ نے مجھ سے غلط بات کی ہے، لہٰذا آنے جانے کے عام راستے کی طرف دیکھو۔ ان کی بیوی نے کہا حاجیوں کے قافلے واپس جا چکے ہیں اور راستے بند ہو چکے ہیں۔ بہرحال وہ ٹیلے پر چڑھ کر کھڑی ہو جاتیں اور راستے کی طرف دیکھتیں (جب کوئی نظر نہ آتا تو) واپس آ کر تیمارداری میں لگ جاتیں اور پھر ٹیلے پر چڑھ کر دیکھتیں۔ وہ ایسے ہی کر رہی تھیں کہ اچانک انہوں نے دیکھا کہ ایک جماعت ہے جسے ان کی سواریاں تیزی سے لیے چلی آ رہی ہیں اور وہ اپنے کجاووں میں بیٹھے ہوئے ایسے لگ رہے تھے جیسے گدھ ہوں۔ ان کی بیوی نے کپڑے سے ان کی طرف اشارہ کیا تو وہ دیکھ کر ان کی طرف آئے یہاں تک کہ ان کے پاس آ کر کھڑے ہو گئے اور پوچھا کیا بات ہے؟ ان کی بیوی نے کہا ایک مسلمان مر رہا ہے، کیا آپ اس کے کفن کا انتظام کر سکتے ہیں؟ ان لوگوں نے پوچھا وہ کون ہے؟ انہوں نے بتایا وہ ابوذر ہیں۔ یہ سنتے ہی وہ سب کہنے لگے ہمارے ماں باپ حضرت ابوذرؓ پر قربان ہوں، اور کوڑے مار کر سواریاں تیز دوڑائیں اور حضرت ابوذرؓ کے پاس پہنچ گئے۔ حضرت ابوذرؓ نے کہا تمہیں خوشخبری ہو، اور پھر انہیں حضورؐ والی وہی حدیث سنائی۔ پھر فرمایا میں نے حضورؐ سے یہ سنا ہے کہ جن دو مسلمانوں کے دو یا تین بچے مر جائیں اور وہ ثواب کی نیت سے اس پر صبر کر لیں تو دونوں کو جہنم کے دیکھنے سے بھی ",""],["ٱللَّٰه","a"],[" بچا لیں گے۔ تم لوگ سن رہے ہو، اگر میرے پاس کفن کے لیے کوئی کپڑا ہوتا تو مجھے اسی میں کفن دیا جاتا، ایسے ہی اگر میری بیوی کے پاس میرے کفن کے قابل کوئی کپڑا ہوتا تو مجھے اسی میں کفن دیا جاتا (ہمارے پاس تو کفن کا کپڑا ہے نہیں، اس لیے آپ لوگ کفن کا کپڑا دیں)۔ لیکن میں ",""],["ٱللَّٰه","a"],[" اور اسلام کا واسطہ دے کر کہتا ہوں کہ تم میں سے جو آدمی امیر یا چودھری یا نمبردار یا قاصد رہ چکا ہو وہ مجھے کفن نہ دے۔ تو ان لوگوں میں سے ہر آدمی ان میں سے کسی نہ کسی منصب پر رہ چکا تھا، صرف ایک انصاری جوان ایسا تھا جس نے ان میں سے کوئی بھی کام نہیں کیا تھا۔ اس نے کہا میں آپ کو کفن دوں گا کیونکہ آپ نے جتنی باتیں کہی ہیں ان میں سے کوئی کام میں نے نہیں کیا۔ میں نے یہ چادر اوڑھ رکھی ہے اور میرے تھیلے میں دو کپڑے ہیں جنہیں میری ماں نے کات کر میرے لیے بنایا تھا، میں ان تین کپڑوں میں آپ کو کفن دوں گا۔ حضرت ابوذرؓ نے فرمایا ہاں تم مجھے ضرور کفن دینا؛ چنانچہ اس انصاری نے انہیں کفن دیا۔ راوی حضرت ابراہیمؒ کہتے ہیں کہ اس جماعت میں حضرت حجر بن ادبر اور (میرے والد) مالک بھی تھے اور یہ سب لوگ یمن کے تھے۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابن مسعودؓ","b"],[" کہتے ہیں کہ جب حضرت عثمانؓ نے حضرت ابوذرؓ کو ربذہ بستی کی طرف جلا وطن کر دیا اور تقدیر کی لکھی موت ان کو آنے لگی اور اس وقت ان کے پاس صرف ان کی بیوی اور ان کا ایک غلام تھا تو انہوں نے ان دونوں کو وصیت کی کہ (جب میرا انتقال ہو جائے تو) تم دونوں مجھے غسل دینا اور پھر مجھے کفن دینا، پھر میرے جنازے کو راستے کے درمیان رکھ دینا۔ جو بھی پہلا قافلہ آپ لوگوں کے پاس سے گزرے انہیں بتا دینا کہ یہ حضورؐ کے صحابی حضرت ابوذرؓ ہیں، ان کے دفن کرنے میں ہماری مدد کرو۔ چنانچہ جب ان کا انتقال ہو گیا تو ان دونوں نے غسل دے کر کفن پہنا کر ان کا جنازہ راستہ کے درمیان رکھ دیا کہ اتنے میں حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ عراق کی ایک جماعت کے ساتھ وہاں پہنچے۔ یہ لوگ عمرہ کرنے جا رہے تھے۔ ان کے اونٹ جنازے پر چڑھنے ہی لگے تھے کہ وہ لوگ راستے میں جنازہ دیکھ کر گھبرا گئے۔ حضرت ابوذرؓ کے غلام نے کھڑے ہو کر کہا یہ نبی کریمؐ کے صحابی حضرت ابوذرؓ ہیں، ان کے دفن کرنے میں ہماری مدد کرو۔ یہ سن کر حضرت عبد",""],["ٱللَّٰه","a"],["ؓ چیخ مار کر رونے لگے اور فرمانے لگے ",""],["حضورؐ نے سچ فرمایا تھا کہ (اے ابوذر!) تو اکیلا چلے گا، اکیلا مرے گا اور اکیلا اٹھایا جائے گا۔","h"],[" پھر وہ اور ان کے ساتھی سواریوں سے اترے اور انہیں دفن کیا، پھر حضرت عبد",""],["ٱللَّٰه","a"],[" بن مسعودؓ نے اپنے ساتھیوں کو حضرت ابوذرؓ والی حدیث سنائی اور حضورؐ نے تبوک جاتے ہوئے حضرت ابوذرؓ کو جو کچھ کہا تھا وہ بھی بتایا۔",""],[" (15)","s"]]]],"f":[["(15)","Ibn Sa'd (Vol.4 Pg.233). Abu Nu'aym has reported a similar narration from Hadhrat Ummu Dharr, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.157)."]]},{"b":[["n",[["حضرت حمید بن منہبؒ","b"],[" کہتے ہیں کہ میرے دادا حضرت خریم بن اوسؓ نے فرمایا کہ میں ہجرت کر کے حضورؐ کی طرف چلا اور جب آپؐ تبوک سے واپس آئے اس وقت میں آپؐ کی خدمت میں پہنچا اور میں اسلام میں داخل ہو گیا۔ میں نے حضورؐ کو یہ فرماتے سنا کہ مجھے یہ سفید حیرہ (شہر) دکھایا گیا ہے اور یہ شیماء بنت بقیلہ ازدیہ سفید خچر پر سوار کالا دوپٹہ اوڑھے ہوئے گویا کہ مجھے نظر آ رہی ہے۔ میں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! اگر ہم حیرہ میں داخل ہوں اور جو منظر آپؐ نے شیماء کا بتایا ہے اس منظر میں ہمیں ملے تو کیا وہ مجھے مل جائے گی؟ حضورؐ نے فرمایا ہاں! وہ تمہاری (باندی) ہے۔ پھر (حضورؐ کے انتقال کے بعد) بہت سے لوگ مرتد ہو گئے لیکن ہمارے قبیلہ بنو طے میں کوئی مرتد نہ ہوا؛ چنانچہ ہم حضرت خالد بن ولیدؓ کے ساتھ حیرہ کے ارادے سے چلے۔ جب ہم حیرہ میں داخل ہونے لگے تو ہمیں سب سے پہلے شیماء بنت بقیلہ اسی حال میں ملی جو حضورؐ نے بتایا تھا، سفید خچر پر سوار کالا دوپٹہ اوڑھے ہوئی تھی۔ میں نے اس پر فوراً قبضہ کر لیا اور میں نے کہا مجھے حضورؐ نے اس کا سارا حال بتایا تھا (اور آپؐ نے مجھے یہ دے دی تھی)۔ حضرت خالدؓ نے مجھ سے گواہ طلب کیے؛ چنانچہ حضرت محمد بن مسلمہ انصاریؓ اور حضرت محمد بن بشیر انصاریؓ میرے گواہ بنے جس پر حضرت خالدؓ نے مجھے شیماء دے دی۔ پھر اس شیماء کے پاس اس کا بھائی عبدالمسیح بن بقیلہ صلح کے ارادے سے آیا اور اس نے مجھ سے کہا شیماء کو میرے ہاتھ بیچ دو۔ میں نے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! اس کی قیمت دس سو سے کم نہیں لوں گا؛ چنانچہ اس نے مجھے ہزار درہم دے دیے اور میں نے شیماء اس کے سپرد کر دی۔ میرے ساتھیوں نے مجھ سے کہا اگر تم سو ہزار یعنی لاکھ بھی مانگ لیتے تو وہ لاکھ بھی تمہیں دے دیتا (اس کے پاس تو پیسے بہت تھے)۔ میں نے کہا مجھے معلوم نہیں تھا کہ دس سو سے بھی بڑا کوئی ہندسہ ہوتا ہے۔",""],[" (16)","s"]]]],"f":[["(16)","Ibn Sa'd (Vol.4 Pg.234)."]]},{"b":[["n",[["حضرت جبیر بن حیہؒ","b"],[" کہتے ہیں کہ عجمی کافر سردار بندار فان نے یہ پیغام بھیجا کہ اے عرب کے لوگو! اپنے میں سے ایک آدمی میرے پاس بھیجو تاکہ ہم اس سے بات کریں؛ چنانچہ لوگوں نے اس کام کے لیے حضرت مغیرہ بن شعبہؓ کا انتخاب کیا۔ حضرت جبیر کہتے ہیں کہ میں ان کو دیکھ رہا تھا کہ ان کے لمبے لمبے بال تھے اور وہ کانے تھے۔ چنانچہ وہ اس سردار کے پاس گئے، جب وہ وہاں سے واپس آئے تو ہم نے ان سے پوچھا کہ اس سردار سے کیا بات ہوئی؟ انہوں نے بتایا کہ میں نے پہلے ",""],["ٱللَّٰه","a"],[" کی حمد و ثنا بیان کی پھر میں نے کہا (زمانہ جاہلیت میں) ہم لوگ تمام لوگوں سے زیادہ دور گھر والے تھے (آبادی دور دور تھی)، سب سے زیادہ بھوکے تھے، سب سے زیادہ بدحال تھے، تمام لوگوں میں ہر خیر سے سب سے زیادہ دور تھے یہاں تک کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ہمارے پاس ایک رسول بھیجا جس نے ہم سے دنیا میں ",""],["ٱللَّٰه","a"],[" کی مدد کا اور آخرت میں جنت کا وعدہ کیا اور جب سے وہ رسول ہمارے پاس آئے ہیں اس وقت سے ہم اپنے رب کی طرف سے مسلسل کامیابی اور مدد ہی دیکھ رہے ہیں، اور اب ہم تمہارے پاس آئے ہیں اور ",""],["ٱللَّٰه","a"],[" کی قسم! ہمیں یہاں بادشاہت اور شاندار زندگی نظر آ رہی ہے۔ ہم اسے چھوڑ کر بدحالی کی طرف کبھی واپس نہیں جائیں گے بلکہ یا تو تم پر غالب آ کر جو کچھ تمہارے قبضے میں ہے وہ سب کچھ لے لیں گے یا پھر یہیں ہی شہید ہو جائیں گے۔",""],[" (17)","s"]]],["p",[["حضرت جبیر بن حیہؒ نے حضرت نعمان بن مقرنؓ کے اہواز والوں کے پاس آدمی بھیجنے کے بارے میں لمبی حدیث ذکر کی ہے، اس میں یہ بھی ہے کہ اہواز والوں نے مطالبہ کیا کہ ان کے پاس کوئی آدمی بھیجیں؛ چنانچہ حضرت نعمانؓ نے حضرت مغیرہ بن شعبہؓ کو بھیجا۔ ان لوگوں کے ترجمان نے کہا تم لوگ کون ہو؟ حضرت مغیرہؓ نے کہا ہم عرب کے کچھ لوگ ہیں۔ ہم سخت بدحالی میں تھے اور بہت طویل عرصے سے پریشانیوں اور مصیبتوں میں مبتلا تھے، ہم بھوک کی وجہ سے کھال اور گٹھلی چوسا کرتے تھے، اون اور بالوں کے کپڑے پہنا کرتے تھے، درختوں اور پتھروں کی عبادت کیا کرتے تھے۔ ہمارا یہی حال چل رہا تھا کہ آسمانوں اور زمین کے رب نے ہمارے پاس ہم میں سے ایک نبی بھیجا جس کے ماں باپ کو ہم پہچانتے تھے۔ ہمارے نبیؐ نے ہمیں اس بات کا حکم دیا کہ جب تک تم لوگ ایک ",""],["ٱللَّٰه","a"],[" کی عبادت نہ کرو یا جزیہ ادا نہ کرو ہم تم سے جنگ کرتے رہیں، اور ہمارے نبیؐ نے ہمیں ",""],["ٱللَّٰه","a"],[" کے سارے پیغام پہنچائے، ان میں ایک پیغام یہ تھا کہ ہم میں سے جو آدمی قتل (شہید) ہوگا وہ جنت میں ایسی نعمتیں پائے گا کہ ان جیسی نعمتیں اس نے کبھی نہیں دیکھی ہوں گی اور ہم میں سے جو زندہ رہ جائے گا وہ تمہاری گردنوں کا مالک ہوگا، تم پر غلبہ پائے گا۔",""]]]],"f":[["(17)","Abu Nu'aym in his Dalaa'il (Pg.196) and Tabraani, as quoted in Isaabah."]]},{"b":[["n",[["حضرت طلقؒ","b"],[" کہتے ہیں کہ ایک آدمی نے آ کر حضرت ابوالدرداءؓ سے کہا اے ابوالدرداء! آپ کا گھر جل گیا۔ انہوں نے فرمایا میرا گھر نہیں جل سکتا۔ پھر دوسرے آدمی نے آ کر یہی بات کہی تو انہوں نے کہا نہیں، میرا گھر نہیں جل سکتا۔ پھر تیسرے آدمی نے آ کر بھی وہی بات کہی تو اس کو بھی یہی کہا کہ میرا گھر نہیں جل سکتا۔ پھر چوتھے آدمی نے آ کر کہا آگ تو بھڑکی تھی اور آپ کے گھر تک بھی پہنچ گئی تھی لیکن وہاں جا کر بجھ گئی تھی۔ انہوں نے فرمایا مجھے یقین تھا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ ایسا نہیں کریں گے (یعنی میرے گھر کو جلنے نہیں دیں گے)۔ اس آدمی نے کہا اے ابوالدرداء! ہمیں پتہ نہیں چل رہا کہ آپ کی کونسی بات زیادہ عجیب ہے؟ پہلے آپ نے کہا میرا گھر نہیں جل سکتا، پھر بعد میں آپ نے کہا مجھے یقین تھا کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ ایسا نہیں کریں گے۔ انہوں نے فرمایا میں نے چند کلمات حضورؐ سے سنے ہیں، جو آدمی صبح کو یہ کلمات کہہ لے گا شام تک اسے کوئی مصیبت نہیں پہنچے گی، وہ کلمات یہ ہیں:",""]]],["q",[["اللَّهُمَّ أَنْتَ رَبِّي لَا إِلَهَ إِلَّا أَنْتَ عَلَيْكَ تَوَكَّلْتُ وَأَنْتَ رَبُّ الْعَرْشِ الْكَرِيمِ، مَا شَاءَ اللَّهُ كَانَ وَمَا لَمْ يَشَأْ لَمْ يَكُنْ، وَلَا حَوْلَ وَلَا قُوَّةَ إِلَّا بِاللَّهِ الْعَلِيِّ الْعَظِيمِ أَعْلَمُ أَنَّ اللَّهَ عَلَى كُلِّ شَيْءٍ قَدِيرٌ، وَأَنَّ اللَّهَ قَدْ أَحَاطَ بِكُلِّ شَيْءٍ عِلْمًا، اللَّهُمَّ إِنِّي أَعُوذُ بِكَ مِنْ شَرِّ نَفْسِي وَمِنْ شَرِّ كُلِّ دَابَّةٍ أَنْتَ آخِذٌ بِنَاصِيَتِهَا، إِنَّ رَبِّي عَلَى صِرَاطٍ مُسْتَقِيمٍ","a"]]],["p",[["ترجمہ: اے ",""],["ٱللَّٰه","a"],["! تو میرا رب ہے، تیرے سوا کوئی معبود نہیں، تجھ پر میں نے توکل کیا، تو محترم عرش کا رب ہے۔ جو ",""],["ٱللَّٰه","a"],[" (تبارک و تعالیٰ) نے چاہا وہ ہوا اور جو نہیں چاہا وہ نہیں ہوا۔ برائیوں سے بچنے کی قوت اور نیکی کرنے کی طاقت صرف بزرگ و برتر ",""],["ٱللَّٰه","a"],[" ہی سے ملتی ہے۔ میں اس بات کو جانتا ہوں کہ ",""],["ٱللَّٰه","a"],[" ہر چیز پر قادر ہے اور ",""],["ٱللَّٰه","a"],[" ہر چیز کو اپنے علم سے گھیرے ہوئے ہے۔ اے ",""],["ٱللَّٰه","a"],["! میں اپنے نفس کے شر سے اور ہر اس جانور کے شر سے تیری پناہ چاہتا ہوں جس کی پیشانی کو تو پکڑنے والا ہے۔ بے شک میرا رب سیدھے راستے پر ہے۔",""],[" (18)","s"]]]],"f":[["(18)","Abu Nu'aym in his Dalaa'il (Pg.198)."]]},{"b":[["n",[["دعوت کے باب میں یہ گزر چکا ہے کہ ",""],["حضرت عدی بن حاتمؓ","b"],[" نے فرمایا کہ اس ذات کی قسم جس کے قبضے میں میری جان ہے! تیسری بات بھی ضرور ہو کر رہے گی، اس لیے کہ حضورؐ فرما چکے ہیں۔",""]]]],"f":[]},{"b":[["n",[["صحابہ کرامؓ کی جماعتوں کو دعوت کے لیے بھیجنے کے باب میں یہ گزر چکا ہے کہ ",""],["حضرت ہشام بن عاصؓ","b"],[" نے جبلہ بن ایہم سے کہا ",""],["ٱللَّٰه","a"],[" کی قسم! یہ دربار جہاں تم بیٹھے ہوئے ہو یہ بھی، اور ان شاء ",""],["ٱللَّٰه","a"],[" (تمہارے) بڑے بادشاہ (ہرقل) کا ملک (روم) بھی ہم تم سے ضرور لے لیں گے کیونکہ ہمیں اس کی خبر ہمارے نبی حضرت محمدؐ نے دی ہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابوبکر صدیقؓ کے ",""],["ٱللَّٰه","a"],[" کے راستے میں لشکر بھیجنے کا اہتمام کرنے کے باب میں یہ گزر چکا ہے کہ ",""],["حضرت علیؓ","b"],[" نے کہا میری رائے یہ ہے کہ چاہے آپ خود جائیں چاہے کسی اور کو ان کے پاس بھیج دیں، ان شاء ",""],["ٱللَّٰه","a"],[" کامیابی آپ ہی کو ہوگی، آپ کی مدد ضرور ہوگی۔ حضرت ابوبکرؓ نے فرمایا ",""],["ٱللَّٰه","a"],[" تمہیں خیر کی بشارت دے، یہ تمہیں کہاں سے پتہ چل گیا (کہ کامیابی تو ہمیں ہی ملے گی اور ہماری مدد ضرور ہوگی)؟ حضرت علیؓ نے کہا میں نے حضورؐ کو فرماتے ہوئے سنا کہ یہ دین اپنے دشمنوں پر غالب آ کر رہے گا یہاں تک کہ یہ دین مضبوطی سے کھڑا ہو جائے اور دین والوں کو غلبہ مل جائے گا۔ حضرت ابوبکرؓ نے تعجب سے فرمایا سبحان ",""],["ٱللَّٰه","a"],["! یہ حدیث کتنی عمدہ ہے، تم نے یہ حدیث سنا کر مجھے خوش کر دیا، ",""],["ٱللَّٰه","a"],[" تمہیں ہمیشہ خوش رکھے۔",""]]]],"f":[]},{"b":[["n",[["اور تائیدات غیبیہ کے باب میں ",""],["حضرت ابن عمرؓ","b"],[" کا یہ قول آئے گا کہ جب حضرت ابن عمرؓ نے شیر کا کان پکڑ کر مروڑا اور اس کو راستے سے ہٹایا تو اس کو کہا حضورؐ نے تمہارے بارے میں غلط نہیں کہا ہے، میں نے حضورؐ کو یہ فرماتے ہوئے سنا ہے کہ ابن آدم جس چیز سے ڈرتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ وہ چیز ابن آدم پر مسلط کر دیتے ہیں اور اگر ابن آدم ",""],["ٱللَّٰه","a"],[" تعالیٰ کے علاوہ کسی سے نہ ڈرے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ اس پر اپنے علاوہ کسی اور کو مسلط نہیں ہونے دیتے۔",""],[" (19)","s"]]]],"f":[["(19)","Bayhaqi in his Asmaa was Sifaat (Pg.125)."]]}]},"17":{"lead":[],"stories":[{"b":[["n",[["حضرت ابو اسماءؒ","b"],[" کہتے ہیں کہ ایک مرتبہ حضرت ابوبکرؓ حضورؐ کے ساتھ دوپہر کا کھانا کھا رہے تھے کہ کھاتے میں یہ آیت نازل ہوئی:",""]]],["q",[["فَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ خَيْرًا يَرَهُۥ ۝ وَمَن يَعْمَلْ مِثْقَالَ ذَرَّةٍ شَرًّا يَرَهُۥ  (سورۃ الزلزال: ۷-۸)","a"]]],["p",[["ترجمہ: \"سو جو شخص (دنیا میں) ذرہ برابر نیکی کرے گا وہ (وہاں) اس کو دیکھ لے گا اور جو شخص ذرہ برابر بدی کرے گا وہ اس کو دیکھ لے گا۔\" یہ سن کر حضرت ابوبکرؓ نے کھانا کھانا چھوڑ دیا اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہم جو بھی برا کام کریں گے کیا ہمیں اس کا بدلہ ضرور ملے گا؟ حضورؐ نے فرمایا:",""]]],["c",[["آپ لوگ جو ناگواریاں (دنیا میں) دیکھتے ہو یہ برے عملوں کا بدلہ ہے اور اچھے اعمال کا بدلہ بعد میں آخرت میں دیا جائے گا۔",""],[" (1)","s"]]]],"f":[["(1)","Ibn Abi Shaybah, Ibn Rahway, Abd bin Humayd, Haakim and others."]]},{"b":[["n",[["حضرت ابو ادریس خولانیؒ","b"],[" کہتے ہیں کہ پھر حضورؐ نے فرمایا اے ابوبکر! (دنیا میں) جو ناگواریاں دیکھتے ہو وہ برے کاموں کی وجہ سے پیش آتی ہیں اور نیک کاموں کا بدلہ جمع کیا جا رہا ہے جو تمہیں قیامت کے دن دیا جائے گا، اور اس بات کی تصدیق ",""],["ٱللَّٰه","a"],[" کی کتاب کی اس آیت سے ہوتی ہے:",""]]],["q",[["وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍ  (سورۃ الشوریٰ: ۳۰)","a"]]],["p",[["ترجمہ: \"اور تم کو (اے گناہ گارو) جو کچھ مصیبت پہنچتی ہے تو وہ تمہارے ہی ہاتھوں کے کیے ہوئے کاموں سے (پہنچتی ہے) اور بہت سے تو درگزر ہی کر دیتا ہے۔\"",""],[" (2)","s"]]]],"f":[["(2)","Ibn Mardway, as quoted in Kanzul Ummaal (Vol.1 Pg.275)."]]},{"b":[["n",[["حضرت ابوبکر صدیقؓ","b"],[" فرماتے ہیں کہ میں حضورؐ کے پاس تھا تو یہ آیت نازل ہوئی:",""]]],["q",[["مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ وَلَا يَجِدْ لَهُۥ مِن دُونِ ٱللَّهِ وَلِيًّا وَلَا نَصِيرًا  (سورۃ النساء: ۱۲۳)","a"]]],["p",[["ترجمہ: \"جو شخص کوئی برا کام کرے گا وہ اس کے عوض میں سزا دیا جائے گا اور اس شخص کو خدا کے سوا نہ کوئی یار ملے گا نہ مددگار ملے گا۔\" حضورؐ نے فرمایا اے ابوبکر! مجھ پر جو آیت نازل ہوئی کیا وہ تمہیں میں نہ پڑھا دوں؟ میں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! ضرور پڑھا دیں؛ چنانچہ حضورؐ نے مجھے وہ آیت پڑھا دی۔ یہ آیت سنتے ہی مجھے ایسے محسوس ہوا کہ جیسے میری کمر ٹوٹ گئی ہے جس کی وجہ سے میں نے انگڑائی لی۔ حضورؐ نے فرمایا اے ابوبکر! تمہیں کیا ہوا؟ میں نے کہا ہم میں سے کون ایسا ہے جس نے برے کام نہ کیے ہوں؟ اور ہم جو بھی برا کام کریں گے کیا ہمیں اس کا بدلہ ضرور ملے گا؟ حضورؐ نے فرمایا اے ابوبکر! تمہیں اور مومنوں کو برے کاموں کا بدلہ تو دنیا ہی میں مل جائے گا اور تم اپنے رب سے اس حال میں ملاقات کرو گے (یعنی مرتے وقت یہ حالت ہوگی) کہ تم پر کوئی گناہ نہ ہوگا اور دوسروں کے گناہوں کو جمع کیا جاتا رہے گا اور انہیں ان گناہوں کا بدلہ قیامت کے دن دیا جائے گا۔",""],[" (3)","s"]]]],"f":[["(3)","Abd bin Humayd, Tirmidhi and Ibn Mundhir. Tirmidhi has commented on the chain of narrators."]]},{"b":[["n",[["حضرت ابوبکر صدیقؓ","b"],[" فرماتے ہیں کہ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! مَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ والی آیت کے بعد حال کس طرح ٹھیک ہو سکتا ہے؟ کیونکہ ہم نے جو بھی برا کام کیا ہے اس کا بدلہ ہمیں ضرور ملے گا۔ حضورؐ نے فرمایا اے ابوبکر! ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہاری مغفرت فرمائے، کیا تم بیمار نہیں ہوتے؟ کیا تم کبھی تھکتے نہیں؟ کیا تمہیں کبھی کوئی غم پیش نہیں آتا؟ کیا تمہیں کبھی کوئی مشقت نہیں اٹھانی پڑتی؟ کیا تمہیں کبھی کوئی مصیبت پیش نہیں آتی؟ میں نے عرض کیا جی ہاں سب کچھ پیش آتا ہے۔ حضورؐ نے فرمایا یہی گناہوں کا بدلہ ہے جو تمہیں دنیا میں مل رہا ہے۔",""],[" (4)","s"]]]],"f":[["(4)","Ahmad, Ibn Mundhir, Abu Ya'la, Ibn Hibbaan, Haakim, Bayhaqi and others, as quoted in Kanzul Ummaal (Vol.1 Pg.239)."]]},{"b":[["n",[["حضرت محمد بن منکدرؒ","b"],[" کہتے ہیں کہ ایک آدمی نے حضرت عمر بن خطابؓ سے کہا مجھے ",""],["ٱللَّٰه","a"],[" کی کتاب میں ایک ایسی آیت معلوم ہے جو کہ بہت سخت ہے۔ یہ سن کر حضرت عمرؓ اس کی طرف بڑھے اور اسے کوڑا مارا (ظاہری الفاظ قرآن کے ادب کے خلاف تھے) اور فرمایا تمہیں کیا ہوا؟ تم نے اس آیت کی گہری تحقیق کر لی ہے جس سے تمہیں اس (کے بہت سخت ہونے) کا پتہ چل گیا ہے؟ وہ آدمی چلا گیا۔ اگلے دن حضرت عمرؓ نے اس آدمی سے کہا جس آیت کا تم نے کل ذکر کیا تھا وہ کون سی ہے؟ اس آدمی نے کہا وہ یہ ہے: وَمَن يَعْمَلْ سُوٓءًا يُجْزَ بِهِۦ، لہٰذا ہم میں سے جو بھی کوئی برا کام کرے گا اسے اس کا بدلہ ضرور ملے گا۔ حضرت عمرؓ نے کہا جب یہ آیت نازل ہوئی تھی تو اس وقت ہمیں کچھ عرصہ تک (پریشانی کی وجہ سے) کھانا پینا بالکل اچھا نہیں لگتا تھا، اس کے بعد ",""],["ٱللَّٰه","a"],[" تعالیٰ نے رعایت والی آیت نازل کر دی (پھر ہماری وہ پریشانی ختم ہوئی)، وہ آیت یہ ہے:",""]]],["q",[["وَمَن يَعْمَلْ سُوٓءًا أَوْ يَظْلِمْ نَفْسَهُۥ ثُمَّ يَسْتَغْفِرِ ٱللَّهَ يَجِدِ ٱللَّهَ غَفُورًا رَّحِيمًا  (سورۃ النساء: ۱۱۰)","a"]]],["p",[["ترجمہ: \"اور جو شخص کوئی برائی کرے یا اپنی جان کا ضرر کرے پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ سے معافی چاہے تو وہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کو بڑی مغفرت والا بڑی رحمت والا پائے گا۔\"",""],[" (5)","s"]]]],"f":[["(5)","Ibn Raahway, as quoted in Kanzul Ummaal (Vol.1 Pg.239)."]]},{"b":[["n",[["حضرت ثعلبہؓ","b"],[" فرماتے ہیں کہ حضرت عمرو بن سمرہ بن حبیب بن عبد شمسؓ نے نبی کریم ",""],["ﷺ","a"],[" کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! میں نے فلاں قبیلہ کا ایک اونٹ چوری کیا ہے، مجھے (اس گناہ سے) پاک کر دیں۔ حضورؐ نے اس قبیلہ والوں کے پاس آدمی بھیج کر پتہ کرایا۔ انہوں نے بتایا کہ ہاں ہمارا ایک اونٹ گم ہے؛ چنانچہ حضورؐ کے فرمانے پر حضرت عمرو بن سمرہؓ کا ہاتھ کاٹا گیا۔ حضرت ثعلبہؓ کہتے ہیں جب حضرت عمروؓ کا ہاتھ کٹ کر نیچے گرا اس وقت میں انہیں دیکھ رہا تھا، انہوں نے (اپنے ہاتھ کو خطاب کرتے ہوئے) کہا تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے مجھے تجھ سے پاک کر دیا ورنہ تو نے میرے جسم کو جہنم میں داخل کرنے کا ارادہ کر لیا تھا۔",""]]]],"f":[]},{"b":[["n",[["حضرت حسنؒ","b"],[" کہتے ہیں کہ حضرت عمران بن حصینؓ کے جسم میں ایک بیماری تھی، ان کے چند ساتھی ان کے پاس آئے اور ان میں سے ایک نے کہا آپ کے جسم میں جو ہم بیماری دیکھ رہے ہیں اس کی وجہ سے ہمیں بہت رنج و صدمہ ہے۔ حضرت عمرانؓ نے فرمایا تم جو بیماری دیکھ رہے ہو اس کی وجہ سے غمگین نہ ہو کیونکہ جو بیماری تم دیکھ رہے ہو وہ گناہوں کی وجہ سے ہے، اور جن گناہوں کو ",""],["ٱللَّٰه","a"],[" تعالیٰ ویسے ہی معاف فرما دیتے ہیں وہ تو ان سے کہیں زیادہ ہیں۔ پھر انہوں نے یہ آیت پڑھی: وَمَآ أَصَٰبَكُم مِّن مُّصِيبَةٍ فَبِمَا كَسَبَتْ أَيْدِيكُمْ وَيَعْفُوا۟ عَن كَثِيرٍ۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Maajah, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.56)."]]},{"b":[["n",[["حضرت ابوضمرہ بن حبیبؒ","b"],[" کہتے ہیں کہ جب حضرت ابوبکر صدیقؓ کے ایک بیٹے کی وفات کا وقت قریب آیا تو وہ ایک تکیے کی طرف دیکھنے لگا۔ جب اس کا انتقال ہو گیا تو لوگوں نے کہا ہم نے دیکھا تھا کہ آپ کا بیٹا آنکھوں سے اس تکیہ کی طرف دیکھ رہا تھا۔ جب لوگوں نے تکیہ اٹھایا تو اس کے نیچے پانچ یا چھ دینار ملے۔ یہ دیکھ کر حضرت ابوبکرؓ کف افسوس ملنے لگے اور بار بار اِنَّا لِلّٰہِ وَاِنَّا اِلَیْہِ رَاجِعُوْنَ پڑھتے رہے اور فرماتے رہے میرے خیال میں تو تمہاری کھال ان دیناروں کی سزا برداشت نہیں کر سکتی (کہ تم نے ان کو جمع کر کے رکھا اور انہیں خرچ نہ کیا)۔",""],[" (7)","s"]]]],"f":[["(7)","Ibn Abi Haatim, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.116)."]]},{"b":[["n",[["اور مسلمانوں کو گالی دینے کے عنوان میں یہ گزر چکا ہے کہ ایک آدمی نے حاضر خدمت ہو کر حضورؐ سے اپنے غلاموں (کو سزا دینے) کے بارے میں پوچھا تو آپؐ نے فرمایا کہ جب قیامت کا دن ہوگا تو ان غلاموں نے جو تجھ سے خیانت کی اور تیری نافرمانی کی اور تجھ سے جھوٹ بولا اس کا حساب کیا جائے گا اور تم نے ان کو جو سزا دی اس کا بھی حساب کیا جائے گا۔ اگر تمہاری سزا ان کے جرم کے برابر ہوگی تو معاملہ برابر سرابر ہو جائے گا، نہ تمہیں انعام ملے گا نہ سزا، اور اگر تمہاری سزا ان کے جرم سے کم نکلی تو تمہیں ان پر فضیلت ہو جائے گی، اور اگر تمہاری سزا ان کے جرم سے زیادہ ہوگی تو اس زائد سزا کا تم سے بدلہ لیا جائے گا۔ وہ آدمی یہ سن کر ایک طرف ہو کر زور زور سے رونے لگا۔ حضورؐ نے اس کو فرمایا کیا تم ",""],["ٱللَّٰه","a"],[" تعالیٰ کا یہ ارشاد نہیں پڑھتے:",""]]],["q",[["وَنَضَعُ ٱلْمَوَٰزِينَ ٱلْقِسْطَ لِيَوْمِ ٱلْقِيَٰمَةِ فَلَا تُظْلَمُ نَفْسٌ شَيْـًٔا وَإِن كَانَ مِثْقَالَ حَبَّةٍ مِّنْ خَرْدَلٍ أَتَيْنَا بِهَا وَكَفَىٰ بِنَا حَٰسِبِينَ  (سورۃ الانبیاء: ۴۷)","a"]]],["p",[["ترجمہ: \"اور (وہاں) قیامت کے روز ہم میزان عدل قائم کریں گے (اور سب کے اعمال کا وزن کریں گے) سو کسی پر اصلاً ظلم نہ ہوگا اور اگر (کسی کا) عمل رائی کے دانہ کے برابر بھی ہوگا تو ہم اس کو (وہاں) حاضر کر دیں گے اور ہم حساب لینے والے کافی ہیں۔\" تو اس آدمی نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! مجھے اپنے لیے اور ان غلاموں کے لیے اس سے بہتر صورت نظر نہیں آ رہی ہے کہ میں ان سے الگ ہو جاؤں، اس لیے میں آپؐ کو گواہ بناتا ہوں کہ یہ سب غلام آزاد ہیں۔",""],[" (8)","s"]]]],"f":[["(8)","Tirmidhi, reporting from reliable sources."]]}]},"18":{"lead":[],"stories":[{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ جب یہ آیت نازل ہوئی:",""]]],["q",[["لِّلَّهِ مَا فِى ٱلسَّمَٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ يُحَاسِبْكُم بِهِ ٱللَّهُ ۖ فَيَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۗ وَٱللَّهُ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ  (سورۃ البقرہ: ۲۸۴)","a"]]],["p",[["ترجمہ: \"",""],["ٱللَّٰه","a"],[" تعالیٰ ہی کی ملک ہیں سب جو کچھ آسمانوں میں ہیں اور جو کچھ زمین میں ہیں، اور جو باتیں تمہارے نفسوں میں ہیں اگر تم ان کو ظاہر کرو گے یا پوشیدہ رکھو گے حق تعالیٰ تم سے حساب لیں گے، پھر (بجز کفر و شرک کے) جس کے لیے منظور ہوگا بخش دیں گے اور جس کو منظور ہوگا سزا دیں گے، اور ",""],["ٱللَّٰه","a"],[" ہر شے پر پوری قدرت رکھنے والے ہیں۔\" تو اس سے صحابہ کرامؓ کو بہت گرانی اور پریشانی ہوئی اور آ کر حضورؐ کی خدمت میں دو زانو ہو کر بیٹھ گئے اور عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہمیں کچھ ایسے اعمال کا مکلف بنایا گیا ہے جو ہمارے بس میں ہیں جیسے نماز، روزہ، جہاد اور صدقہ، لیکن اب آپؐ پر یہ آیت نازل ہوئی ہے (اور اس میں ہمیں ایسے اعمال کا مکلف بنایا گیا جو ہمارے بس میں نہیں ہیں)۔ حضورؐ نے فرمایا کیا تم چاہتے ہو کہ تم اس آیت کو سن کر سَمِعْنَا وَعَصَيْنَا (ہم نے ",""],["ٱللَّٰه","a"],[" کا حکم سن لیا لیکن ہم اسے مانیں گے نہیں) کہو جیسے کہ تم سے پہلے تورات اور انجیل والوں نے کہا تھا؟ نہیں، بلکہ تم سَمِعْنَا وَأَطَعْنَا غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ کہو، یعنی ہم نے سن لیا اور مان لیا، اے ہمارے رب! ہم تیری مغفرت چاہتے ہیں اور تیرے پاس ہی لوٹ کر جانا ہے؛ چنانچہ صحابہؓ نے یہ دعا مانگنی شروع کر دی اور جب ان کی زبانیں اس دعا سے مانوس ہو گئیں تو ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس کے بعد یہ آیت نازل فرمائی:",""]]],["q",[["ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ  (سورۃ البقرہ: ۲۸۵)","a"]]],["p",[["ترجمہ: \"اعتقاد رکھتے ہیں رسول (",""],["ﷺ","a"],[") اس چیز کا جو ان کے پاس ان کے رب کی طرف سے نازل کی گئی ہے اور مومنین بھی سب عقیدہ رکھتے ہیں ",""],["ٱللَّٰه","a"],[" کے ساتھ اور اس کے فرشتوں کے ساتھ اور اس کی کتابوں کے ساتھ اور اس کے پیغمبروں کے ساتھ کہ ہم اس کے پیغمبروں میں سے کسی میں تفریق نہیں کرتے، اور ان سب نے یوں کہا کہ ہم نے (آپ کا ارشاد) سنا اور خوشی سے مانا، ہم آپ کی بخشش چاہتے ہیں اے ہمارے پروردگار اور آپ ہی کی طرف (ہم سب کو) لوٹنا ہے۔\" جب صحابہؓ نے حضورؐ کے ارشاد کے مطابق اس طرح کیا تو ",""],["ٱللَّٰه","a"],[" تعالیٰ نے پہلی آیت (کے حکم) کو منسوخ کر دیا اور یہ آیت نازل فرمائی:",""]]],["q",[["لَا يُكَلِّفُ ٱللَّهُ نَفْسًا إِلَّا وُسْعَهَا ۚ لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ ۗ رَبَّنَا لَا تُؤَاخِذْنَآ إِن نَّسِينَآ أَوْ أَخْطَأْنَا  (سورۃ البقرہ: ۲۸۶)","a"]]],["p",[["آخر آیت تک۔ ترجمہ: \"",""],["ٱللَّٰه","a"],[" تعالیٰ کسی شخص کو مکلف نہیں بناتا مگر اسی کا جو اس کی طاقت (اختیار) میں ہو، اس کو ثواب بھی اسی کا ملے گا جو ارادہ سے کرے اور اس پر عذاب بھی اسی کا ہوگا جو ارادہ سے کرے۔ اے ہمارے رب! ہم پر دار و گیر نہ فرمائیے اگر ہم بھول جائیں یا چوک جائیں۔\"",""],[" (1)","s"]]]],"f":[["(1)","Ahmad. Muslim has reported a similar narration."]]},{"b":[["n",[["حضرت مجاہدؒ","b"],[" کہتے ہیں کہ میں نے حضرت ابن عباسؓ کی خدمت میں حاضر ہو کر عرض کیا کہ اے ابو عباس! میں حضرت ابن عمرؓ کے پاس تھا، انہوں نے یہ آیت پڑھی اور پڑھ کر رونے لگے۔ حضرت ابن عباسؓ نے پوچھا کونسی آیت؟ میں نے کہا وَإِن تُبْدُوا۟ مَا فِىٓ أَنفُسِكُمْ أَوْ تُخْفُوهُ ۔ حضرت ابن عباسؓ نے فرمایا جب یہ آیت نازل ہوئی تھی تو اس سے حضورؐ کے صحابہؓ بڑے غمگین اور بہت زیادہ پریشان ہوئے تھے۔ انہوں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ہم تو ہلاک ہو گئے۔ پہلے تو ہم زبان سے جو بولتے تھے اور جو عمل کرتے تھے اسی پر ہمارا مواخذہ ہوتا تھا اور اب اس آیت میں یہ آ گیا ہے کہ دل میں جو خیال آئے گا اس پر بھی ہمارا مواخذہ ہوگا، اور ہمارے دل ہمارے ہاتھ میں نہیں ہیں (اب جو اچھا یا برا خیال از خود ہمارے دل میں آئے گا اس پر بھی ہمارا مواخذہ ہوگا تو ہم ہلاک ہو جائیں گے)۔ اس پر حضورؐ نے ان سے فرمایا تم تو یوں کہو سَمِعْنَا وَأَطَعْنَا۔ چنانچہ صحابہؓ نے سَمِعْنَا وَأَطَعْنَا کہنا شروع کر دیا، پھر آیت آمَنَ ٱلرَّسُولُ سے لے کر لَهَا مَا كَسَبَتْ وَعَلَيْهَا مَا ٱكْتَسَبَتْ تک آیات نازل ہوئیں جن سے پہلا حکم منسوخ ہو گیا اور دل میں جو برے خیالات آتے ہیں ان کو معاف کر دیا گیا اور صرف اعمال پر مواخذہ رہ گیا۔",""]]],["p",[["دوسری روایت میں یہ ہے کہ حضورؐ نے فرمایا تم تو یوں کہو سَمِعْنَا وَأَطَعْنَا وَسَلَّمْنَا، یعنی ہم نے سنا، مان لیا اور تسلیم کیا۔ اس پر ",""],["ٱللَّٰه","a"],[" تعالیٰ نے ان کے دلوں میں ایمان ڈال دیا۔",""],[" (2)","s"]]]],"f":[["(2)","Ahmad. Muslim and Ibn Jareer have reported a similar narration, as quoted in the Tafseer of Ibn Katheer (Vol.1 Pg.338)."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں کہ جب یہ آیت نازل ہوئی:",""]]],["q",[["ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ  (سورۃ الانعام: ۸۲)","a"]]],["p",[["ترجمہ: \"(جو لوگ ایمان رکھتے ہیں) اور اپنے ایمان کو ظلم کے ساتھ مخلوط نہیں کرتے (ایسوں ہی کے لیے امن ہے اور وہی راہ پر چل رہے ہیں)\"، تو یہ آیت حضورؐ کے صحابہؓ پر بہت گراں گزری اور وہ اس سے بہت پریشان ہوئے اور انہوں نے (حضورؐ کی خدمت میں) عرض کیا ہم میں سے کون ایسا ہے جس نے ظلم نہ کیا ہو؟ (چھوٹے موٹے گناہ تو ہو ہی جاتے ہیں)۔ حضورؐ نے فرمایا تم جو سمجھے ہو یہاں ظلم سے مراد وہ نہیں ہے (بلکہ یہاں ظلم سے مراد شرک ہے)، جیسے حضرت لقمانؑ نے اپنے بیٹے سے کہا تھا:",""]]],["q",[["يَٰبُنَىَّ لَا تُشْرِكْ بِٱللَّهِ ۖ إِنَّ ٱلشِّرْكَ لَظُلْمٌ عَظِيمٌ  (سورۃ لقمان: ۱۳)","a"]]],["p",[["ترجمہ: \"بیٹا! ",""],["ٱللَّٰه","a"],[" کے ساتھ کسی کو شریک نہ ٹھہرانا، بے شک شرک کرنا بڑا بھاری ظلم ہے۔\"",""],[" (3)","s"]]]],"f":[["(3)","Ibn Abi Haatim and Bukhaari."]]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],["ؓ","b"],[" فرماتے ہیں کہ جب یہ آیت نازل ہوئی: ٱلَّذِينَ ءَامَنُوا۟ وَلَمْ يَلْبِسُوٓا۟ إِيمَٰنَهُم بِظُلْمٍ تو حضورؐ نے فرمایا مجھے (",""],["ٱللَّٰه","a"],[" کی طرف سے) کہا گیا کہ آپ بھی ان میں سے ہیں۔",""],[" (4)","s"]]]],"f":[["(4)","Ibn Mardway, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.153)."]]},{"b":[["n",[["حضرت صفیہ بنت شیبہؓ","b"],[" فرماتی ہیں کہ ہم حضرت عائشہؓ کے پاس بیٹھی تھیں، ہم نے قریش کی عورتوں کا تذکرہ کیا اور ان کے فضائل بیان کیے۔ حضرت عائشہؓ نے فرمایا واقعی قریش کی عورتوں کو بڑے فضائل حاصل ہیں لیکن ",""],["ٱللَّٰه","a"],[" کی قسم! ",""],["ٱللَّٰه","a"],[" کی کتاب کی تصدیق کرنے اور اس پر ایمان لانے میں انصاری عورتوں سے آگے بڑھا ہوا میں نے کسی کو نہیں دیکھا۔ جب سورۃ نور کی یہ آیت نازل ہوئی:",""]]],["q",[["وَلْيَضْرِبْنَ بِخُمُرِهِنَّ عَلَىٰ جُيُوبِهِنَّ  (سورۃ النور: ۳۱)","a"]]],["p",[["ترجمہ: \"اور اپنے دوپٹے اپنے سینوں پر ڈالے رہا کریں\"، تو انصار مردوں نے واپس گھر جا کر اپنی عورتوں کو وہ حکم سنایا جو ",""],["ٱللَّٰه","a"],[" نے اس آیت میں نازل فرمایا تھا۔ ہر آدمی اپنی بیوی، اپنی بیٹی، اپنی بہن اور اپنی ہر رشتہ دار عورت کو یہ آیت پڑھ کر سناتا۔ ان میں سے ہر عورت سنتے ہی ",""],["ٱللَّٰه","a"],[" کی نازل کردہ آیت پر ایمان لانے اور ان کی تصدیق کرنے کے لیے فوراً کھڑی ہو کر منقش چادر لے کر اس میں لپٹ جاتی؛ چنانچہ حضورؐ کے پیچھے فجر کی نماز میں یہ سب چادروں میں ایسی لپٹی ہوئی آئیں کہ گویا ان کے سروں پر کوے بیٹھے ہوئے ہیں۔",""],[" (5)","s"]]]],"f":[["(5)","Ibn Abi Haatim and Abu Dawood, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.284)."]]},{"b":[["n",[["حضرت مکحولؒ","b"],[" کہتے ہیں کہ ایک بہت بوڑھا آدمی جس کی دونوں بھنویں اس کی آنکھوں پر آ پڑی تھیں، اس نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! ایک ایسا آدمی جس نے بہت بدعہدی اور بدکاری کی اور اپنی جائز ناجائز ہر خواہش پوری کی اور اس کے گناہ اتنے زیادہ ہیں کہ اگر تمام زمین والوں میں تقسیم کر دیے جائیں تو وہ سب کو ہلاک کر دیں، تو کیا اس کے لیے توبہ کی کوئی گنجائش ہے؟ نبی کریم ",""],["ﷺ","a"],[" نے فرمایا کیا تم مسلمان ہو چکے ہو؟ اس نے کہا جی ہاں، میں کلمہ شہادت اشھد ان ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" وحدہ لا شریک لہ و اشھد ان محمدا عبدہ و رسولہ پڑھتا ہوں۔ حضورؐ نے فرمایا جب تک تم ایسے (کلمہ شہادت پڑھتے) رہو گے ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہاری تمام بدعہدیاں اور بدکاریاں معاف کرتے رہیں گے اور تمہاری برائیوں کو نیکیوں سے بدلتے رہیں گے۔ اس بوڑھے نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! میری تمام بدعہدیاں اور بدکاریاں معاف؟ حضورؐ نے فرمایا ہاں، تمہاری تمام بدعہدیاں اور بدکاریاں معاف ہیں۔ یہ سن کر وہ بڑے میاں ",""],["ٱللَّٰه","a"],[" اکبر ",""],["لَا إِلٰهَ إِلَّا ٱللّٰهُلَا إِلٰهَ إِلَّا ٱللّٰهُ","a"],[" کہتے ہوئے پیٹھ پھیر کر (خوش خوش) واپس چلے گئے۔",""],[" (6)","s"]]]],"f":[["(6)","Ibn Abi Haatim."]]},{"b":[["n",[["حضرت ابوفروہؓ","b"],[" فرماتے ہیں کہ میں نے حضورؐ کی خدمت میں حاضر ہو کر عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! آپ ذرا یہ بتائیں کہ ایک آدمی نے سارے گناہ کیے ہیں، کوئی چھوٹا بڑا گناہ نہیں چھوڑا، کیا اس کی توبہ قبول ہو سکتی ہے؟ حضورؐ نے فرمایا کیا تم مسلمان ہو گئے ہو؟ میں نے کہا جی ہاں۔ حضورؐ نے فرمایا اب نیکیاں کرتے رہو اور برے کام چھوڑ دو تو ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہارے تمام گناہوں کو نیکیاں بنا دیں گے۔ میں نے کہا میری تمام بدعہدیاں اور بدکاریاں بھی معاف ہو جائیں گی؟ حضورؐ نے فرمایا ہاں۔ اس پر حضرت ابوفروہؓ چل پڑے اور حضورؐ کی نگاہوں سے اوجھل ہونے تک ",""],["ٱللَّٰه","a"],[" اکبر کہتے رہے۔",""]]]],"f":[]},{"b":[["n",[["حضرت ابوہریرہؓ","b"],[" فرماتے ہیں کہ ایک عورت میرے پاس آئی اور اس نے مجھ سے کہا کیا میری توبہ قبول ہو سکتی ہے؟ میں نے زنا کیا تھا جس سے میرے ہاں بچہ پیدا ہوا، پھر میں نے اس بچے کو قتل کر ڈالا۔ میں نے کہا نہیں (تم نے دو بڑے گناہ کیے ہیں، اس لیے) نہ تو تمہاری آنکھ کبھی ٹھنڈی ہو اور نہ تجھے شرافت و کرامت کبھی حاصل ہو۔ اس پر وہ عورت افسوس کرتی ہوئی اٹھ کر چلی گئی۔ پھر میں نے حضورؐ کے ساتھ فجر کی نماز پڑھی اور اس عورت نے جو کچھ کہا تھا اور میں نے اسے جو جواب دیا تھا وہ سب حضورؐ کو بتایا۔ حضورؐ نے فرمایا تم نے اسے برا جواب دیا۔ کیا تم یہ آیتیں وَٱلَّذِينَ لَا يَدْعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ سے لے کر إِلَّا مَن تَابَ آخر آیت تک نہیں پڑھتے؟",""]]],["q",[["وَٱلَّذِينَ لَا يَدْعُونَ مَعَ ٱللَّهِ إِلَٰهًا ءَاخَرَ ... إِلَّا مَن تَابَ ... وَكَانَ ٱللَّهُ غَفُورًا رَّحِيمًا  (سورۃ الفرقان: ۶۸-۷۰)","a"]]],["p",[["ترجمہ: \"اور جو کہ ",""],["ٱللَّٰه","a"],[" تعالیٰ کے ساتھ کسی اور معبود کی پرستش نہیں کرتے اور جس شخص کے قتل کرنے کو ",""],["ٱللَّٰه","a"],[" نے حرام فرمایا ہے اس کو قتل نہیں کرتے ہاں مگر حق پر، اور وہ زنا نہیں کرتے، اور جو شخص ایسے کام کرے گا تو سزا سے اس کو سابقہ پڑے گا کہ قیامت کے روز اس کا عذاب بڑھتا چلا جائے گا اور وہ اس (عذاب) میں ہمیشہ ذلیل (و خوار) ہو کر رہے گا، مگر جو (شرک و معاصی سے) توبہ کر لے اور ایمان (بھی) لے آئے اور نیک کام کرتا رہے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ ایسے لوگوں کے (گزشتہ) گناہوں کی جگہ نیکیاں عنایت فرمائے گا اور ",""],["ٱللَّٰه","a"],[" تعالیٰ غفور رحیم ہے۔\" پھر میں نے یہ آیتیں اس عورت کو پڑھ کر سنائیں۔ اس نے کہا تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے میری خلاصی کی صورت بنا دی۔",""],[" (7)","s"]]],["p",[["ابن جریر کی ایک روایت میں یہ ہے کہ وہ افسوس کرتے ہوئے ان کے پاس سے چلی گئی اور وہ کہہ رہی تھی ہائے افسوس! کیا یہ حسن جہنم کے لیے پیدا کیا گیا ہے؟ اس روایت میں آگے یہ ہے کہ حضورؐ کے پاس سے حضرت ابوہریرہؓ واپس آئے اور انہوں نے مدینہ کے تمام محلوں اور گھروں میں اس عورت کو ڈھونڈنا شروع کیا، اسے بہت ڈھونڈا لیکن وہ عورت کہیں نہ ملی۔ اگلی رات کو وہ خود حضرت ابوہریرہؓ کے پاس آئی تو حضورؐ نے جو فرمایا تھا وہ حضرت ابوہریرہؓ نے اسے بتایا۔ وہ فوراً سجدے میں گر گئی اور کہنے لگی تمام تعریفیں اس ",""],["ٱللَّٰه","a"],[" کے لیے ہیں جس نے میرے لیے خلاصی کی صورت بنا دی اور جو گناہ مجھ سے سرزد ہو گیا تھا اس سے توبہ کا راستہ بنا دیا۔ اور اس عورت نے اپنی ایک باندی اور اس کی بیٹی آزاد کی اور ",""],["ٱللَّٰه","a"],[" کے سامنے سچی توبہ کی۔",""],[" (8)","s"]]]],"f":[["(7)","Tabraani, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.328)."],["(8)","Ibn Mardway, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.328)."]]},{"b":[["n",[["حضرت تمیم داریؓ کے غلام حضرت ابوالحسنؒ","b"],[" کہتے ہیں کہ جب یہ آیت نازل ہوئی:",""]]],["q",[["وَٱلشُّعَرَآءُ يَتَّبِعُهُمُ ٱلْغَاوُۥنَ  (سورۃ الشعراء: ۲۲۴)","a"]]],["p",[["ترجمہ: \"اور شاعروں کی راہ تو بے راہ لوگ چلا کرتے ہیں\"، تو (مسلمان شعراء) حضرت حسان بن ثابت، حضرت عبد",""],["ٱللَّٰه","a"],[" بن رواحہ اور حضرت کعب بن مالکؓ روتے ہوئے حضورؐ کی خدمت میں حاضر ہوئے اور عرض کیا جب ",""],["ٱللَّٰه","a"],[" تعالیٰ نے اس آیت کو نازل فرمایا تو ",""],["ٱللَّٰه","a"],[" کو معلوم تھا کہ ہم لوگ شعراء ہیں (لہٰذا یہ سخت وعید تو ہمارے لیے ہوئی)۔ اس پر حضورؐ نے یہ آگے والی آیت تلاوت فرمائی:",""]]],["q",[["إِلَّا ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّٰلِحَٰتِ","a"]]],["p",[["ترجمہ: \"مگر جو لوگ ایمان لائے اور اچھے کام کیے۔\" حضورؐ نے فرمایا یہ دونوں باتیں تم لوگوں میں موجود ہیں۔ اور:",""]]],["q",[["وَذَكَرُوا۟ ٱللَّهَ كَثِيرًا","a"]]],["p",[["ترجمہ: \"اور انہوں نے (اپنے اشعار میں) کثرت سے ",""],["ٱللَّٰه","a"],[" کا ذکر کیا۔\" حضورؐ نے فرمایا یہ صفت بھی تم میں موجود ہے۔ اور:",""]]],["q",[["وَٱنتَصَرُوا۟ مِنۢ بَعْدِ مَا ظُلِمُوا۟","a"]]],["p",[["ترجمہ: \"اور انہوں نے بعد اس کے کہ ان پر ظلم ہو چکا ہے (اس کا) بدلہ لیا۔\" حضورؐ نے فرمایا یہ صفت بھی تم میں ہے (لہٰذا یہ وعید تم مسلمان شعراء کے لیے نہیں ہے)۔",""],[" (9)","s"]]]],"f":[["(9)","Ibn Ishaaq, Ibn Abi Haatim and Ibn Jareer, as quoted in the Tafseer of Ibn Katheer (Vol.3 Pg.354)."]]},{"b":[["n",[["حضرت عطاء بن سائبؒ","b"],[" کہتے ہیں کہ سب سے پہلے دن جو میں نے حضرت عبدالرحمن بن ابی لیلیٰؒ کو دیکھا اس کی صورت یہ ہوئی کہ میں نے دیکھا کہ ایک گدھے پر ایک بڑے میاں ایک جنازے کے پیچھے پیچھے جا رہے ہیں، ان کے سر اور داڑھی کے بال سفید ہیں۔ میں نے سنا کہ وہ کہہ رہے ہیں کہ مجھے فلاں بن فلاں صحابی نے بتایا کہ انہوں نے حضورؐ کو یہ فرماتے ہوئے سنا کہ جو ",""],["ٱللَّٰه","a"],[" سے ملنا پسند کرتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے ملنے کو پسند فرماتے ہیں اور جو ",""],["ٱللَّٰه","a"],[" سے ملنے کو ناپسند کرتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے ملنے کو ناپسند کرتے ہیں۔ یہ سن کر سب لوگ رونے لگے۔ انہوں نے پوچھا کہ آپ لوگ کیوں رو رہے ہیں؟ لوگوں نے کہا ہم سب ہی (",""],["ٱللَّٰه","a"],[" سے ملنے یعنی) موت کو ناپسند کرتے ہیں۔ انہوں نے فرمایا حضورؐ کے فرمان کا مطلب یہ نہیں ہے بلکہ انسان کے مرنے کا وقت جب قریب آتا ہے تو ",""],["ٱللَّٰه","a"],[" تعالیٰ کا فرمان ہے:",""]]],["q",[["فَأَمَّآ إِن كَانَ مِنَ ٱلْمُقَرَّبِينَ ۝ فَرَوْحٌ وَرَيْحَانٌ وَجَنَّتُ نَعِيمٍ  (سورۃ الواقعہ: ۸۸-۸۹)","a"]]],["p",[["ترجمہ: \"پھر (جب قیامت واقع ہو گی تو) جو شخص مقربین میں سے ہوگا اس کے لیے تو راحت ہے اور (فراغت کی) غذائیں ہیں اور آرام کی جنت ہے\"، تو جب اسے (فرشتوں کی طرف سے) ان نعمتوں کی بشارت دی جاتی ہے تو وہ انسان ",""],["ٱللَّٰه","a"],[" سے ملنے کو پسند کرنے لگ جاتا ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کی ملاقات کو اس سے زیادہ پسند کرنے لگ جاتے ہیں۔ اور ",""],["ٱللَّٰه","a"],[" تعالیٰ کا دوسرا فرمان یہ ہے:",""]]],["q",[["وَأَمَّآ إِن كَانَ مِنَ ٱلْمُكَذِّبِينَ ٱلضَّآلِّينَ ۝ فَنُزُلٌ مِّنْ حَمِيمٍ ۝ وَتَصْلِيَةُ جَحِيمٍ  (سورۃ الواقعہ: ۹۲-۹۴)","a"]]],["p",[["ترجمہ: \"اور جو شخص جھٹلانے والوں (اور) گمراہوں میں سے ہوگا تو کھولتے ہوئے پانی سے اس کی دعوت ہوگی اور دوزخ میں داخل ہونا ہوگا\"، تو جب اسے ان تکلیفوں کی بشارت دی جاتی ہے تو وہ ",""],["ٱللَّٰه","a"],[" سے ملاقات کو ناپسند کرنے لگ جاتا ہے اور ",""],["ٱللَّٰه","a"],[" تعالیٰ اس سے ملنے کو اس سے زیادہ ناپسند کرنے لگ جاتے ہیں۔",""]]]],"f":[]},{"b":[["n",[["حضرت عبد","b"],["ٱللَّٰه","a"],[" بن عمرو بن عاصؓ","b"],[" فرماتے ہیں کہ جب یہ آیت نازل ہوئی:",""]]],["q",[["إِذَا زُلْزِلَتِ ٱلْأَرْضُ زِلْزَالَهَا  (سورۃ الزلزال: ۱)","a"]]],["p",[["ترجمہ: \"جب زمین اپنی سخت جنبش سے ہلائی جائے گی\"، تو اس وقت حضرت ابوبکر صدیقؓ وہاں (حضورؐ کے پاس) بیٹھے ہوئے تھے، وہ یہ سورت سن کر رونے لگے۔ حضورؐ نے ان سے فرمایا اگر تم لوگ غلطیاں اور گناہ نہیں کرو گے (اور پھر استغفار نہیں کرو گے) تاکہ ",""],["ٱللَّٰه","a"],[" تعالیٰ تمہیں بخش دے تو پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ ایسے لوگوں کو پیدا کریں گے جو غلطیاں اور گناہ کریں گے (اور استغفار کریں گے) پھر ",""],["ٱللَّٰه","a"],[" تعالیٰ انہیں معاف کر دیں گے۔",""]]]],"f":[]},{"b":[["n",[["حضرت عمرؓ","b"],[" فرماتے ہیں کہ حضورؐ نے مجھ سے فرمایا اے عمر! تمہارا اس وقت کیا حال ہوگا جب تم چار ہاتھ لمبی اور دو ہاتھ چوڑی زمین (یعنی قبر) میں ہو گے اور تم منکر نکیر کو دیکھو گے؟ میں نے عرض کیا یا رسول ",""],["ٱللَّٰه","a"],["! منکر نکیر کون ہیں؟ حضورؐ نے فرمایا یہ قبر میں امتحان لینے والے (دو فرشتے) ہیں جو قبر کو اپنے دانتوں سے کریدیں گے اور ان کے بال اتنے لمبے ہوں گے کہ وہ اپنے بالوں کو روندتے ہوئے آئیں گے اور ان کی آواز زور دار گرج کی طرح ہوگی اور ان کی آنکھیں اچکنے والی بجلی کی طرح چمک رہی ہوں گی۔ ان دونوں کے پاس ایک اتنا بڑا ہتھوڑا ہوگا کہ سارے منی والے مل کر اسے نہ اٹھا سکیں۔ حضورؐ کے ہاتھ میں ایک چھڑی تھی جسے آپؐ ہلا رہے تھے، آپؐ نے اس کی طرف اشارہ کرتے ہوئے فرمایا لیکن ان دونوں کے لیے اسے اٹھانا میری اس چھڑی سے بھی زیادہ آسان ہوگا۔ وہ دونوں تمہارا امتحان لیں گے، اگر تم جواب نہ دے سکے یا تم لڑکھڑا گئے تو پھر وہ ہتھوڑا اس زور سے ماریں گے کہ تم را کھ بن جاؤ گے۔ میں نے کہا یا رسول ",""],["ٱللَّٰه","a"],["! کیا اس وقت میں اسی حالت پر ہوں گا؟ (یعنی اس وقت میرے ہوش و حواس ٹھیک ہوں گے)؟ حضورؐ نے فرمایا ہاں۔ میں نے کہا پھر تو میں ان دونوں سے نمٹ لوں گا۔",""],[" (10)","s"]]],["p",[["ایک روایت میں اس کے بعد یہ ہے کہ حضورؐ نے فرمایا اس ذات کی قسم جس نے مجھے حق دے کر بھیجا ہے! مجھے حضرت جبرائیل علیہ السلام نے بتایا ہے کہ وہ دونوں تمہارے پاس آئیں گے اور تم سے سوال کریں گے تو تم جواب میں کہو گے میرا رب ",""],["ٱللَّٰه","a"],[" ہے، تم بتاؤ تم دونوں کا رب کون ہے؟ اور (حضرت) محمدؐ میرے نبی ہیں، تم دونوں کے نبی کون ہیں؟ اور اسلام میرا دین ہے، تم دونوں کا دین کیا ہے؟ اس پر وہ دونوں کہیں گے دیکھو کیا عجیب بات ہے، ہمیں پتہ نہیں چل رہا ہے کہ ہمیں تمہارے پاس بھیجا گیا ہے یا تمہیں ہمارے پاس بھیجا گیا ہے۔",""],[" (11)","s"]]]],"f":[["(10)","Ahmad, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.301)."],["(11)","Ibn Jareer, as quoted in the Tafseer of Ibn Katheer (Vol.4 Pg.540). Abu Dawood in his Ba'th, Abu Sheikh in his Sunnah, Haakim, Bayhaqi in his Kitaabu Adhaabil Qabr, Isfahaani in his Hujjah and others have also reported it, as quoted in Kanzul Ummaal (Vol.8 Pg.121)."]]},{"b":[["n",[["حضرت ابوبحریہ کندیؒ","b"],[" فرماتے ہیں کہ ایک دن حضرت عمر بن خطابؓ باہر تشریف لائے تو دیکھا کہ ایک مجلس ہے جس میں حضرت عثمان بن عفانؓ بھی ہیں۔ حضرت عمرؓ نے فرمایا تمہارے ساتھ ایک آدمی بیٹھا ہوا ہے کہ اگر اس کا ایمان کسی بڑے لشکر میں تقسیم کیا جائے تو ان سب کو کافی ہو جائے گا۔ اس سے حضرت عمرؓ کی مراد حضرت عثمان بن عفانؓ تھے۔",""],[" (12)","s"]]]],"f":[["(12)","Abdul Waahid Maqdasi in his book At-Tabseer, as quoted in Riyaadhun Nudhrah (Vol.2 Pg.34). Ibn Asaakir, as quoted in Muntakhab Kanzul Ummaal (Vol.5 Pg.8)."]]},{"b":[["n",[["اور صحابہ کرامؓ کی صفات کے بارے میں صحابہ کرامؓ کے اقوال کے عنوان میں یہ گزر چکا ہے کہ جب ",""],["حضرت ابن عمرؓ","b"],[" سے پوچھا گیا کہ کیا نبی کریم ",""],["ﷺ","a"],[" کے صحابہؓ ہنسا کرتے تھے؟ انہوں نے فرمایا ہاں، مگر ایمان ان کے دلوں میں پہاڑوں سے بھی بڑا تھا۔",""],[" (13)","s"]]]],"f":[["(13)","Under the heading \"Statements of the Sahabah Concerning Their Qualities\"."]]},{"b":[["n",[["اور مشقتیں اور تکلیفیں برداشت کرنے کے عنوان میں یہ گزر چکا ہے کہ ",""],["حضرت عمارؓ","b"],[" کو مشرکین نے بڑا پکڑا اور اس وقت تک نہیں چھوڑا جب تک انہوں نے ان کے معبودوں کی تعریف نہ کی، تو انہوں نے حضورؐ سے عرض کیا کہ مجھے اتنی تکلیف پہنچائی گئی کہ آخر مجھے مجبور ہو کر آپؐ کی گستاخی کرنی پڑی اور ان کے معبودوں کی تعریف کرنی پڑی۔ آپؐ نے فرمایا تم اپنے دل کو کیسا پاتے ہو؟ انہوں نے کہا اپنے دل کو مطمئن پاتا ہوں۔",""],[" (14)","s"],[" (15)","s"]]]],"f":[["(14)","Under the heading \"Hadhrat Ammaar bin Yaasir and his Family Members Endure Hardships and Difficulties\" and the subheading \"Hadhrat Ammaar is Tortured Until he is Forced to Utter Words of Kufr While his Heart was Content with Imaan\"."],["(15)","Abu Nu'aym in his Hilya, Ibn Sa'd, Ibn Jareer and Bayhaqi, as quoted in the Tafseer of Ibn Katheer (Vol.2 Pg.587)."]]},{"b":[["n",[["اور امیر کا کسی کو اپنے بعد خلیفہ بنانے کے عنوان میں گزر چکا ہے کہ ",""],["حضرت ابوبکرؓ","b"],[" نے فرمایا کیا تم لوگ مجھے میرے رب سے ڈراتے ہو؟ میں کہہ دوں گا اے ",""],["ٱللَّٰه","a"],["! میں نے تیری مخلوق میں سے سب سے بہترین آدمی کو ان کا خلیفہ بنایا تھا۔ دوسری روایت میں یہ ہے کہ آپؓ نے فرمایا میں ",""],["ٱللَّٰه","a"],[" اور حضرت عمرؓ کو تم لوگوں سے زیادہ جانتا ہوں۔",""]]]],"f":[]},{"b":[["n",[["اور بیت المال کے سارے مال کو تقسیم کر دینے کے عنوان میں یہ گزر چکا ہے کہ ایک آدمی نے ",""],["حضرت عمرؓ","b"],[" سے کہا اے امیر المومنین! ہو سکتا ہے کہ کبھی دشمن حملہ آور ہو جائے یا مسلمانوں پر اچانک کوئی مصیبت آ پڑے تو ان ضرورتوں کے لیے اگر آپ اس مال میں سے کچھ بچا کر لیں تو اچھا ہوگا۔ یہ سن کر حضرت عمرؓ نے فرمایا تمہاری زبان پر شیطان بول رہا ہے اور اس کا جواب ",""],["ٱللَّٰه","a"],[" مجھے سکھا رہا ہے اور اس کے شر سے مجھے بچا رہا ہے، اور وہ یہ ہے کہ میں نے ان تمام ضرورتوں کے لیے وہی سب کچھ تیار کیا ہوا ہے جو حضورؐ نے تیار کیا تھا اور وہ ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اور اس کے رسولؐ کی اطاعت (ہر مصیبت کا علاج اور ہر ضرورت کا انتظام ",""],["ٱللَّٰه","a"],[" و رسول کی ماننا ہے)۔ دوسری روایت میں ہے کہ کل کو پیش آنے والی ضرورت کے لیے میں آج ",""],["ٱللَّٰه","a"],[" کی نافرمانی نہیں کر سکتا۔ اور ایک روایت میں یہ ہے کہ میں نے مسلمانوں (کی ضروریات) کے لیے ",""],["ٱللَّٰه","a"],[" کا تقویٰ تیار کیا ہوا ہے۔ ",""],["ٱللَّٰه","a"],[" نے فرمایا ہے:",""]]],["q",[["وَمَن يَتَّقِ ٱللَّهَ يَجْعَل لَّهُۥ مَخْرَجًا ۝ وَيَرْزُقْهُ مِنْ حَيْثُ لَا يَحْتَسِبُ  (سورۃ الطلاق: ۲-۳)","a"]]],["p",[["ترجمہ: \"اور جو شخص ",""],["ٱللَّٰه","a"],[" سے ڈرتا ہے ",""],["ٱللَّٰه","a"],[" تعالیٰ اس کے لیے (مضرتوں سے) نجات کی شکل نکال دیتا ہے اور اس کو ایسی جگہ سے رزق پہنچاتا ہے جہاں اس کا گمان بھی نہیں ہوتا۔\"",""]]]],"f":[]},{"b":[["n",[["صحابہؓ کے مال خرچ کرنے کے شوق کے باب میں یہ گزر چکا ہے کہ جب ",""],["حضرت علیؓ","b"],[" نے سائل کو صدقہ دینے کا ارادہ کیا تو حضرت فاطمہؓ نے کہا وہ چھ درہم ہی تو آپ نے آٹے کے لیے رکھوائے تھے۔ حضرت علیؓ نے کہا کسی بھی بندے کا ایمان اس وقت تک سچا ثابت نہیں ہو سکتا جب تک کہ اس کو جو چیز اس کے پاس ہے اس سے زیادہ اعتماد اس چیز پر نہ ہو جائے جو ",""],["ٱللَّٰه","a"],[" کے خزانوں میں ہے۔",""]]]],"f":[]},{"b":[["n",[["اور مال واپس کرنے کے باب میں یہ گزر چکا ہے کہ ",""],["حضرت عامر بن ربیعہؓ","b"],[" نے کہا مجھے تمہارے زمین کے اس ٹکڑے کی کوئی ضرورت نہیں کیونکہ آج ایک ایسی سورت نازل ہوئی جس نے ہمیں دنیا ہی بھلا دی اور وہ سورت یہ ہے:",""]]],["q",[["ٱقْتَرَبَ لِلنَّاسِ حِسَابُهُمْ وَهُمْ فِى غَفْلَةٍ مُّعْرِضُونَ  (سورۃ الانبیاء: ۱)","a"]]],["p",[["ترجمہ: \"ان (منکر) لوگوں سے ان کا (وقت) حساب نزدیک آ پہنچا اور یہ (ابھی) غفلت (ہی) میں (پڑے ہیں اور) اعراض کیے ہوئے ہیں۔\"",""]]]],"f":[]},{"b":[["n",[["اور ",""],["حضرت عائشہؓ","b"],[" کی حدیث گزر چکی ہے کہ حضرت اسید بن حضیرؓ بڑی فضیلت والے لوگوں میں سے تھے، وہ کہا کرتے تھے کہ میں تین حالتوں میں جیسا ہوتا ہوں اگر ہر وقت ویسا رہوں تو یقیناً جنت والوں میں سے ہو جاؤں اور مجھے اس میں کوئی شک نہ رہے۔ ایک وہ حالت جب کہ میں خود قرآن پڑھ رہا ہوں یا کوئی اور قرآن پڑھ رہا ہو اور میں سن رہا ہوں۔ دوسری وہ حالت جب کہ میں حضورؐ کا خطبہ سن رہا ہوں۔ تیسری وہ حالت جب کہ میں کسی جنازے میں شریک ہوں اور جب بھی میں کسی جنازے میں شریک ہوتا ہوں تو اپنے دل میں صرف یہی سوچتا ہوں کہ اس جنازے کے ساتھ کیا ہوگا اور یہ جنازہ کہاں جا رہا ہے؟",""],[" (16)","s"]]]],"f":[["(16)","Haakim, reporting from reliable sources as confirmed by Dhahabi."]]}]}}});
